// AUTO-GENERATED by build.py — do not edit. Source: data/mci/**
window.MCI_DATA = {"manifest":{"id":"mci","title":"MCI — Mass Casualty Incident Management","subtitle":"Tactical MCI Ops for EMS","version":"1.0.0","edition":"Aligned to NIMS/ICS, JESIP METHANE, START/JumpSTART, CDC SALT, TECC and DOT ERG field practice","description":"A tactical, high-yield MCI course for EMS built as an incident timeline: understand the event, own the first ten minutes, command it, triage it, treat and move patients, survive CBRNE and hostile threats, then demobilize and recover. Each chapter has a tight summary, field pearls, red flags, memory aids, flashcards, course-style quizzes, scenarios, algorithms, tables — and timed game-style drills for triage, METHANE radio reports, and officer roles.","icon":"siren","color":"#c8102e","accentColor":"#1f6feb","estimatedHours":9,"difficulty":"Beginner to Advanced","certification":"Educational reviewer (no certifying body)","audience":["EMR","EMT","AEMT","Paramedic","EMS Supervisor","Flight / Critical Care","ED Nurse & Physician"],"prerequisites":["BLS-level patient assessment","Basic familiarity with local EMS protocols"],"contentTypes":["summary","flashcards","quizzes","scenarios","algorithms","tables","drills"],"chapters":[{"id":"c01","number":1,"title":"MCI Fundamentals & Types of Disasters","section":"① Mission Briefing","difficulty":"Beginner"},{"id":"c02","number":2,"title":"First-Due: Size-Up, CSCATTT & METHANE","section":"② The First 10 Minutes","difficulty":"Beginner"},{"id":"c03","number":3,"title":"ICS for EMS: Command Structure","section":"② The First 10 Minutes","difficulty":"Intermediate"},{"id":"c04","number":4,"title":"MCI Officer Roles & Action Cards","section":"② The First 10 Minutes","difficulty":"Intermediate"},{"id":"c05","number":5,"title":"Scene Layout: Zones, Staging & Patient Flow","section":"② The First 10 Minutes","difficulty":"Intermediate"},{"id":"c06","number":6,"title":"Triage I: START & JumpSTART","section":"③ Triage","difficulty":"Beginner"},{"id":"c07","number":7,"title":"Triage II: SALT, Tags & Re-Triage","section":"③ Triage","difficulty":"Intermediate"},{"id":"c08","number":8,"title":"Treatment Area, Transport & Hospital Distribution","section":"④ Treat & Move","difficulty":"Intermediate"},{"id":"c09","number":9,"title":"CBRNE I: HazMat Recognition, PPE & Decon","section":"⑤ CBRNE","difficulty":"Intermediate"},{"id":"c10","number":10,"title":"CBRNE II: Chemical Agents & Antidotes","section":"⑤ CBRNE","difficulty":"Advanced"},{"id":"c11","number":11,"title":"CBRNE III: Biological & Radiological/Nuclear","section":"⑤ CBRNE","difficulty":"Advanced"},{"id":"c12","number":12,"title":"Explosive & Hostile Events: Blast, Active Shooter, TECC","section":"⑤ CBRNE","difficulty":"Advanced"},{"id":"c13","number":13,"title":"Special MCIs: Collapse, Crush, Crowds & Natural Disasters","section":"⑥ Special Ops & Recovery","difficulty":"Advanced"},{"id":"c14","number":14,"title":"Demobilization, Recovery & Responder Resilience","section":"⑥ Special Ops & Recovery","difficulty":"Beginner"}]},"chapters":{"c01":{"id":"c01","title":"MCI Fundamentals & Types of Disasters","shortTitle":"Fundamentals","estimatedStudyTime":30,"difficulty":"Beginner","learningObjectives":["Define an MCI by the resource gap, not by a casualty number.","Classify incidents: open vs closed, simple vs compound, compensated vs uncompensated.","Classify disasters (natural vs human-made) and predict the dominant injury pattern of each.","Explain the mindset shift from 'best care for one' to 'most good for the most'."],"summary":[{"title":"What Makes It an MCI","content":"An MCI is any incident where the number or severity of casualties exceeds the resources immediately available. Three patients on a rural road with one ambulance can be an MCI; 15 patients downtown with 20 units nearby may not be. Local plans set activation tiers (e.g., Level 1/2/3 by patient count) — know yours, but the definition is always the resource gap. A disaster is an MCI that overwhelms the whole community's response capacity and needs outside help."},{"title":"The Mindset Shift","content":"Daily EMS = maximum care for each patient. MCI = the greatest good for the greatest number. You triage, do seconds-long lifesaving interventions, and move on. CPR on an arrested patient, full spinal packaging, and detailed exams are luxuries the scene can't afford until resources catch up."},{"title":"Classify the Incident in One Line","content":"CLOSED (contained) — finite, known number of victims, e.g., a bus crash. OPEN (uncontained) — victims keep appearing or the number is unknown, e.g., earthquake, ongoing shooter, toxic plume. SIMPLE — infrastructure intact (roads, hospitals, comms work). COMPOUND — infrastructure itself is damaged (hospital flooded, roads cut, cell network down). COMPENSATED — the system can absorb it with extra resources. UNCOMPENSATED — it can't, even with mutual aid → disaster. Open + compound is the worst case: expect long scene times and self-sufficiency."},{"title":"Types of Disasters","content":"NATURAL: geophysical (earthquake, tsunami, volcano, landslide), hydrological (flood), meteorological (hurricane/cyclone, tornado, blizzard), climatological (heat wave, wildfire, drought), biological (pandemic, epidemic). HUMAN-MADE: technological/industrial (HazMat release, explosion, structural collapse, utility failure), transportation (bus, rail, air, maritime), intentional (terrorism/CBRNE, active shooter, vehicle ramming, armed conflict), and mass-gathering/crowd events (crowd crush, stampede). Tactically: the disaster TYPE predicts the INJURY pattern, the HAZARDS to you, and whether infrastructure is intact."},{"title":"The Disaster Cycle (One Paragraph)","content":"Mitigation (reduce risk) → Preparedness (plans, drills, caches, training) → Response (the incident) → Recovery (restore services, debrief, rebuild) → back to mitigation. EMS lives in response, but MCIs are won in preparedness: knowing your MCI plan, your role cards, and where the triage tags are BEFORE the call."}],"clinicalPearls":["MCI is a math problem: patients > resources. Declare it early — standing down an over-call is cheap; catching up an under-call is not.","Disaster type → injury pattern: earthquake = crush; flood = drowning/hypothermia/trauma from debris; tornado = penetrating debris + blunt; blast = blast lung + fragments; crowd crush = compressive asphyxia.","In an OPEN incident, never assume the patient count you were dispatched to is the final count.","Compound incidents (infrastructure damaged) mean plan for long holds on scene and limited hospital capacity.","Hurricanes and ice storms kill AFTER the event too: CO poisoning from generators, falls during cleanup, chainsaw injuries, missed dialysis and oxygen."],"redFlags":["Waiting for a 'certain number' of patients before declaring an MCI.","Treating the first critical patient you find and losing the scene.","Assuming hospitals and roads are working in a regional disaster.","Repeated incidents or a second explosion — consider an intentional event with secondary devices."],"commonMistakes":["Defining MCI by a fixed number rather than the resource gap.","Confusing closed (finite victims) with open (ongoing/unknown victims).","Forgetting the 'after-disaster' injury wave (CO, cleanup trauma, chronic disease decompensation)."],"memoryAids":["MCI = Patients > Resources. Disaster = Community > Capacity.","Open/Closed = how many victims. Simple/Compound = is infrastructure intact.","N-H split: Natural (Geo-Hydro-Meteo-Climato-Bio) vs Human-made (Tech, Transport, Terror, Crowds)."],"decisionTrees":[{"title":"Is This an MCI?","content":"Arrive / receive report\n  → Casualties (number × severity) > resources immediately available?\n     → NO: routine operations, but re-assess as info arrives\n     → YES: DECLARE MCI\n        → Closed or open? (finite vs ongoing/unknown victims)\n        → Simple or compound? (infrastructure intact?)\n        → Hazards? (CBRNE, structural, violence)\n        → Send METHANE report and activate MCI plan / request resources"}],"references":["NIMS / ICS doctrine (FEMA)","WHO / CRED disaster classification (natural hazard groups)","UK JESIP / MIMMS major-incident principles"]},"c02":{"id":"c02","title":"First-Due: Size-Up, CSCATTT & the METHANE Report","shortTitle":"First-Due & METHANE","estimatedStudyTime":35,"difficulty":"Beginner","learningObjectives":["Perform the first-arriving crew's actions without getting pulled into patient care.","Apply CSCATTT as the order of MCI priorities.","Deliver a complete METHANE report in under 60 seconds.","Use plain-language radio and structured follow-up updates (CAN)."],"summary":[{"title":"The First Crew's Job Is Not Treatment","content":"The first ambulance sets the tone for the entire incident. The most common failure is the first crew treating the first patient they reach — the scene then runs without command for 20 minutes. First-due rule: one crew member takes COMMAND and the radio; the other does a rapid RECON/global triage. You stay visible, stay with the vehicle/command point, and you do not disappear into a patient."},{"title":"Safety 1-2-3: Self → Scene → Survivors","content":"Stop short. Park upwind, uphill, upstream, out of the traffic lane and away from obvious hazards (fuel, wires, smoke, crowds, unstable structure). Look for clues of CBRNE or violence: multiple people down without trauma, odd odors or clouds, dead animals, repeated blasts, gunfire. If it smells, looks, or feels wrong — withdraw and report. A dead or injured rescuer converts a resource into a patient."},{"title":"CSCATTT — The Order of Business","content":"Command & Control → Safety → Communication → Assessment → Triage → Treatment → Transport. The first four (CSCA) are MANAGEMENT; the last three (TTT) are MEDICAL SUPPORT. You cannot do TTT well until CSCA is in place. It's a priority list, not a pause — in reality you do several at once, but if something must slip, it's treatment, never command or safety."},{"title":"METHANE: The Universal First Report","content":"M — Major incident DECLARED (or 'standby'). E — EXACT location (grid/address, landmarks, which side). T — TYPE of incident (what happened: RTC, explosion, collapse, chemical). H — HAZARDS present and potential (fire, fuel, chemical, structural, violence, weather). A — ACCESS and egress routes (best approach, RV point, staging). N — NUMBER, severity and type of casualties (estimate: 'approx 25: 5 red, 8 yellow, 12 green'). E — EMERGENCY services present and REQUIRED (who's on scene, what you need). Short, factual, estimates are fine — a fast 80%-right report beats a slow perfect one."},{"title":"Radio Discipline","content":"Plain language, no 10-codes (NIMS standard — mutual-aid units won't share your codes). Name the incident ('Riverside Bus Command') so every unit knows who to call. Think before you key; one message, one purpose; repeat back critical orders. After METHANE, send structured updates (e.g., CAN: Conditions, Actions, Needs) every 10–15 minutes or when anything big changes."}],"clinicalPearls":["First-in doesn't get sucked in: command, recon, report — patients come next.","Say the words 'MASS CASUALTY INCIDENT' / 'MAJOR INCIDENT DECLARED' on the radio. Ambiguity delays the cavalry.","Give casualty numbers as estimates with severity split — 'approximately' is a perfectly good word.","Your ambulance is a landmark: park it where it can serve as a visible command point without blocking the ambulance loop.","Name the staging/rendezvous point in your first report so incoming units don't self-dispatch into the scene."],"redFlags":["Multiple casualties down with no obvious trauma → think chemical; stop, withdraw upwind, report (Step 1-2-3).","A second explosion, gunfire, or suspicious packages → secondary-device/hostile threat; stage away.","No one has said 'I am command' within the first minutes.","Radio traffic chaos: every unit talking, no named incident, codes being used."],"commonMistakes":["First crew starting CPR or packaging the first patient.","Waiting for exact numbers before sending METHANE.","Forgetting the 'H' (hazards) and 'A' (access) — incoming units drive into danger or gridlock.","Parking in the hazard zone or blocking the only access road."],"memoryAids":["Safety 1-2-3: Self, Scene, Survivors.","CSCATTT: 'Can Some Cops And Teachers Train Together?' — CSCA = manage, TTT = medical.","METHANE: Major — Exact location — Type — Hazards — Access — Number — Emergency services.","Updates = CAN: Conditions, Actions, Needs."],"decisionTrees":[{"title":"First-Due Crew: First 3 Minutes","content":"Approach\n  → Stop short, upwind/uphill, out of traffic; look for CBRNE/violence clues\n     → Clues present: withdraw, report, wait for specialist teams\n     → Scene appears safe:\n        Crew member 1 (COMMAND): announce arrival + 'MCI declared' + name incident\n           → METHANE report → request resources → name staging\n        Crew member 2 (RECON/TRIAGE): 360° look + global sort (walk/wave)\n           → feed numbers back to command\n  → Hand over roles (triage/treatment/transport) as units arrive"}],"references":["JESIP Joint Doctrine — M/ETHANE model","MIMMS (Major Incident Medical Management and Support) — CSCATTT","NIMS — plain-language communications"]},"c03":{"id":"c03","title":"ICS for EMS: Command Structure","shortTitle":"ICS for EMS","estimatedStudyTime":35,"difficulty":"Intermediate","learningObjectives":["Apply the ICS principles that matter on an EMS scene: unity of command, span of control, modular growth, common terminology.","Distinguish command staff from general staff and name each position.","Map the EMS/Medical Branch structure under Operations.","Perform a correct transfer of command and explain unified command."],"summary":[{"title":"Why ICS","content":"ICS (Incident Command System, part of NIMS) gives every agency the same org chart, titles, and language, so a medic from another county can plug into your scene in seconds. It grows and shrinks with the incident (modular): a 5-patient crash may be IC + Triage only; a stadium collapse fills the whole chart. Every position not filled is held by the person above it — so the IC owns everything until delegated."},{"title":"The Principles You Actually Use","content":"Unity of command: everyone reports to ONE supervisor. Span of control: one supervisor manages roughly 3–7 people/units, ~5 is optimal — beyond that, add a layer. Common terminology: plain language and standard titles. Management by objectives via an Incident Action Plan (IAP; verbal for small incidents). Accountability: check-in, assignments tracked. Chain of command: orders flow down, info flows up — no freelancing."},{"title":"Command Staff vs General Staff","content":"COMMAND STAFF (report directly to IC, title = Officer): Safety Officer (can stop unsafe acts immediately), Public Information Officer (media), Liaison Officer (other agencies). GENERAL STAFF (title = Section Chief): Operations (does the work — EMS lives here), Planning (situation, resources, IAP, documentation), Logistics (supplies, facilities, comms equipment, food, responder medical), Finance/Admin (costs, time, claims). Memory: 'Officers advise, Chiefs execute'."},{"title":"ICS Titles by Level","content":"Incident Commander → Section = Chief → Branch = Director → Division (geographic) / Group (functional) = Supervisor → Unit = Leader → Strike Team / Task Force = Leader → Staging Area = Manager. Division = WHERE (Division A = front of building, Division 2 = 2nd floor). Group = WHAT (Medical Group, Rescue Group). The EMS piece is usually the Medical Group (or Medical Branch when large)."},{"title":"EMS Inside ICS","content":"Operations Section → Medical Branch Director (large incidents) → Medical Group Supervisor → Triage Unit Leader (with triage teams; morgue manager), Treatment Unit Leader (with Red/Yellow/Green treatment managers), Patient Transportation Unit/Group Leader (with Medical Communications Coordinator and ground/air ambulance coordinators), plus Medical Supply Coordinator. Staging Area Manager reports to Operations (or IC early). Chapter 4 covers each role's action card."},{"title":"Transfer of Command & Unified Command","content":"Transfer of command: face-to-face whenever possible; brief situation, objectives, hazards, resources, org chart; announce the change on the radio so everyone knows who is IC now. Arriving senior officers don't automatically take over — they assume command only after a formal transfer. Unified Command: when multiple agencies share jurisdiction (fire, police, EMS, public health), their commanders co-locate at one command post and produce ONE set of objectives/IAP — each agency keeps authority over its own people."}],"clinicalPearls":["If you're the first EMS unit, you ARE every ICS position until you hand one off.","When your span exceeds ~5, don't work harder — add a supervisor layer.","Division = geography (where), Group = function (what).","The Safety Officer can halt any unsafe act on the spot without waiting for the IC.","A freelancer — a crew acting without assignment — is a safety and accountability hazard, no matter how well-intentioned."],"redFlags":["Two people both believing they're IC (no formal transfer).","One supervisor running 12 crews directly.","Units self-dispatching into the scene instead of checking in at staging.","Agencies running parallel command posts with conflicting objectives."],"commonMistakes":["Calling a Section 'Branch' or a Unit 'Group' — titles carry meaning.","Forgetting that unfilled positions stay with the supervisor above.","Transferring command by radio only, without a briefing.","Thinking unified command means one agency gives up its authority."],"memoryAids":["Command Staff = 'SLP': Safety, Liaison, PIO — they're Officers.","General Staff = 'OPLF' (Operations, Planning, Logistics, Finance) — 'Only Paramedics Love Food' — they're Chiefs.","Titles ladder: Chief → Director → Supervisor → Leader → Manager (staging). 'Cheerful Directors Supervise Lazy Managers.'","Span of control: 'Five alive' (3–7)."],"decisionTrees":[{"title":"Scale the Org Chart","content":"Small MCI (≤ ~10 pts)\n  → IC (first EMS officer) + Triage + Transport\nMedium MCI\n  → IC → Medical Group Supervisor → Triage / Treatment / Transport Unit Leaders + Staging\nLarge / multi-agency MCI\n  → Unified Command + Command Staff (Safety, PIO, Liaison)\n  → Operations Section Chief → Medical Branch Director → Medical Groups / Divisions\n  → Planning, Logistics, Finance as needed\nRule: span of control > ~5–7 → add a layer"}],"references":["FEMA NIMS (2017) and ICS-100/200 curriculum","FIRESCOPE ICS Multi-Casualty Branch organization"]},"c04":{"id":"c04","title":"MCI Officer Roles & Action Cards","shortTitle":"Officer Roles","estimatedStudyTime":40,"difficulty":"Intermediate","learningObjectives":["State the mission, first actions, and 'never do' for each MCI officer role.","Describe how Triage → Treatment → Transport → Staging hand patients and vehicles to each other.","Run a transport log and distribute patients across hospitals.","Use vests and action cards to make roles visible and repeatable."],"summary":[{"title":"Roles Beat Heroics","content":"In an MCI nobody is 'just a medic'. Each officer has a narrow mission and hands off the rest. Wear the vest (it's your ID), take the action card (it's your checklist), and report only to your supervisor. Typical ICS titles: Medical Group Supervisor (often 'EMS Command/IC' in small incidents), Triage Unit Leader, Treatment Unit Leader, Patient Transportation Unit Leader, Staging Area Manager — usually called Triage/Treatment/Transport/Staging Officer on scene."},{"title":"Incident Commander (EMS Command)","content":"Mission: own the whole incident. First actions: establish and name command at a fixed, visible command post; declare MCI; METHANE; set objectives (life safety, triage, treat, transport, hazard control); assign Triage, Transport, Treatment, Staging; coordinate with fire/police (unified command); request resources early; manage span of control. Never: get hands-on with a patient, leave the command post without handover."},{"title":"Triage Officer","content":"Mission: find and sort every casualty, fast. First actions: global sort (walk/wave), direct triage teams in pairs, ensure every patient is tagged with a category, perform only seconds-long lifesaving interventions (tourniquet, open airway, position), report counts by color to the IC, direct litter teams to move reds first to the treatment area, re-triage. Coordinates with morgue manager for the dead (leave in place unless obstructing access). Never: stop to treat or transport."},{"title":"Treatment Officer","content":"Mission: keep patients alive until transport. First actions: set up the treatment area (red/yellow/green/black zones) near the loading zone and away from hazards; assign Red/Yellow/Green treatment managers; do secondary triage on arrival; provide focused interventions (airway, O2, bleeding control, splinting, IV only when it doesn't slow flow); prioritize and hand patients to the Transport Officer; request supplies through logistics. Never: let the treatment area become a holding hospital — flow out is the goal."},{"title":"Transport Officer","content":"Mission: right patient, right hospital, right vehicle, tracked. First actions: set up the ambulance loading zone; get hospital capacity via the Medical Communications Coordinator/hospital coordination center; call units forward from staging; assign destination per patient category and hospital capability; keep a transport log (tag #, category, unit, destination, time out); spread patients across hospitals — don't dump everyone at the closest; use buses for greens with a medic aboard. Never: let crews choose their own hospital or self-dispatch."},{"title":"Staging Officer & Support Roles","content":"STAGING: set staging at a safe distance with easy one-way access; check in every unit (unit ID, level, crew); crews stay with vehicles, keys in; release units only on request from Transport; tell IC when available units drop to a set level. SAFETY OFFICER: scans hazards, enforces PPE, can stop unsafe acts. MEDICAL COMMUNICATIONS: single voice to hospitals (capacity, notifications). MORGUE MANAGER: dead stay in place where possible; secure, out of view; coordinate with law enforcement/ME. LOGISTICS/SUPPLY: MCI caches, O2, litters. REHAB: monitor responders."}],"clinicalPearls":["Your vest is your badge in chaos. No vest = nobody knows to bring you the problem.","Assign Transport EARLY. The bottleneck in most MCIs is getting patients off scene, not triaging them.","Triage officer's hands touch patients for seconds; treatment officer's for minutes; transport officer's not at all — they touch paper and radios.","The dead are not moved unless they block access to the living — it's also a crime/identification scene.","A transport log entry per patient (tag # → unit → hospital → time) is how families and hospitals find people later."],"redFlags":["Ambulances driving into the scene, loading whoever is nearest, and choosing their own hospital.","The closest hospital receiving every patient while others sit empty.","The IC kneeling beside a patient.","Treatment area filling up with nobody leaving (transport bottleneck)."],"commonMistakes":["Triage officer stopping to start IVs.","No staging — units block the access road.","No transport log — patients 'disappear' into the system.","Running out of litter-bearers — use green patients and non-medical responders to carry."],"memoryAids":["Triage FINDS, Treatment KEEPS, Transport MOVES, Staging HOLDS, Command THINKS.","Transport log = 'Tag–Truck–Target–Time'.","Staging rules: 'Check in, keys in, crews in.'"],"decisionTrees":[{"title":"Patient & Vehicle Flow Between Officers","content":"Casualty location\n  → TRIAGE OFFICER: sort, tag, LSI, count → litter teams carry reds first\n     → TREATMENT AREA (Treatment Officer): secondary triage, stabilize, prioritize\n        → TRANSPORT OFFICER: request unit from STAGING, assign hospital, log\n           → LOADING ZONE → ambulance → hospital\nSTAGING OFFICER: holds vehicles, sends them only when Transport calls\nCOMMAND (IC): coordinates all of the above; resources, safety, hospitals via Med Comms"}],"references":["FIRESCOPE Multi-Casualty Incident (MCI) position checklists","FEMA ICS / NIMS — position titles and responsibilities"]},"c05":{"id":"c05","title":"Scene Layout: Zones, Staging & Patient Flow","shortTitle":"Scene Layout","estimatedStudyTime":30,"difficulty":"Intermediate","learningObjectives":["Define hot, warm, and cold zones and what happens in each.","Place the command post, treatment area, loading zone, staging, morgue, and helicopter LZ correctly.","Design a one-way patient and vehicle flow.","Apply basic stand-off distances for hazardous and explosive threats."],"summary":[{"title":"Three Zones","content":"HOT (exclusion/direct threat): immediate danger — fire, collapse, contamination, active violence. Only properly protected specialist teams (e.g., HazMat, USAR, law enforcement/Rescue Task Force under escort). WARM (contamination reduction/indirect threat): decon corridor, casualty collection points, rapid lifesaving care under protection. COLD (support): command post, treatment area, transport loading, staging, rehab, media. Zones are set by the hazard, marked visibly, and can move — the wind shifts, the shooter moves, the building settles."},{"title":"Where Everything Goes","content":"Command post: cold zone, visible, close enough to see the scene. Treatment area: cold zone, upwind/uphill, flat, lit, sheltered, with room to grow, one way in/one way out, next to the loading zone. Ambulance loading zone: at the treatment area exit, on a one-way vehicle loop — no backing up. Staging: further out, on the approach route, out of sight of the hazard, with space to park in rows. Green (walking wounded) collection point: separate, supervised. Morgue: cold zone, out of public view, secure. Helicopter LZ: cold zone, away from the treatment area (rotor wash), clear of wires/debris."},{"title":"One-Way Flow","content":"Patients flow one direction: Hot → (CCP) → Warm (decon if needed) → Treatment (Red/Yellow/Green) → Loading Zone → Hospital. Vehicles flow one direction: Staging → Loading Zone → Hospital, never back through the scene. Crossing flows (ambulances reversing into crowds, litters weaving through traffic) cause delays and injuries. Draw it on the hood of your rig in the first 10 minutes."},{"title":"Stand-Off Distances (Quick Reference)","content":"HazMat: use the DOT Emergency Response Guidebook (ERG) initial isolation and protective action distances; approach upwind, uphill, upstream. Suspected explosive: stay out of line-of-sight, use cover, don't use radios/cell phones next to a suspected device, and use the bomb-threat stand-off chart (e.g., pipe bomb ≈ 70 ft mandatory evacuation / ≈ 1,200 ft shelter-or-evacuate outdoors; car bomb ≈ 320 ft / ≈ 1,500 ft). Always ask: is the staging area itself a target (secondary device)?"}],"clinicalPearls":["Treatment area next to the loading zone, red section closest to the exit — reds leave first.","Staging should be invisible from the hazard and reachable without driving through the scene.","Greens wander. Give them a place, a person in charge, and a reason to stay (water, shelter, phone charging).","Rotor wash throws debris and tarps — keep the LZ well away from the treatment area.","Re-check the wind every 15 minutes in any chemical or fire incident — zones move."],"redFlags":["Treatment area downwind of smoke or a chemical release.","Ambulances reversing through pedestrian areas.","Staging in an obvious, crowded spot in a terrorist incident — potential secondary-device target.","Unprotected responders entering the hot zone to 'just grab one'."],"commonMistakes":["Placing the treatment area so close it must be moved when the hazard grows.","Forgetting space to expand the treatment area as patient numbers rise.","Morgue in public view.","No physical markings — tape, cones, flags — so zones exist only in the IC's head."],"memoryAids":["Hot = Hazard, Warm = Wash (decon) & Work fast, Cold = Command & Care.","Upwind, Uphill, Upstream.","Flow is a river — it never runs backward."],"decisionTrees":[{"title":"Scene Layout Sketch (Typical)","content":"      WIND →\n[ HOT ZONE: incident ]\n        ↓ litters / CCP\n[ WARM: decon corridor ]\n        ↓\n[ COLD: TREATMENT AREA ]  RED | YELLOW | GREEN    (BLACK separate, screened)\n        ↓ exit\n[ LOADING ZONE ] ←— one-way loop —— [ STAGING (out of sight) ]\n        ↓\n    Hospitals\nCommand post: cold, visible | LZ: cold, away from treatment"}],"references":["DOT/PHMSA Emergency Response Guidebook (ERG, current edition)","DHS/NCTC Bomb Threat Stand-Off Distances card","FEMA ICS facilities (ICP, staging, base, helibase/helispot)"]},"c06":{"id":"c06","title":"Triage I: START & JumpSTART","shortTitle":"START & JumpSTART","estimatedStudyTime":45,"difficulty":"Beginner","learningObjectives":["Triage an adult with START in under 60 seconds (goal ~30 s).","Triage a child with JumpSTART, including the 5-rescue-breath rule.","Use only the lifesaving interventions START allows during triage.","Recognize when START criteria mislead (cold, dark, walkers who are sick)."],"summary":[{"title":"START in One Breath","content":"Simple Triage And Rapid Treatment uses three physiological checks — RPM: Respirations, Perfusion, Mental status. Step 0: everyone who can WALK → MINOR (green). Then for each non-walker: Breathing? If no → open/position airway → starts breathing = IMMEDIATE (red); still apneic = DECEASED (black). Breathing > 30/min = IMMEDIATE. Perfusion: radial pulse absent OR capillary refill > 2 s = IMMEDIATE (control bleeding). Mental status: can't follow simple commands = IMMEDIATE. Passed everything = DELAYED (yellow)."},{"title":"What You May Do During START","content":"Only two things, both seconds long: open the airway (position it; insert an airway adjunct if instantly available per protocol) and control major bleeding (direct pressure/tourniquet — or have a green patient hold pressure). Then tag and move. No CPR, no splinting, no oxygen, no IVs during primary triage. Target: ~30 seconds per patient, never more than 60."},{"title":"JumpSTART for Kids (≈1–8 years)","content":"Children arrest from hypoxia, and normal pediatric vitals differ — so JumpSTART adapts START. Walk → MINOR. Not breathing → position airway → breathing = IMMEDIATE; still apneic → check PERIPHERAL PULSE: none = DECEASED; pulse present → give 5 RESCUE BREATHS (~15 s) → breathing = IMMEDIATE, still apneic = DECEASED. Breathing: RR < 15 or > 45 = IMMEDIATE. Perfusion: no palpable peripheral pulse = IMMEDIATE. Mental status (AVPU): 'P' with inappropriate response (non-localizing, posturing) or 'U' = IMMEDIATE; A, V, or appropriate P = DELAYED. If the patient looks like a child → JumpSTART; looks like a young adult → START."},{"title":"Babies and Kids Who Can't Walk Yet","content":"Infants and toddlers who are not developmentally able to walk go straight through the JumpSTART algorithm (they can't 'pass' the walk test). Per JumpSTART guidance, a well-appearing non-walker with normal JumpSTART findings and no significant external injury may be tagged MINOR; otherwise DELAYED or IMMEDIATE by the criteria. A child carried out by a parent is triaged as an individual — not automatically green."},{"title":"Where START Fools You","content":"Capillary refill is unreliable in the cold and dark → use the radial pulse. Walkers can be sick (internal bleeding, chest pain, pregnancy, blast lung, toxic exposures with delayed onset) — they're green for sorting, not for life: re-triage them. START is a snapshot: a yellow with a pelvic fracture can be red in 20 minutes. Over-triaging everyone to red feels safe but buries the true reds and raises their mortality."}],"clinicalPearls":["RPM = 30-2-Can do: RR > 30 → red; CRT > 2 s (or no radial) → red; can't follow commands → red.","In START an RR of exactly 30 does NOT trigger red — the cutoff is MORE than 30.","JumpSTART numbers: 15–45 is 'OK'; outside that range is red.","Kids get a pulse check and 5 rescue breaths before being tagged deceased — the only 'resuscitation' in mass triage.","Use green patients as helpers: 'Hold pressure here, don't let go until someone relieves you.'"],"redFlags":["Spending > 60 seconds per patient — the triage line stops.","Starting CPR on an apneic adult during START.","Tagging a child deceased without the pulse check / 5 breaths step.","Relying on capillary refill in a cold night-time scene."],"commonMistakes":["Tagging RR 30 as red (rule is > 30).","Using adult START cut-offs on a toddler (RR 40 is normal for a 2-year-old).","Treating 'walking' as 'uninjured' — greens still need assessment and re-triage.","Forgetting to open the airway before tagging an apneic adult deceased."],"memoryAids":["START = RPM 30-2-Can do.","JumpSTART = 'Pulse? → 5 breaths', then 15–45, Pulse, AVPU.","Black needs TWO things in a child: no breathing after positioning AND (no pulse OR no breathing after 5 breaths)."],"decisionTrees":[{"title":"START (Adult)","content":"Can walk? → YES: MINOR (green)\n  NO ↓\nBreathing?\n  → NO: position airway → breathing? YES: IMMEDIATE | NO: DECEASED\n  → YES ↓\nRR > 30? → YES: IMMEDIATE\n  NO ↓\nRadial pulse absent OR CRT > 2 s? → YES: IMMEDIATE (control bleeding)\n  NO ↓\nFollows simple commands? → NO: IMMEDIATE | YES: DELAYED"},{"title":"JumpSTART (Child ~1–8 y)","content":"Can walk? → YES: MINOR\n  NO ↓\nBreathing?\n  → NO: position airway → breathing? YES: IMMEDIATE\n        NO → palpable peripheral pulse? NO: DECEASED\n                YES → 5 rescue breaths → breathing? YES: IMMEDIATE | NO: DECEASED\n  → YES ↓\nRR < 15 or > 45? → YES: IMMEDIATE\n  NO ↓\nPalpable peripheral pulse? → NO: IMMEDIATE\n  YES ↓\nAVPU: U or inappropriate P → IMMEDIATE | A, V, appropriate P → DELAYED"}],"references":["START — Newport Beach Fire Dept / Hoag Hospital (1983, revised)","JumpSTART Pediatric MCI Triage — L. Romig, MD","CHEMM / REMM triage resources (HHS)"]},"c07":{"id":"c07","title":"Triage II: SALT, Tags & Re-Triage","shortTitle":"SALT & Re-Triage","estimatedStudyTime":40,"difficulty":"Intermediate","learningObjectives":["Run SALT: global sort, lifesaving interventions, five categories including Expectant.","Compare START, SALT and Triage Sieve and know when each is used.","Tag correctly and re-triage at every hand-off point.","Explain over-triage vs under-triage and why both kill."],"summary":[{"title":"SALT in 4 Moves","content":"SORT globally: 'Walk to me' (assess LAST), 'Wave/move' (assess SECOND), still or obvious life threat (assess FIRST). ASSESS individually and do LIFESAVING INTERVENTIONS (seconds only): control major hemorrhage, open airway (child: consider 2 rescue breaths), chest decompression (if trained), antidote auto-injector. Then: not breathing → DEAD. Breathing → ask 4 questions: obeys commands/purposeful movement? peripheral pulse? not in respiratory distress? major hemorrhage controlled? ALL yes → MINIMAL (minor injuries only) or DELAYED. ANY no → IMMEDIATE if likely to survive with current resources, otherwise EXPECTANT. TREATMENT/TRANSPORT by priority."},{"title":"Expectant (Gray) Is a Resource Decision","content":"Expectant = alive, but unlikely to survive given CURRENT resources (e.g., massive burns, devastating head injury with agonal breathing in a scene with 3 ambulances for 60 patients). They get comfort care and pain relief and are re-triaged as soon as resources allow — the same patient may become IMMEDIATE when the scene stabilizes. Expectant is not abandonment and not 'black'. START has no expectant step; SALT and many systems do."},{"title":"Which System?","content":"START/JumpSTART: simplest, widely taught in North America. SALT: CDC-sponsored national all-hazards guideline (adults and kids in one algorithm, includes LSIs and Expectant) — the basis of the Model Uniform Core Criteria. Triage Sieve (UK/NARU): primary triage by walking, catastrophic hemorrhage, airway, breathing rate, and pulse/CRT, ranking P1–P3. Secondary triage tools (e.g., Triage Sort using the Revised Trauma Score) are used at the treatment area. Use what your system trains — consistency beats elegance."},{"title":"Tags: Your Silent Radio","content":"Tags or ribbons tell everyone the category without a word. Minimum on a tag: unique number, category, time, and critical interventions (TOURNIQUET + TIME, antidotes given, decontaminated Y/N). Attach to a limb or neck — not clothing that will be cut off. Category changes: tear/fold the tag to the new color and note the time; never leave two contradictory colors. Use the tear-off stub for the transport log."},{"title":"Re-Triage and the Two Errors","content":"Triage is a snapshot. Re-triage at: primary (scene) → secondary (treatment area entry) → before transport → hospital arrival — and whenever condition or resources change. UNDER-triage (critical patient tagged low) causes preventable deaths. OVER-triage (non-critical tagged red) floods the red area and transport — critical mortality rises as over-triage rises (Frykberg). Trauma-system benchmarks: under-triage < 5%, over-triage ~25–35%. In MCIs, accuracy saves the reds."}],"clinicalPearls":["SALT LSIs = 'Bleed, Breathe (airway ± 2 breaths for kids), Decompress, Dose (auto-injector)'.","SALT asks four YES questions: Obeys? Pulse? No distress? Bleeding controlled? Any 'no' → red or gray.","Write TQ + time on the tag (and on the patient's forehead if tags are short).","Same patient, different tag over time is normal — re-triage is the system working.","Over-triage feels safe but kills: it buries the true reds."],"redFlags":["Tags attached to jackets that get cut off in treatment.","Two colors on one patient with no time noted.","Expectant patients left alone without comfort care or re-triage.","No one assigned to re-triage the green area."],"commonMistakes":["Confusing EXPECTANT (alive, gray) with DEAD (black).","Forgetting that walkers are assessed LAST, not skipped.","Tagging everyone red 'to be safe'.","Forgetting the 2 rescue breaths for apneic children in SALT."],"memoryAids":["SALT = Sort, Assess, Lifesaving interventions, Treatment/Transport.","Sort: Walk → last, Wave → second, Still → first.","Colors: Green walks, Yellow waits, Red runs (first), Gray gets comfort, Black is gone.","Tag must-haves: #, Color, Time, TQ/Antidote, Decon."],"decisionTrees":[{"title":"SALT Individual Assessment","content":"LSIs as needed: hemorrhage control | open airway (child: consider 2 breaths) | chest decompression | auto-injector\nBreathing?\n  → NO: DEAD\n  → YES ↓\nObeys commands/purposeful movement? Peripheral pulse? Not in respiratory distress? Major hemorrhage controlled?\n  → ALL YES: minor injuries only? YES → MINIMAL | NO → DELAYED\n  → ANY NO: likely to survive with current resources?\n        YES → IMMEDIATE | NO → EXPECTANT\nRe-triage at every stage"}],"references":["SALT Mass Casualty Triage — CDC-sponsored workgroup (Lerner et al.)","Model Uniform Core Criteria (MUCC) for Mass Casualty Triage","NARU / UK Ambulance Service Triage Sieve","Frykberg ER. Medical management of disasters and mass casualties (over-triage and critical mortality)"]},"c08":{"id":"c08","title":"Treatment Area, Transport & Hospital Distribution","shortTitle":"Treat & Transport","estimatedStudyTime":35,"difficulty":"Intermediate","learningObjectives":["Deliver focused, flow-friendly care in the treatment area (MARCH priorities).","Set transport priorities and load vehicles efficiently.","Distribute patients across hospitals by capability and capacity.","Track every patient from tag to hospital bed."],"summary":[{"title":"Treatment Area Care: Do What Changes Outcome","content":"MARCH: Massive hemorrhage (tourniquets, packing), Airway (position, adjuncts; advanced airways only if they don't stall flow), Respiration (seal open chest wounds, decompress tension pneumothorax, O2 to those who need it most), Circulation (bleeding control first; IV/IO and fluids selectively — permissive hypotension in penetrating trauma), Hypothermia/Head (keep everyone warm — blankets, ground insulation; protect the head-injured airway). Skip what doesn't change survival in the next hour: detailed secondary surveys, full spinal packaging of every patient, non-critical IVs. One provider can watch several yellows; reds need hands."},{"title":"Transport Priorities","content":"Reds first — especially those who need a surgeon now: non-compressible torso hemorrhage, airway that won't stay open, tension physiology not relieved, severe burns with airway involvement. Then yellows, then greens. Fill vehicles smartly: 1 red + 1–2 greens, or 2 yellows, per ambulance (per local policy and crew capacity). Move greens in bulk — buses or vans with a medic and a radio. Use air medical for long distances or specialty centers, but an LZ costs time — don't fly a patient a ground unit could have delivered sooner."},{"title":"Hospital Distribution: Distribute, Don't Dump","content":"The closest hospital gets hit first and hardest — often by walking wounded who self-present before EMS patients arrive ('upside-down triage': the first arrivals at hospital are the least injured). Send reds to the trauma center, burns to burn-capable centers, children to pediatric-capable hospitals when the time cost is acceptable, and spread yellows/greens to hospitals further out. Get capacity through one channel: the Medical Communications Coordinator / regional hospital coordination center (e.g., 'General can take 4 red, 8 yellow')."},{"title":"Tracking: Every Patient Has a Trail","content":"Tag number → transport log → hospital. Without tracking, families can't find loved ones, hospitals can't anticipate, and patients 'disappear'. Log at the loading point (tag #, category, unit, destination, time). Hand the tear-off stub to the transport officer. Many systems use electronic patient tracking — scan the barcode on the tag. Family reunification centers depend on this data."},{"title":"Hospital Side (What EMS Should Know)","content":"Hospitals activate their own command system (e.g., HICS), clear ED beds, cancel elective surgery, and open surge areas. A classic CDC rule of thumb: roughly double the number of casualties arriving in the first hour to estimate the hospital's total. Expect decontamination at the hospital door for chemical incidents — many contaminated patients self-present. Give hospitals early, honest numbers so they can surge."}],"clinicalPearls":["The fastest treatment in an MCI is often the ambulance door closing on a red patient headed to a surgeon.","Hypothermia is the silent MCI killer — insulate from the ground, not just on top.","Load reds with a green 'buddy' who can call for help if the red deteriorates — and fill empty seats.","First-hour hospital arrivals × 2 ≈ total expected at that hospital (rule of thumb).","If you can't remember where a patient went, nobody can. Log it."],"redFlags":["Treatment area turning into a field hospital with long procedures and no outflow.","All ambulances going to the closest hospital.","Patients leaving the scene without a log entry.","Greens self-evacuating in private cars untracked (they'll show up at the nearest ED)."],"commonMistakes":["Intubating or starting multiple IVs on scene while transport units wait.","Sending one green per ambulance.","Not telling hospitals the real numbers early.","Forgetting pediatric/burn/trauma capability when assigning destinations."],"memoryAids":["MARCH: Massive bleeding, Airway, Respiration, Circulation, Hypothermia/Head.","Distribute, don't dump.","Vehicle math: 1 red + greens, 2 yellows, a busload of greens with a medic.","Log = Tag · Truck · Target · Time."],"decisionTrees":[{"title":"Destination Decision","content":"Patient ready for transport\n  → RED?\n     → Needs surgery/trauma team → TRAUMA CENTER (spread reds across trauma-capable hospitals)\n     → Major burns → burn-capable center (if time allows; else stabilize at nearest)\n     → Child → pediatric-capable hospital if time cost acceptable\n  → YELLOW → hospitals with capacity, often further from scene\n  → GREEN → bus/van with medic to hospital/clinic with spare capacity (NOT the closest)\n  → Always: check capacity via Med Comms, log it"}],"references":["TCCC/TECC MARCH algorithm (CoTCCC / C-TECC)","CDC 'In a Moment's Notice: Surge Capacity for Terrorist Bombings' (first-hour rule of thumb)","Hospital Incident Command System (HICS)"]},"c09":{"id":"c09","title":"CBRNE I: HazMat Recognition, PPE & Decon","shortTitle":"HazMat, PPE & Decon","estimatedStudyTime":40,"difficulty":"Intermediate","learningObjectives":["Recognize CBRNE/HazMat clues and apply Step 1-2-3 Plus.","Read DOT placards, NFPA 704 diamonds, and the ERG color pages.","Match PPE levels A–D to tasks.","Run gross, mass, and technical decontamination — and know when dry beats wet."],"summary":[{"title":"CBRNE: Know Which Letter","content":"Chemical, Biological, Radiological, Nuclear, Explosive. Explosives are by far the most common terrorist weapon; chemicals the most common HazMat call; biological events start silently (at clinics, days later); radiological events are mostly a fear-and-decon problem unless doses are huge. Your scene questions: Is it still releasing? Is it on people (contamination)? Can it spread person-to-person? What PPE do I need?"},{"title":"Recognition & Step 1-2-3 Plus","content":"Clues: multiple casualties with similar symptoms and no trauma, unexplained odors/mists/clouds/oily liquids, dead animals or wilted vegetation, explosions with unusual smoke or little damage, placards/labels/containers, people fleeing from one point. STEP 1: one casualty, no obvious cause → approach with normal caution. STEP 2: two casualties → approach with caution, report, consider options. STEP 3: three or more → DO NOT APPROACH; withdraw, contain, report (METHANE), isolate. PLUS: tell exposed people to get out of the area, remove outer clothing, and decontaminate ('Remove, Remove, Remove')."},{"title":"Reading the Labels","content":"DOT PLACARDS show hazard class 1–9 (1 explosives, 2 gases, 3 flammable liquids, 4 flammable solids, 5 oxidizers, 6 toxic/infectious, 7 radioactive, 8 corrosives, 9 miscellaneous) and a 4-digit UN/NA ID. The ERG: YELLOW pages = look up by ID number; BLUE = by material name; ORANGE = guide pages (hazards, PPE, first aid, evacuation); GREEN = initial isolation & protective action distances for toxic-inhalation hazards. NFPA 704 diamond (fixed facilities): BLUE = health, RED = flammability, YELLOW = instability/reactivity, WHITE = special (W = water-reactive, OX = oxidizer); 0 = minimal → 4 = severe."},{"title":"PPE Levels","content":"LEVEL A: SCBA + fully encapsulating vapor-tight suit — highest skin and respiratory protection, unknown/vapor hazards (HazMat entry teams). LEVEL B: SCBA + splash-protective suit — highest respiratory, less skin protection. LEVEL C: air-purifying respirator (APR/PAPR) + splash suit — known agent and concentration, enough oxygen; typical for decon teams and hospital decon. LEVEL D: work uniform, no respiratory protection — never in a contaminated area. EMS without HazMat training works in the COLD zone and receives patients AFTER decon."},{"title":"Decontamination","content":"The single most effective step: REMOVE CLOTHING — removes the large majority (often quoted ~80–90%) of external contamination. GROSS/emergency decon: immediate disrobe + flush for life-threatening exposure. MASS decon: disrobe → dry decon (blot/wipe exposed skin) for most exposures → wet decon (high-volume, low-pressure water, e.g., ladder-pipe/fire-engine corridor) for caustics, visible liquid contamination, or symptoms → re-dress/cover. TECHNICAL decon: thorough decon of responders/equipment. Ambulatory and non-ambulatory lanes; keep families together; give privacy and warmth; bag and tag belongings. Decon before transport — always. Life threats (airway, bleeding, antidotes) are managed in the warm zone by protected, trained providers during decon."}],"clinicalPearls":["Three down, stay out: Step 1-2-3 is the rescuer's survival rule.","Clothing off is decon step one — and it's free, fast, and can be done by the patient.","Dry decon first for most exposures; go wet for caustics, visible liquid, or symptoms.","A contaminated patient in your ambulance takes the ambulance and crew out of service.","Expect many contaminated patients to self-present to hospitals — warn them early."],"redFlags":["Rescuers developing symptoms (eye irritation, cough, miosis) — withdraw and decon everyone.","Responders entering the hot zone in Level D.","Skipping decon because the patient is critical — do rapid gross decon with LSIs instead.","Treatment area downwind of the release."],"commonMistakes":["Confusing ERG yellow (ID number) and blue (name) pages.","Thinking Level C protects in oxygen-deficient or unknown atmospheres (it doesn't — it filters air).","Using high-pressure water or scrubbing that abrades skin.","Forgetting modesty, warmth, and family grouping in mass decon — people avoid decon and self-evacuate."],"memoryAids":["Step 1-2-3 Plus: 1 = approach, 2 = caution, 3 = don't approach + 'Remove, Remove, Remove'.","ERG colors: Yellow = Your number, Blue = By name, Orange = Orders (guide), Green = Gap (distances).","NFPA: Blue = Body (health), Red = Fire, Yellow = Yikes (unstable), White = Weird (special).","PPE: A = Airtight, B = Breathing (SCBA) but splash, C = Canister (filter), D = Daily uniform."],"decisionTrees":[{"title":"Contaminated Casualty Flow","content":"Suspected HazMat/chemical\n  → Isolate, deny entry, upwind/uphill; ERG distances\n  → Casualties: get ambulatory out of hot zone → instruct 'remove outer clothing'\n  → Warm zone decon corridor (Level B/C teams):\n       LSIs (airway, bleeding, antidote) by trained protected staff\n       → Dry decon (default) | Wet decon (caustic, visible liquid, symptomatic)\n  → Cold zone: triage/treat (EMS) → transport → notify hospital"}],"references":["DOT/PHMSA Emergency Response Guidebook (ERG 2024)","NFPA 704 Standard System for the Identification of the Hazards of Materials","US HHS/BARDA PRISM — Primary Response Incident Scene Management guidance (mass decon)","UK Step 1-2-3 Plus (JESIP / NARU)"]},"c10":{"id":"c10","title":"CBRNE II: Chemical Agents & Antidotes","shortTitle":"Chemical Agents","estimatedStudyTime":45,"difficulty":"Advanced","learningObjectives":["Recognize the six chemical toxidromes EMS will see: nerve, cyanide, choking, vesicant, riot-control, opioid.","Dose the nerve-agent antidote kit by severity and titrate atropine correctly.","Give hydroxocobalamin for cyanide and know when to suspect it.","Separate delayed-onset agents (phosgene, mustard) that look 'fine' on scene."],"summary":[{"title":"Nerve Agents & Organophosphates","content":"Sarin (GB), soman (GD), tabun (GA), VX — and organophosphate pesticides — block acetylcholinesterase → acetylcholine flood. Muscarinic: SLUDGEM/DUMBELS (salivation, lacrimation, urination, defecation, GI upset, emesis, MIOSIS) and the 'killer B's' — Bronchorrhea, Bronchospasm, Bradycardia. Nicotinic: fasciculations, weakness → paralysis (tachycardia possible). CNS: seizures, coma, apnea. Vapor acts in seconds–minutes; liquid on skin can be delayed up to ~18 h. Death = respiratory failure (secretions + bronchospasm + paralysis + central apnea)."},{"title":"Nerve Agent Treatment","content":"Decon (remove clothing) + ABCs + antidotes. ATROPINE dries secretions and opens airways — titrate (adult typically 2 mg IM/IV, repeat every 5–10 min) to DRY bronchial secretions and EASY breathing, NOT to heart rate or pupil size; huge cumulative doses may be needed. PRALIDOXIME (2-PAM) reactivates the enzyme — give early before 'aging' (soman ages in minutes). Auto-injector kit (DuoDote/ATNAA: atropine 2.1 mg + pralidoxime 600 mg IM): MILD/moderate symptoms → 1 kit; SEVERE (resp. distress, seizures, unconscious) → 3 kits rapidly + benzodiazepine (midazolam 10 mg IM or diazepam 10 mg) for seizures. Isolated miosis/rhinorrhea from vapor may need no injector — observe. Children: weight-based atropine / pediatric auto-injectors per protocol."},{"title":"Cyanide","content":"Hydrogen cyanide/cyanogen chloride (and most commonly SMOKE from house fires — burning plastics, foam). Blocks cellular oxygen use: sudden collapse, gasping then apnea, seizures, hypotension → cardiac arrest within minutes at high doses; pink skin and 'bitter almonds' are unreliable; SpO2 may look normal. Suspect in enclosed-space fire victims with altered mental status, hypotension, or arrest. Treat: remove from source, 100% O2, HYDROXOCOBALAMIN (Cyanokit) 5 g IV over ~15 min (child 70 mg/kg), may repeat; turns skin and urine red and interferes with some lab tests/pulse oximetry. Nitrites cause methemoglobinemia — avoid in smoke victims who may have CO poisoning."},{"title":"Choking (Pulmonary) Agents","content":"CHLORINE (bleach odor, yellow-green gas) and AMMONIA are water-soluble → immediate eye, nose, throat burning, cough, stridor; heavy exposure → lower airway injury. PHOSGENE ('freshly mown hay') is poorly soluble → mild early symptoms then delayed non-cardiogenic pulmonary edema at 2–24 h. Treat: remove from source, O2, bronchodilators for bronchospasm, enforced REST (exertion worsens phosgene edema), observe phosgene exposures ~24 h even if they look well. No antidote."},{"title":"Vesicants, Riot Agents & Opioid Agents","content":"SULFUR MUSTARD (garlic/horseradish): no pain at exposure; erythema and blisters 2–24 h later; eyes and airways too. Cellular damage starts within minutes — decon immediately even without symptoms; no antidote. LEWISITE (geranium): immediate pain; antidote BAL (dimercaprol). RIOT-CONTROL agents (CS, CN, OC/pepper): immediate tearing, burning, cough; self-limited ~15–30 min after leaving the area — fresh air, irrigate eyes, watch asthmatics and confined-space exposures. Incapacitating OPIOIDS (fentanyl analogs, e.g., aerosolized carfentanil): miosis + coma + apnea WITHOUT secretions or fasciculations → ventilate and give naloxone (large/repeated doses)."}],"clinicalPearls":["Wet + pinpoint + twitching = nerve agent. Dry + pinpoint + not breathing = opioid.","Atropine endpoint = DRY LUNGS and easy breathing. Not the pulse, not the pupils.","3 kits + a benzo for severe nerve-agent poisoning — don't under-dose.","House-fire victim in arrest or shock → think cyanide + CO → hydroxocobalamin.","The patient who 'feels fine' after phosgene or mustard may be sick tomorrow — document, observe, don't discharge on scene."],"redFlags":["Rescuers with miosis, runny nose, or chest tightness — you're exposed; withdraw.","Titrating atropine to heart rate in a bronchorrheic patient.","Using nitrites in smoke inhalation victims with possible CO poisoning.","Releasing phosgene-exposed patients from the scene without observation."],"commonMistakes":["Waiting for symptoms before decontaminating mustard exposures.","Mixing up nerve-agent and opioid toxidromes (both have small pupils).","Giving one kit to a seizing, apneic nerve-agent patient.","Over-treating riot-control agent exposures — most resolve with fresh air."],"memoryAids":["DUMBELS: Diarrhea, Urination, Miosis, Bronchorrhea / Bronchospasm / Bradycardia, Emesis, Lacrimation, Salivation.","Nerve agent kit dosing: 'Mild 1, Severe 3 + Benzo'.","Cyanide antidote = 'Cyanokit is RED': hydroxocobalamin turns skin/urine red.","Smell clues (never rely on them): Phosgene = hay, Mustard = garlic, Lewisite = geranium, Chlorine = bleach, H2S = rotten eggs."],"decisionTrees":[{"title":"Small Pupils — Which Toxidrome?","content":"Pinpoint pupils + decreased consciousness\n  → Wet (secretions, sweating, bronchorrhea), fasciculations, ± seizures?\n       → NERVE AGENT / organophosphate → decon + atropine + pralidoxime (+ benzo)\n  → Dry, no fasciculations, apnea/hypoventilation?\n       → OPIOID agent → ventilate + naloxone\n  Sudden collapse, normal-ish pupils, enclosed fire/HCN source?\n       → CYANIDE → O2 + hydroxocobalamin"}],"references":["HHS CHEMM (Chemical Hazards Emergency Medical Management)","DuoDote / ATNAA prescribing information (atropine 2.1 mg + pralidoxime 600 mg)","Cyanokit (hydroxocobalamin) prescribing information","US Army MRICD — Medical Management of Chemical Casualties Handbook"]},"c11":{"id":"c11","title":"CBRNE III: Biological & Radiological/Nuclear","shortTitle":"Bio & Rad/Nuc","estimatedStudyTime":40,"difficulty":"Advanced","learningObjectives":["Recognize bioterrorism clues and match Category A agents to transmission and PPE.","Separate radiation EXPOSURE from CONTAMINATION and act accordingly.","Apply time–distance–shielding and emergency-worker dose guidance.","Manage dirty-bomb casualties without delaying trauma care."],"summary":[{"title":"Biological Events Arrive Quietly","content":"There's usually no scene — just a surge of sick people at EDs and clinics days later. Clues: clusters of the same severe illness, illness in an unusual place/season/age group, many cases from one event or location, sick or dead animals, a single case of a vanished disease (smallpox = public-health emergency). Overt events (threat letters, sprayers) are the exception. EMS role: protect yourself (PPE), mask the patient (source control), limit crew exposure, notify public health/medical control, clean the vehicle, follow prophylaxis guidance."},{"title":"CDC Category A Agents — EMS Essentials","content":"ANTHRAX (inhalational): flu-like → severe respiratory distress, shock, widened mediastinum; NOT person-to-person → standard precautions. PLAGUE (pneumonic): fulminant pneumonia ± hemoptysis; person-to-person by DROPLETS → mask the patient, droplet precautions (many systems use N95). SMALLPOX: high fever then synchronous pustules, densest on face/extremities incl. palms/soles; AIRBORNE + CONTACT → N95/PAPR, gown, gloves, eye protection; vaccinate contacts early. BOTULISM: alert patient with descending symmetric flaccid paralysis (diplopia, dysarthria, dysphagia → respiratory failure), no fever; not person-to-person; support ventilation, antitoxin. TULAREMIA: pneumonia/ulceroglandular, not person-to-person. VIRAL HEMORRHAGIC FEVERS (e.g., Ebola): fever, bleeding, shock; CONTACT/droplet with body fluids → full PPE with trained donning/doffing and a spotter."},{"title":"Radiation: Exposure vs Contamination","content":"EXPOSED (irradiated): energy passed through the body — like an X-ray. The patient is NOT radioactive and poses NO risk to you. CONTAMINATED: radioactive material is ON (external) or IN (internal: inhaled, ingested, wounds) the body — risk is mainly from spreading particles. Standard PPE (gloves, gown, N95/surgical mask, eye protection) + removing the patient's clothing (removes the large majority of external contamination) + gentle washing handles most of it. Radiation contamination is almost never an immediate threat to the patient's life or yours — treat life threats FIRST."},{"title":"Time, Distance, Shielding","content":"Minimize TIME near a source; maximize DISTANCE (inverse-square law: double the distance → ¼ the dose); use SHIELDING (concrete, earth, vehicles, buildings). Wear personal dosimeters and know turn-back values. US EPA emergency-worker guidance: ~5 rem (50 mSv) for general emergency actions, ~10 rem (100 mSv) to protect valuable property, ~25 rem (250 mSv) for lifesaving/protecting large populations — higher only by fully informed volunteers. ALARA: As Low As Reasonably Achievable."},{"title":"Device Types & Field Medicine","content":"RDD ('dirty bomb'): conventional explosive + radioactive material — the blast injures; radiation doses are usually low; triage and treat trauma normally, then decon. RED (radiological exposure device): hidden source irradiating passers-by — exposures without contamination, often discovered by clusters of skin burns/ARS. IND (nuclear detonation): blast, thermal, prompt radiation, then fallout — public messaging is 'Get inside, stay inside, stay tuned' (shelter in the center of a sturdy building/basement until advised). Acute radiation syndrome: earlier vomiting = higher dose (roughly: < 1 h → severe dose, > 4 h → likely survivable). Potassium iodide (KI) protects ONLY the thyroid and ONLY against radioactive iodine — not a general 'radiation pill'."}],"clinicalPearls":["An irradiated patient is not radioactive. A contaminated patient is — but clothing off + wash fixes most of it.","Never delay lifesaving trauma care for radiological decontamination.","Mask the coughing patient first — source control beats PPE.","Smallpox, Ebola, and pneumonic plague are the Category A agents that spread person-to-person; anthrax, botulism, tularemia do not.","White-powder letters are usually hoaxes: don't shake/sniff, isolate the area, wash hands with soap and water, call law enforcement/HazMat."],"redFlags":["Multiple previously healthy adults with severe pneumonia and shock from the same building.","Fever + synchronous pustules on face and palms → smallpox until proven otherwise.","Alert patient with descending paralysis and difficulty swallowing → botulism; prepare for respiratory failure.","Unexplained radiation-like skin burns in several people → hidden source (RED)."],"commonMistakes":["Refusing to touch an irradiated (exposed-only) patient.","Giving KI after a dirty bomb without radioiodine involvement.","Using only standard precautions for smallpox or VHF.","Over-decontaminating stable patients while critical trauma waits."],"memoryAids":["Category A: 'A-B-P-S-T-V' — Anthrax, Botulism, Plague, Smallpox, Tularemia, VHF.","Person-to-person: 'SPV' — Smallpox, Plague (pneumonic), VHF.","Radiation protection: Time–Distance–Shielding (ALARA).","Exposed = X-ray (safe). Contaminated = mud (wash it off)."],"decisionTrees":[{"title":"Radiological Casualty","content":"Radiological incident suspected\n  → Life threats? YES → treat now (standard PPE), decon after/with care\n  → Contaminated?\n       Unknown/likely → survey if meter available; remove clothing; gentle wash; cover wounds\n       Exposed only → no decon needed; patient is NOT radioactive\n  → Early vomiting? (< ~1 h) → high dose → priority for hospital ARS care\n  → Track your dose: time, distance, shielding; dosimeter turn-back values"}],"references":["CDC Bioterrorism Agents/Diseases (Category A)","HHS REMM — Radiation Emergency Medical Management","US EPA Protective Action Guides (PAG) Manual — emergency worker dose guidelines","FEMA/Ready.gov — Nuclear explosion: Get Inside, Stay Inside, Stay Tuned"]},"c12":{"id":"c12","title":"Explosive & Hostile Events: Blast, Active Shooter, TECC","shortTitle":"Blast & Hostile MCI","estimatedStudyTime":45,"difficulty":"Advanced","learningObjectives":["Classify blast injuries (primary to quinary) and recognize blast lung.","Apply TECC phases of care and the THREAT sequence.","Explain the Rescue Task Force model and casualty collection points.","Anticipate secondary devices, upside-down triage, and responder targeting."],"summary":[{"title":"Blast Injury Classes","content":"PRIMARY: the pressure wave hits air-filled organs — tympanic membranes, lungs (blast lung), bowel; worse in ENCLOSED spaces and near the device. SECONDARY: fragments/shrapnel/debris — the most common cause of blast injuries (penetrating wounds anywhere, eyes). TERTIARY: the body thrown, or structure collapsing on it — blunt trauma, traumatic amputation, crush. QUATERNARY: everything else — burns, toxic inhalation, CO, exacerbation of chronic illness. QUINARY: hyperinflammatory state from additives (bacteria, chemicals, radiation)."},{"title":"Blast Lung & Blast Pearls","content":"Blast lung: dyspnea, hypoxia, cough, hemoptysis, chest pain — can appear up to 24–48 h later. Give O2, avoid aggressive fluids, be careful with positive-pressure ventilation (pneumothorax and arterial air embolism risk), watch for tension pneumothorax. A ruptured eardrum signals significant pressure exposure but is NOT a reliable marker of blast lung — and an intact eardrum doesn't rule it out. Victims may be deafened: communicate with gestures and written cues. Traumatic amputation = high energy; look for hidden torso injury."},{"title":"Hostile MCI: The Threat Changes Everything","content":"Active shooters, bombings, vehicle rammings, and complex coordinated attacks may target responders. Expect secondary devices near CCPs and staging, shooters moving between locations, and fake 'victims'. Staging out of sight; vary your positions; no gathering in obvious open spaces; police cordons decide where you can go. 'Upside-down triage': the least injured flee and self-present to nearby hospitals first; the critically injured arrive later via EMS."},{"title":"TECC — Three Phases of Care","content":"DIRECT THREAT (hot): win the fight / get out of the line of fire; casualty self-aid if possible; ONLY tourniquet for life-threatening extremity bleeding ('high and tight') and move to cover — no airway management, no spinal immobilization. INDIRECT THREAT (warm): structured MARCH care — reassess/convert tourniquets, pack junctional wounds, recovery position/NPA, chest seal and needle decompression, prevent hypothermia, consider TXA per protocol, prepare for movement. EVACUATION (cold): reassess and continue care during transport; more advanced interventions as resources allow."},{"title":"THREAT & the Rescue Task Force","content":"Hartford Consensus THREAT: Threat suppression, Hemorrhage control, Rapid Extrication to safety, Assessment by medical providers, Transport to definitive care. Rescue Task Force (RTF): small teams of EMS/fire in ballistic protection, escorted by law enforcement, entering CLEARED warm-zone areas to stop bleeding and move casualties to a casualty collection point (CCP) — while other officers keep hunting the threat. Goal: 'Stop the killing, then stop the dying.' Bystanders with Stop the Bleed training save lives before you arrive."}],"clinicalPearls":["Hemorrhage is the leading preventable cause of death in hostile events — tourniquets early, high and tight in the hot zone.","In direct threat, the best medicine is fire superiority and cover — not airway management.","Enclosed-space blasts (bus, train, room) produce far more primary blast injury than open-air blasts.","Every ruptured eardrum is a reason to look harder at the lungs — but a normal eardrum doesn't clear them.","CCPs and staging are predictable targets — ask police to clear them for secondary devices."],"redFlags":["Unattended bags, vehicles parked oddly near the scene, or a second explosion.","Responders bunching at one obvious spot (perfect secondary target).","Delayed dyspnea or hypoxia in a blast survivor who looked fine (blast lung).","Aggressive fluids or high-pressure ventilation in blast lung."],"commonMistakes":["Entering a hot zone without law enforcement — or not entering cleared warm zones when RTF is the plan.","Using a tourniquet too low or too loose in the hot zone ('high and tight' then reassess in warm).","Assuming an intact eardrum rules out primary blast injury.","Forgetting the tourniquet time on the tag."],"memoryAids":["Blast classes: 1 Pressure, 2 Projectiles, 3 Pushed/Pinned, 4 Plus everything else (burns, toxins), 5 Pro-inflammatory.","THREAT: Threat suppression, Hemorrhage control, Rapid Extrication, Assessment, Transport.","TECC: Hot = Tourniquet & Cover; Warm = MARCH; Cold = Reassess & Ride.","'Stop the killing, stop the dying.'"],"decisionTrees":[{"title":"Hostile Event — EMS Flow","content":"Report of shooting/explosion\n  → Stage out of sight; police establish cordons\n  → Threat ongoing? Direct threat = HOT → police only (self-aid/TQ by those already inside)\n  → Areas cleared but not secure = WARM → Rescue Task Forces with police escort:\n       TQs, packing, airway positioning, chest seals → move to CCP\n  → CCP → triage (SALT/START) → COLD treatment & transport\n  → Watch for secondary devices; re-check staging/CCP safety"}],"references":["C-TECC Tactical Emergency Casualty Care guidelines","Hartford Consensus (ACS) — THREAT","CDC Explosions and Blast Injuries: A Primer for Clinicians","FEMA/USFA Fire/EMS Departments Operational Considerations for Active Shooter and Mass Casualty Incidents"]},"c13":{"id":"c13","title":"Special MCIs: Collapse, Crush, Crowds & Natural Disasters","shortTitle":"Special MCIs","estimatedStudyTime":40,"difficulty":"Advanced","learningObjectives":["Manage entrapment and prevent death at release in crush syndrome.","Recognize and respond to crowd crush and mass-gathering hazards.","Apply hazard-specific tactics for transport crashes and natural disasters.","Protect vulnerable populations: children, elderly, technology-dependent patients."],"summary":[{"title":"Structural Collapse & Crush Syndrome","content":"Don't enter unstable structures — USAR teams shore, breach, and perform confined-space rescue; EMS supports them and may treat in voids only when it's declared safe. Crush syndrome follows prolonged compression of large muscle masses (classically hours, but sooner with heavy loads): at RELEASE, potassium, acid, and myoglobin flood the circulation → arrhythmia/cardiac arrest ('smiling death') and later kidney failure. Before release: IV/IO normal saline (~1–1.5 L/h adult; avoid potassium-containing fluids), cardiac monitor, prepare for hyperkalemia (calcium, sodium bicarbonate, nebulized albuterol per protocol). If no access and release can't wait, some protocols allow a tourniquet on the limb before release as a last resort."},{"title":"Crowd Crush & Mass Gatherings","content":"Danger starts when crowd density exceeds ~4–5 people per m² and people can no longer move independently; crowd 'waves' and surges precede collapse. Victims die standing — compressive (traumatic) asphyxia — not mainly from trampling. Signs: facial/neck plethora and petechiae, subconjunctival hemorrhage, hypoxia. Actions: alert event control to stop inflow and open exits, extract from the edges, open airway, O2, ventilate, triage normally. Pre-plan mass gatherings: medical posts, access/egress lanes, heat/cold plans, intoxication, communications with event security."},{"title":"Transportation Incidents","content":"Closed incidents with a manifest — get the passenger count early and account for everyone (including those ejected or wandered off). BUS/COACH: rollover = multi-system blunt trauma, entrapment, fuel. RAIL: isolate power (overhead lines, third rail) before entry; long extrication; hazmat cargo. AIRCRAFT: approach upwind, fuel fires, composite fiber hazards (respiratory protection), wide debris field; airport emergency plans. MARITIME: drowning, hypothermia, staged shore triage."},{"title":"Natural Disaster Tactics","content":"EARTHQUAKE: aftershocks — stay out of damaged buildings; crush and fractures; compound incident (hospitals damaged). FLOOD: never enter moving water — ~6 inches (15 cm) can knock you down and ~1 foot (30 cm) can float most cars; electrocution, contaminated water, hypothermia; swift-water teams only. HEAT WAVE: exertional or classic heat stroke = cool FIRST (cold-water immersion is best), transport second. WINTER STORM: hypothermia, CO from heaters/generators, falls. HURRICANE: pre-landfall evacuation of dependent patients; post-storm CO, chainsaw injuries, missed dialysis. WILDFIRE: protect your exit route; burns, smoke, CO/cyanide."},{"title":"Vulnerable Populations","content":"CHILDREN: JumpSTART triage; keep with caregivers where possible; document and protect UNACCOMPANIED MINORS (photo, tag, safe supervised area) — never release to unverified adults; smaller airways and higher surface area → faster hypothermia and toxin absorption. ELDERLY: atypical presentations, falls, medication dependence, heat vulnerability. TECHNOLOGY-DEPENDENT: home ventilators, O2 concentrators, dialysis, insulin — power outages create patients. DISABILITIES: service animals stay with owners; communication aids; evacuation chairs. PREGNANCY: left lateral tilt; fetal well-being depends on maternal oxygenation and perfusion."}],"clinicalPearls":["Fluids before freedom: start IV saline before releasing a crush victim.","Peaked T waves after extrication = hyperkalemia → calcium now.","Crowd crush kills by asphyxia — the fix is releasing the chest and ventilating.","Turn around, don't drown: no rescuer enters moving water without swift-water training and gear.","Unaccompanied children get a name, a photo, a tag, and a guardian-in-charge — reunification is a safety process."],"redFlags":["Releasing a long-entrapped limb without fluids or a monitor.","Crowd surges, people unable to raise their arms, screams from one area of a crowd.","Rescuers entering unshored collapse voids.","Power outage calls for ventilator/O2-dependent patients — rising heat or cold."],"commonMistakes":["Using lactated Ringer's (contains potassium) for crush pre-release fluids.","Releasing unaccompanied children to any adult who claims them.","Treating heat stroke without aggressive cooling on scene.","Forgetting to request the passenger manifest in transport incidents."],"memoryAids":["Crush: 'Fluids before freedom; calcium for the K.'","Flood: '6 inches knocks you down, 1 foot floats your car.'","Heat stroke: 'Cool first, transport second.'","Unaccompanied minors: 'Name, Photo, Tag, Guardian.'"],"decisionTrees":[{"title":"Crush Victim Release","content":"Entrapped > ~1 h (large muscle mass) or heavy compression?\n  → YES: crush syndrome risk\n     → IV/IO access → NS 1–1.5 L/h BEFORE release (no K+ fluids)\n     → Cardiac monitor; prepare calcium, bicarbonate, albuterol per protocol\n     → No IV & release can't wait → consider TQ before release (protocol/last resort)\n     → Release → watch for hyperkalemia (peaked T, wide QRS, arrhythmia)\n  → NO: standard trauma care"}],"references":["INSARAG / FEMA USAR medical guidance","International Society of Nephrology / Renal Disaster Relief Task Force crush syndrome recommendations","US National Weather Service 'Turn Around Don't Drown'","AAP / ASPR pediatric disaster and family reunification guidance"]},"c14":{"id":"c14","title":"Demobilization, Recovery & Responder Resilience","shortTitle":"Demob & Resilience","estimatedStudyTime":25,"difficulty":"Beginner","learningObjectives":["Demobilize resources safely and reconcile every patient.","Run a hot wash and contribute to an after-action review.","Apply responder rehab and Psychological First Aid.","Recognize stress reactions that need referral."],"summary":[{"title":"Demobilization Is an Operation","content":"Release resources as they're no longer needed, not all at once — keep enough for re-triage, late-found patients, and responder rehab. Each unit is checked out: crew accounted for, rehab/medical check, equipment decontaminated (CBRNE), restocked, returned to service. Command is formally terminated and announced. Before closing: reconcile the patient count — scene tags = transport log = hospital arrivals (+ dead + released on scene). A mismatch means someone is missing."},{"title":"Documentation That Matters","content":"MCI paperwork is short but non-negotiable: triage tags (they ARE records), the transport log, unit assignments, times, tourniquet times, antidotes and decon given, and exposure logs for responders (chemical/radiological/biological). Complete abbreviated or full ePCRs per local policy after the incident. Records drive reunification, legal review, reimbursement, and the after-action report."},{"title":"Hot Wash & After-Action Review","content":"HOT WASH: within minutes–hours, short, informal, everyone present: what went well, what didn't, any immediate safety issues. AFTER-ACTION REVIEW/REPORT (AAR) with an Improvement Plan: What was supposed to happen? What actually happened? Why was there a difference? What do we sustain, what do we improve — with owners and deadlines. Blame-free and systems-focused. Feed lessons into plans, training, and drills (tabletop → functional → full-scale exercises)."},{"title":"Responder Rehab","content":"Rehab starts during the incident, not after: shade/shelter, hydration, food, rest, medical monitoring (vitals, symptoms, CO if smoke exposure). Rotate crews before exhaustion — e.g., NFPA 1584 guidance: rehab after two 30-minute SCBA cylinders or ~40 minutes of intense work. Watch for heat illness, rhabdomyolysis, chest pain, and dehydration in your own people."},{"title":"Psychological First Aid, Not Forced Debriefing","content":"Stress reactions (poor sleep, intrusive images, irritability, numbness) are common and usually fade in days to weeks. Psychological First Aid (PFA) — 'Look, Listen, Link': ensure safety and basic needs, listen without pushing for details, connect to social support and services. Mandatory single-session psychological debriefing (forcing everyone to relive the event) is NOT recommended — it doesn't prevent PTSD and may harm. Use peer support, buddy checks, and follow-up; refer when symptoms persist beyond ~a month, worsen, or include suicidal thoughts or substance misuse."}],"clinicalPearls":["Tags + transport log + hospital list must add up. If they don't, keep looking.","Release units in phases — the last patients are often found after the scene 'feels' over.","The hot wash is for facts and safety, not therapy — keep it short.","Look, Listen, Link: PFA works for colleagues as well as patients.","Normal people have strong reactions to abnormal events — say it out loud to your crew."],"redFlags":["A colleague who can't sleep, drinks more, or withdraws weeks after the incident.","Any responder talking about hopelessness or self-harm — act today.","Patient numbers that don't reconcile with hospitals.","Contaminated equipment returned to service without decon."],"commonMistakes":["Releasing all resources the moment the last red is transported.","Skipping the hot wash because 'everyone is tired'.","Forcing all staff into a single group debrief to 'process' the event.","Writing AAR findings without owners or deadlines — nothing changes."],"memoryAids":["Demob: Check out, Clean, Restock, Return.","AAR 4 questions: Supposed to? Actually? Why different? Sustain/Improve?","PFA: Look, Listen, Link.","Reconcile: Tags = Log = Hospitals (+ dead + released)."],"decisionTrees":[{"title":"Closing the Incident","content":"All patients transported/released?\n  → Reconcile counts: tags = transport log = hospital arrivals (+ dead/released)\n     → Mismatch: search, re-check hospitals, re-sweep scene\n  → Phased demob: rehab check → decon → restock → return to service\n  → Terminate command (announce)\n  → Hot wash today → AAR/Improvement Plan → update plans & training\n  → PFA + peer follow-up for responders; refer persistent symptoms"}],"references":["FEMA HSEEP — After-Action Report / Improvement Plan","WHO Psychological First Aid: Guide for Field Workers (Look, Listen, Link)","NFPA 1584 — Rehabilitation Process for Members During Emergency Operations","Cochrane/WHO guidance on single-session psychological debriefing"]}},"flashcards":{"c01":{"chapter":"c01","cards":[{"id":"c01_fc01","question":"Define a mass casualty incident (MCI).","answer":"Any incident where the number and/or severity of casualties exceeds the resources immediately available — defined by the resource gap, not a fixed number.","category":"Definitions"},{"id":"c01_fc02","question":"MCI vs disaster?","answer":"An MCI overwhelms immediately available resources; a disaster overwhelms the community's overall response capacity and requires outside (regional/national) assistance.","category":"Definitions"},{"id":"c01_fc03","question":"Open vs closed incident?","answer":"Closed: finite, known number of victims (bus crash). Open: victims keep appearing or number unknown (earthquake, active shooter, plume).","category":"Classification"},{"id":"c01_fc04","question":"Simple vs compound incident?","answer":"Simple: infrastructure intact. Compound: infrastructure (roads, hospitals, comms, utilities) is itself damaged.","category":"Classification"},{"id":"c01_fc05","question":"Compensated vs uncompensated incident?","answer":"Compensated: the system can absorb it with additional resources. Uncompensated: cannot, even with mutual aid — a disaster.","category":"Classification"},{"id":"c01_fc06","question":"Name the 5 natural disaster groups.","answer":"Geophysical, hydrological, meteorological, climatological, biological.","category":"Disaster Types"},{"id":"c01_fc07","question":"Name 4 categories of human-made disasters.","answer":"Technological/industrial, transportation, intentional (terrorism/CBRNE/violence), mass-gathering/crowd events.","category":"Disaster Types"},{"id":"c01_fc08","question":"Dominant injury pattern in an earthquake?","answer":"Crush injuries and crush syndrome, fractures, head injuries, entrapment — plus later wound infections.","category":"Injury Patterns"},{"id":"c01_fc09","question":"Dominant threats in a flood?","answer":"Drowning, hypothermia, debris trauma, electrocution, contaminated water — and swift-water rescuer deaths.","category":"Injury Patterns"},{"id":"c01_fc10","question":"Key post-hurricane killer often missed?","answer":"Carbon monoxide poisoning from generators used indoors; also cleanup injuries and loss of dialysis/oxygen.","category":"Injury Patterns"},{"id":"c01_fc11","question":"Mechanism of death in crowd crush?","answer":"Compressive (traumatic) asphyxia — the chest can't expand; not trampling alone.","category":"Injury Patterns"},{"id":"c01_fc12","question":"Phases of the disaster cycle?","answer":"Mitigation → Preparedness → Response → Recovery (→ back to mitigation).","category":"Disaster Cycle"}]},"c02":{"chapter":"c02","cards":[{"id":"c02_fc01","question":"What are the first-arriving EMS crew's two jobs?","answer":"Command (declare MCI, METHANE, request resources) and recon/global triage — NOT treating the first patient.","category":"First-Due"},{"id":"c02_fc02","question":"Safety 1-2-3?","answer":"Self, Scene, Survivors — in that order.","category":"Safety"},{"id":"c02_fc03","question":"Expand CSCATTT.","answer":"Command & control, Safety, Communication, Assessment, Triage, Treatment, Transport.","category":"CSCATTT"},{"id":"c02_fc04","question":"Which parts of CSCATTT are management vs medical?","answer":"CSCA = management; TTT (Triage, Treatment, Transport) = medical support.","category":"CSCATTT"},{"id":"c02_fc05","question":"Expand METHANE.","answer":"Major incident declared/standby, Exact location, Type of incident, Hazards, Access/egress, Number & severity of casualties, Emergency services present & required.","category":"METHANE"},{"id":"c02_fc06","question":"What goes in the 'H' of METHANE?","answer":"Hazards present AND potential: fire, fuel, chemicals, structural instability, violence/secondary device, weather, traffic.","category":"METHANE"},{"id":"c02_fc07","question":"What goes in the 'A' of METHANE?","answer":"Access and egress routes: safest approach, rendezvous/staging point, roads to avoid, one-way flow.","category":"METHANE"},{"id":"c02_fc08","question":"How should casualty numbers be given in METHANE?","answer":"Estimated total with severity split, e.g., 'approximately 30: 6 red, 10 yellow, 14 green'. Estimates are acceptable.","category":"METHANE"},{"id":"c02_fc09","question":"Why plain language instead of 10-codes?","answer":"NIMS standard — mutual-aid agencies use different codes; plain language prevents misunderstanding.","category":"Comms"},{"id":"c02_fc10","question":"What is a CAN report?","answer":"Structured update: Conditions, Actions, Needs.","category":"Comms"},{"id":"c02_fc11","question":"Where should the first ambulance park?","answer":"Upwind, uphill, upstream, outside the hazard, out of traffic, not blocking access — visible as a command point.","category":"First-Due"},{"id":"c02_fc12","question":"Clue that an MCI is chemical rather than traumatic?","answer":"Multiple casualties collapsed without obvious trauma, odors/clouds, dead animals, similar symptoms in many people.","category":"Safety"}]},"c03":{"chapter":"c03","cards":[{"id":"c03_fc01","question":"What is unity of command?","answer":"Each responder reports to one, and only one, designated supervisor.","category":"Principles"},{"id":"c03_fc02","question":"Recommended span of control in ICS?","answer":"About 3–7 subordinates per supervisor; ~5 is optimal.","category":"Principles"},{"id":"c03_fc03","question":"Name the three Command Staff positions.","answer":"Safety Officer, Public Information Officer, Liaison Officer.","category":"Command Staff"},{"id":"c03_fc04","question":"Name the four General Staff sections.","answer":"Operations, Planning, Logistics, Finance/Administration.","category":"General Staff"},{"id":"c03_fc05","question":"Which ICS section does EMS work in?","answer":"Operations Section (Medical Branch/Group).","category":"EMS in ICS"},{"id":"c03_fc06","question":"Title for the head of a Section? Branch? Division/Group? Unit?","answer":"Section Chief; Branch Director; Division/Group Supervisor; Unit Leader.","category":"Titles"},{"id":"c03_fc07","question":"Division vs Group?","answer":"Division = geographic area (where); Group = functional assignment (what).","category":"Titles"},{"id":"c03_fc08","question":"What is an Incident Action Plan (IAP)?","answer":"The incident's objectives, strategies, and assignments for an operational period — verbal for small incidents, written for large.","category":"Principles"},{"id":"c03_fc09","question":"Who owns an ICS position that hasn't been filled?","answer":"The supervisor above it — ultimately the Incident Commander.","category":"Principles"},{"id":"c03_fc10","question":"Proper transfer of command?","answer":"Face-to-face briefing (situation, objectives, hazards, resources, org), then announce the change to all units.","category":"Command"},{"id":"c03_fc11","question":"What is unified command?","answer":"Multiple agencies with jurisdiction co-manage the incident with one command post and one set of objectives, each keeping authority over its own resources.","category":"Command"},{"id":"c03_fc12","question":"Which section handles supplies, facilities, comms equipment, and food?","answer":"Logistics.","category":"General Staff"},{"id":"c03_fc13","question":"Which section tracks resources, situation status, and writes the IAP?","answer":"Planning.","category":"General Staff"}]},"c04":{"chapter":"c04","cards":[{"id":"c04_fc01","question":"Core mission of the EMS Incident Commander?","answer":"Own the incident: command post, METHANE, objectives, assign officers, request resources, coordinate agencies — never hands-on patient care.","category":"IC"},{"id":"c04_fc02","question":"Core mission of the Triage Officer?","answer":"Find and sort all casualties fast: global sort, tag, seconds-long LSIs, report counts to IC, direct reds to treatment, re-triage.","category":"Triage"},{"id":"c04_fc03","question":"What may the Triage Officer do to a patient?","answer":"Only seconds-long lifesaving interventions: control massive bleeding, open/position the airway, (child) rescue breaths per protocol, auto-injector, decompression if trained and protocol allows.","category":"Triage"},{"id":"c04_fc04","question":"Core mission of the Treatment Officer?","answer":"Set up and run the treatment area by category, perform secondary triage and stabilizing care, and prioritize patients for transport.","category":"Treatment"},{"id":"c04_fc05","question":"Core mission of the Transport Officer?","answer":"Coordinate loading zone, call units from staging, assign destination hospitals by capacity/capability, and keep the transport log.","category":"Transport"},{"id":"c04_fc06","question":"Minimum fields in a transport log?","answer":"Triage tag number, category, transporting unit, destination hospital, departure time (plus basic injuries/age/sex if possible).","category":"Transport"},{"id":"c04_fc07","question":"Why not send every patient to the closest hospital?","answer":"It overwhelms that hospital (which also receives most self-presenters) while others sit underused — distribute by capacity and capability.","category":"Transport"},{"id":"c04_fc08","question":"Staging Officer's key rules?","answer":"Safe location with one-way access; check in every unit; crews stay with vehicles, keys in; release only on Transport's request; report available numbers to IC.","category":"Staging"},{"id":"c04_fc09","question":"Who speaks to hospitals during an MCI?","answer":"The Medical Communications Coordinator (under Transport) — one voice to hospitals/hospital coordination center.","category":"Support Roles"},{"id":"c04_fc10","question":"What happens to the dead at an MCI?","answer":"Left in place unless blocking access to the living; tagged, secured, out of public view; morgue manager coordinates with law enforcement/medical examiner.","category":"Support Roles"},{"id":"c04_fc11","question":"Why wear role vests?","answer":"Instant visual identification of who holds which role — the scene can find its officers.","category":"General"},{"id":"c04_fc12","question":"How can green patients help?","answer":"Under direction they can apply pressure, assist other greens, or help carry litters — and they must still be assessed and re-triaged.","category":"Triage"}]},"c05":{"chapter":"c05","cards":[{"id":"c05_fc01","question":"Define the hot zone.","answer":"Area of immediate danger (contamination, fire, collapse, active violence) — entry only by properly protected specialist teams.","category":"Zones"},{"id":"c05_fc02","question":"What happens in the warm zone?","answer":"Decontamination corridor, casualty collection points, rapid lifesaving care under protection/escort.","category":"Zones"},{"id":"c05_fc03","question":"What belongs in the cold zone?","answer":"Command post, treatment area, loading zone, staging, rehab, media area, morgue (out of view).","category":"Zones"},{"id":"c05_fc04","question":"Ideal treatment area location?","answer":"Cold zone, upwind/uphill, flat, lit, sheltered, room to expand, next to the loading zone, one way in/one way out.","category":"Layout"},{"id":"c05_fc05","question":"Which treatment section sits nearest the loading zone exit?","answer":"Red (Immediate) — they leave first.","category":"Layout"},{"id":"c05_fc06","question":"Ideal staging area?","answer":"On the approach route, out of sight of the hazard, safe, with room to park in rows and a one-way path to the loading zone.","category":"Layout"},{"id":"c05_fc07","question":"Where should the helicopter LZ be?","answer":"Cold zone, clear of wires/obstacles/debris, away from the treatment area because of rotor wash; typically ~100 × 100 ft (≈30 × 30 m) — follow your air provider.","category":"Layout"},{"id":"c05_fc08","question":"Where is the morgue placed?","answer":"Cold zone, secure, out of public and patient view.","category":"Layout"},{"id":"c05_fc09","question":"Rule for positioning near HazMat?","answer":"Upwind, uphill, upstream; use the ERG for isolation and protective action distances.","category":"Stand-off"},{"id":"c05_fc10","question":"Approximate stand-off for a pipe bomb?","answer":"≈70 ft mandatory evacuation; ≈1,200 ft outdoor preferred evacuation (DHS/NCTC chart).","category":"Stand-off"},{"id":"c05_fc11","question":"What is a Casualty Collection Point (CCP)?","answer":"A point (often in the warm zone) where casualties are gathered for triage and rapid care before movement to the treatment area.","category":"Flow"},{"id":"c05_fc12","question":"Why one-way patient and vehicle flow?","answer":"Prevents congestion, collisions, and lost patients; ambulances never back through the scene.","category":"Flow"}]},"c06":{"chapter":"c06","cards":[{"id":"c06_fc01","question":"What does START stand for?","answer":"Simple Triage And Rapid Treatment.","category":"START"},{"id":"c06_fc02","question":"START mnemonic for the 3 checks?","answer":"RPM 30-2-Can do: Respirations > 30, Perfusion (CRT > 2 s / no radial), Mental status (can't follow commands).","category":"START"},{"id":"c06_fc03","question":"START: an adult who can walk is tagged…","answer":"MINOR (green) — assessed later and re-triaged.","category":"START"},{"id":"c06_fc04","question":"START: apneic adult after airway positioning?","answer":"DECEASED (black). If breathing starts after positioning → IMMEDIATE.","category":"START"},{"id":"c06_fc05","question":"START: RR 34, radial present, follows commands?","answer":"IMMEDIATE — RR > 30.","category":"START"},{"id":"c06_fc06","question":"START: RR 20, radial absent?","answer":"IMMEDIATE — perfusion criterion.","category":"START"},{"id":"c06_fc07","question":"START: RR 22, radial present, CRT < 2 s, follows commands, can't walk?","answer":"DELAYED (yellow).","category":"START"},{"id":"c06_fc08","question":"Which two interventions are allowed during START?","answer":"Open/position the airway and control major bleeding.","category":"START"},{"id":"c06_fc09","question":"Age range for JumpSTART?","answer":"Roughly 1–8 years: use JumpSTART if the patient looks like a child, START if they look like a young adult.","category":"JumpSTART"},{"id":"c06_fc10","question":"JumpSTART: apneic child after positioning, with a pulse — next step?","answer":"Give 5 rescue breaths (~15 s). Breathing → IMMEDIATE; still apneic → DECEASED.","category":"JumpSTART"},{"id":"c06_fc11","question":"JumpSTART respiratory cut-offs?","answer":"RR < 15 or > 45 → IMMEDIATE.","category":"JumpSTART"},{"id":"c06_fc12","question":"JumpSTART mental status tool?","answer":"AVPU: U or inappropriate P (non-localizing/posturing) → IMMEDIATE; A, V, or appropriate P → DELAYED.","category":"JumpSTART"},{"id":"c06_fc13","question":"Why use radial pulse over capillary refill in some scenes?","answer":"CRT is unreliable in cold and in poor lighting.","category":"Pitfalls"},{"id":"c06_fc14","question":"Target time per patient in START?","answer":"~30 seconds; no more than 60.","category":"START"}]},"c07":{"chapter":"c07","cards":[{"id":"c07_fc01","question":"SALT global sort — who is assessed first, second, last?","answer":"First: still/obvious life threat. Second: those who wave/move purposefully. Last: those who walk.","category":"SALT Sort"},{"id":"c07_fc02","question":"SALT lifesaving interventions?","answer":"Control major hemorrhage, open airway (child: consider 2 rescue breaths), chest decompression, antidote auto-injector — seconds only.","category":"SALT LSIs"},{"id":"c07_fc03","question":"SALT's four assessment questions?","answer":"Obeys commands/purposeful movement? Peripheral pulse? Not in respiratory distress? Major hemorrhage controlled?","category":"SALT Assess"},{"id":"c07_fc04","question":"SALT: all four YES with only minor injuries?","answer":"MINIMAL (green).","category":"SALT Categories"},{"id":"c07_fc05","question":"SALT: all four YES with significant injuries?","answer":"DELAYED (yellow).","category":"SALT Categories"},{"id":"c07_fc06","question":"SALT: any NO, likely to survive with current resources?","answer":"IMMEDIATE (red).","category":"SALT Categories"},{"id":"c07_fc07","question":"Define EXPECTANT.","answer":"Alive but unlikely to survive given current resources — comfort care, re-triage when resources improve (gray).","category":"SALT Categories"},{"id":"c07_fc08","question":"Minimum information on a triage tag?","answer":"Unique number, category, time, critical interventions (TQ + time, antidotes), decon status.","category":"Tags"},{"id":"c07_fc09","question":"When should patients be re-triaged?","answer":"At the scene, on entry to treatment, before transport, at hospital arrival, and whenever condition or resources change.","category":"Re-Triage"},{"id":"c07_fc10","question":"Under-triage vs over-triage?","answer":"Under: critical patient tagged too low (preventable death). Over: non-critical tagged too high (resources diverted; critical mortality rises).","category":"Accuracy"},{"id":"c07_fc11","question":"Accepted trauma-system targets for triage error?","answer":"Under-triage < 5%; over-triage ~25–35%.","category":"Accuracy"},{"id":"c07_fc12","question":"What is the UK primary triage tool?","answer":"Triage Sieve (P1–P3 priorities), followed by Triage Sort at the casualty clearing station.","category":"Systems"}]},"c08":{"chapter":"c08","cards":[{"id":"c08_fc01","question":"Expand MARCH.","answer":"Massive hemorrhage, Airway, Respiration, Circulation, Hypothermia/Head injury.","category":"Treatment"},{"id":"c08_fc02","question":"What care is skipped in the MCI treatment area?","answer":"Time-consuming care that doesn't change near-term survival: detailed secondary surveys, routine full spinal packaging, non-critical IVs, prolonged procedures.","category":"Treatment"},{"id":"c08_fc03","question":"Why is hypothermia a major concern in MCIs?","answer":"Prolonged waits on the ground worsen coagulopathy and outcomes — insulate from the ground and cover.","category":"Treatment"},{"id":"c08_fc04","question":"Transport priority order?","answer":"Immediate (red) → Delayed (yellow) → Minor (green); Expectant when resources allow.","category":"Transport"},{"id":"c08_fc05","question":"Efficient ambulance loading examples?","answer":"1 red + 1–2 greens, or 2 yellows (per policy); greens in bulk by bus with a medic.","category":"Transport"},{"id":"c08_fc06","question":"What is 'upside-down triage' at hospitals?","answer":"Less-injured patients self-present first to the nearest hospital, filling it before critical EMS patients arrive.","category":"Hospitals"},{"id":"c08_fc07","question":"Why spread patients across hospitals?","answer":"Prevents overwhelming the nearest facility (which also gets most self-presenters) while others sit underused.","category":"Hospitals"},{"id":"c08_fc08","question":"CDC first-hour rule of thumb?","answer":"Roughly double the number of casualties arriving at a hospital in the first hour to estimate its total casualties.","category":"Hospitals"},{"id":"c08_fc09","question":"Who should talk to hospitals during an MCI?","answer":"One Medical Communications Coordinator / regional hospital coordination center.","category":"Hospitals"},{"id":"c08_fc10","question":"Why is patient tracking vital?","answer":"Locates every patient for families, hospitals, re-triage, and accountability; supports reunification.","category":"Tracking"},{"id":"c08_fc11","question":"When should air medical be used in an MCI?","answer":"Long distances or specialty center needs where it's faster than ground — LZs cost time and resources.","category":"Transport"}]},"c09":{"chapter":"c09","cards":[{"id":"c09_fc01","question":"Step 1-2-3 Plus?","answer":"1 casualty: approach normally. 2: approach with caution. 3+: do not approach — withdraw, report, isolate. Plus: get people out, disrobe, decontaminate.","category":"Recognition"},{"id":"c09_fc02","question":"Classic clues of a chemical incident?","answer":"Multiple casualties, similar symptoms, no trauma; odors/mists/liquids; dead animals/vegetation; people fleeing from one point.","category":"Recognition"},{"id":"c09_fc03","question":"DOT hazard classes 1–9?","answer":"1 Explosives, 2 Gases, 3 Flammable liquids, 4 Flammable solids, 5 Oxidizers, 6 Toxic/infectious, 7 Radioactive, 8 Corrosives, 9 Miscellaneous.","category":"Placards"},{"id":"c09_fc04","question":"ERG page colors?","answer":"Yellow: by ID number. Blue: by name. Orange: guides. Green: isolation & protective action distances (TIH).","category":"ERG"},{"id":"c09_fc05","question":"NFPA 704 colors?","answer":"Blue health, Red flammability, Yellow instability, White special hazards; 0–4 severity.","category":"NFPA"},{"id":"c09_fc06","question":"PPE Level A?","answer":"SCBA + fully encapsulating vapor-tight suit.","category":"PPE"},{"id":"c09_fc07","question":"PPE Level B?","answer":"SCBA + splash-protective (non-encapsulating) suit.","category":"PPE"},{"id":"c09_fc08","question":"PPE Level C?","answer":"Air-purifying respirator + splash suit — known agent, adequate O2.","category":"PPE"},{"id":"c09_fc09","question":"Single most effective decon step?","answer":"Removing clothing — removes most external contamination (~80–90% often quoted).","category":"Decon"},{"id":"c09_fc10","question":"Dry vs wet decon?","answer":"Dry (blot/wipe) is default for most exposures; wet (high-volume, low-pressure water) for caustics, visible liquid contamination, or symptomatic patients.","category":"Decon"},{"id":"c09_fc11","question":"Types of decon?","answer":"Gross/emergency, mass, and technical decontamination.","category":"Decon"},{"id":"c09_fc12","question":"Where does EMS without HazMat training work?","answer":"Cold zone — receive patients after decon.","category":"PPE"}]},"c10":{"chapter":"c10","cards":[{"id":"c10_fc01","question":"Mechanism of nerve agents?","answer":"Inhibit acetylcholinesterase → excess acetylcholine at muscarinic, nicotinic, and CNS receptors.","category":"Nerve Agents"},{"id":"c10_fc02","question":"Nerve agent 'killer B's'?","answer":"Bronchorrhea, Bronchospasm, Bradycardia.","category":"Nerve Agents"},{"id":"c10_fc03","question":"Atropine endpoint in nerve-agent poisoning?","answer":"Drying of bronchial secretions and easy breathing — not heart rate or pupil size.","category":"Nerve Agents"},{"id":"c10_fc04","question":"DuoDote/ATNAA contents?","answer":"Atropine 2.1 mg + pralidoxime 600 mg, IM auto-injector.","category":"Antidotes"},{"id":"c10_fc05","question":"Kit dosing for severe nerve-agent poisoning?","answer":"3 kits in rapid succession + benzodiazepine (e.g., midazolam 10 mg IM) for seizures; repeat atropine as needed.","category":"Antidotes"},{"id":"c10_fc06","question":"Why give pralidoxime early?","answer":"It must reactivate acetylcholinesterase before the agent–enzyme bond 'ages' (soman: minutes).","category":"Antidotes"},{"id":"c10_fc07","question":"Cyanide antidote and adult dose?","answer":"Hydroxocobalamin 5 g IV over ~15 min (child 70 mg/kg); may repeat.","category":"Cyanide"},{"id":"c10_fc08","question":"When should you suspect cyanide?","answer":"Enclosed-space fire victims with altered mental status, hypotension, seizures, or arrest; sudden collapse near an industrial/terror source.","category":"Cyanide"},{"id":"c10_fc09","question":"Chlorine vs phosgene presentation?","answer":"Chlorine: immediate upper-airway/eye irritation (water-soluble). Phosgene: mild early, delayed pulmonary edema 2–24 h (poorly soluble).","category":"Choking Agents"},{"id":"c10_fc10","question":"Key management for phosgene exposure?","answer":"Remove, O2, enforced rest, observe ~24 h — no antidote.","category":"Choking Agents"},{"id":"c10_fc11","question":"Sulfur mustard features?","answer":"Garlic odor, painless exposure, delayed erythema/blisters 2–24 h; decon immediately; no antidote.","category":"Vesicants"},{"id":"c10_fc12","question":"Lewisite antidote?","answer":"BAL (dimercaprol).","category":"Vesicants"},{"id":"c10_fc13","question":"Riot-control agent management?","answer":"Remove to fresh air, irrigate eyes, remove contaminated clothing; usually resolves in 15–30 min; watch asthmatics.","category":"Riot Agents"},{"id":"c10_fc14","question":"How to distinguish opioid agent vs nerve agent?","answer":"Both miosis; opioids are DRY with no fasciculations; nerve agents are WET with fasciculations ± seizures.","category":"Opioid Agents"}]},"c11":{"chapter":"c11","cards":[{"id":"c11_fc01","question":"Name the CDC Category A bioterrorism agents.","answer":"Anthrax, botulism, plague, smallpox, tularemia, viral hemorrhagic fevers.","category":"Bio"},{"id":"c11_fc02","question":"Which Category A agents spread person-to-person?","answer":"Smallpox (airborne/contact), pneumonic plague (droplet), VHF (contact with body fluids).","category":"Bio"},{"id":"c11_fc03","question":"PPE for suspected smallpox?","answer":"Airborne + contact: fit-tested N95/PAPR, gown, gloves, eye protection; mask the patient.","category":"Bio"},{"id":"c11_fc04","question":"Inhalational anthrax key features?","answer":"Flu-like prodrome → severe dyspnea, shock; widened mediastinum; not contagious person-to-person.","category":"Bio"},{"id":"c11_fc05","question":"Botulism presentation?","answer":"Alert, afebrile patient with descending symmetric flaccid paralysis: diplopia, ptosis, dysarthria, dysphagia → respiratory failure.","category":"Bio"},{"id":"c11_fc06","question":"Smallpox vs chickenpox rash?","answer":"Smallpox: synchronous lesions, centrifugal (face/extremities, palms/soles). Chickenpox: asynchronous crops, centripetal (trunk).","category":"Bio"},{"id":"c11_fc07","question":"Exposure vs contamination?","answer":"Exposure: radiation passed through — patient not radioactive. Contamination: radioactive material on/in the body — remove clothing, wash.","category":"Rad"},{"id":"c11_fc08","question":"Three principles of radiation protection?","answer":"Time, distance, shielding (ALARA).","category":"Rad"},{"id":"c11_fc09","question":"Inverse-square law?","answer":"Doubling the distance from a point source reduces the dose rate to one quarter.","category":"Rad"},{"id":"c11_fc10","question":"EPA emergency-worker dose guidelines?","answer":"~5 rem general; ~10 rem protecting valuable property; ~25 rem lifesaving/protecting large populations; higher only for informed volunteers.","category":"Rad"},{"id":"c11_fc11","question":"What is an RDD?","answer":"Radiological dispersal device ('dirty bomb'): conventional explosive spreading radioactive material — blast causes most injuries.","category":"Rad"},{"id":"c11_fc12","question":"What does potassium iodide protect against?","answer":"Only thyroid uptake of radioactive iodine.","category":"Rad"},{"id":"c11_fc13","question":"Public message after a nuclear detonation?","answer":"Get inside, stay inside, stay tuned — shelter deep inside a sturdy building until advised.","category":"Rad"},{"id":"c11_fc14","question":"Time to vomiting in ARS — significance?","answer":"Earlier vomiting = higher dose; vomiting within ~1 h suggests a severe dose.","category":"Rad"}]},"c12":{"chapter":"c12","cards":[{"id":"c12_fc01","question":"Primary blast injury?","answer":"Pressure-wave injury to air-filled organs: TMs, lungs (blast lung), bowel.","category":"Blast"},{"id":"c12_fc02","question":"Most common cause of blast injuries?","answer":"Secondary blast injury — fragments/debris (penetrating).","category":"Blast"},{"id":"c12_fc03","question":"Tertiary blast injury?","answer":"Body thrown or structure collapse: blunt trauma, traumatic amputation, crush.","category":"Blast"},{"id":"c12_fc04","question":"Quaternary blast injury?","answer":"All other explosion-related injury: burns, toxic inhalation, CO, exacerbated illness.","category":"Blast"},{"id":"c12_fc05","question":"Blast lung signs?","answer":"Dyspnea, hypoxia, cough, hemoptysis, chest pain — possibly delayed 24–48 h.","category":"Blast"},{"id":"c12_fc06","question":"Is TM rupture a reliable marker of blast lung?","answer":"No — it indicates significant pressure exposure, but its absence doesn't exclude blast lung.","category":"Blast"},{"id":"c12_fc07","question":"Why do enclosed-space blasts cause more primary injury?","answer":"The pressure wave reflects off walls, amplifying and prolonging overpressure.","category":"Blast"},{"id":"c12_fc08","question":"TECC Direct Threat care?","answer":"Return fire/move to cover, self-aid, tourniquet for life-threatening extremity bleeding only.","category":"TECC"},{"id":"c12_fc09","question":"TECC Indirect Threat care?","answer":"MARCH: reassess TQ, pack wounds, airway positioning/NPA, chest seal, needle decompression, hypothermia prevention.","category":"TECC"},{"id":"c12_fc10","question":"Expand THREAT.","answer":"Threat suppression, Hemorrhage control, Rapid Extrication to safety, Assessment by medical providers, Transport.","category":"Active Shooter"},{"id":"c12_fc11","question":"What is a Rescue Task Force?","answer":"EMS/fire in ballistic PPE escorted by law enforcement into cleared warm zones to treat hemorrhage and extract casualties to a CCP.","category":"Active Shooter"},{"id":"c12_fc12","question":"What is upside-down triage?","answer":"Less-injured victims flee and reach nearby hospitals first, before the critically injured.","category":"Hospitals"}]},"c13":{"chapter":"c13","cards":[{"id":"c13_fc01","question":"What causes death at release in crush syndrome?","answer":"Sudden release of potassium, acid, and myoglobin → hyperkalemic arrhythmia/cardiac arrest.","category":"Crush"},{"id":"c13_fc02","question":"Pre-release fluid for crush syndrome?","answer":"Normal saline ~1–1.5 L/h (adult) before extrication; avoid potassium-containing fluids.","category":"Crush"},{"id":"c13_fc03","question":"Drugs to prepare for crush hyperkalemia?","answer":"Calcium (chloride/gluconate), sodium bicarbonate, nebulized albuterol — per protocol.","category":"Crush"},{"id":"c13_fc04","question":"Mechanism of death in crowd crush?","answer":"Compressive (traumatic) asphyxia.","category":"Crowds"},{"id":"c13_fc05","question":"Signs of traumatic asphyxia?","answer":"Facial/neck plethora, petechiae, subconjunctival hemorrhage, hypoxia.","category":"Crowds"},{"id":"c13_fc06","question":"Crowd density danger threshold?","answer":"About 4–5 people per m² and rising, when individuals can't move independently.","category":"Crowds"},{"id":"c13_fc07","question":"First hazard step at a rail incident?","answer":"Isolate power (overhead lines/third rail) before approaching.","category":"Transport"},{"id":"c13_fc08","question":"Why get the passenger manifest?","answer":"Transport incidents are closed — the manifest lets you account for every occupant.","category":"Transport"},{"id":"c13_fc09","question":"Floodwater danger depths?","answer":"~6 inches (15 cm) of moving water can knock a person down; ~1 foot (30 cm) can float most cars.","category":"Natural"},{"id":"c13_fc10","question":"Priority in heat stroke?","answer":"Rapid cooling on scene (cold-water immersion best) before transport.","category":"Natural"},{"id":"c13_fc11","question":"Key protective steps for unaccompanied minors?","answer":"Identify, photograph, tag, keep in a supervised safe area, release only to verified guardians.","category":"Vulnerable"},{"id":"c13_fc12","question":"Technology-dependent patients in disasters?","answer":"Home ventilators, O2 concentrators, dialysis, insulin — power/supply loss creates emergencies; plan early evacuation/power.","category":"Vulnerable"}]},"c14":{"chapter":"c14","cards":[{"id":"c14_fc01","question":"What must reconcile before closing an MCI?","answer":"Patient counts: triage tags = transport log = hospital arrivals (+ dead and released on scene).","category":"Demob"},{"id":"c14_fc02","question":"Why demobilize in phases?","answer":"Late-found patients, re-triage needs, rehab, and possible re-escalation.","category":"Demob"},{"id":"c14_fc03","question":"Demobilization checklist per unit?","answer":"Crew accounted for and checked, equipment decontaminated, restocked, returned to service, release logged.","category":"Demob"},{"id":"c14_fc04","question":"What is a hot wash?","answer":"Short, informal debrief immediately after the incident: what worked, what didn't, immediate safety issues.","category":"Review"},{"id":"c14_fc05","question":"Four AAR questions?","answer":"What was supposed to happen? What happened? Why the difference? What to sustain/improve?","category":"Review"},{"id":"c14_fc06","question":"Exercise types to test MCI plans?","answer":"Tabletop, functional, full-scale exercises (HSEEP).","category":"Review"},{"id":"c14_fc07","question":"Rehab trigger example (NFPA 1584)?","answer":"After two 30-minute SCBA cylinders or ~40 minutes of intense work.","category":"Rehab"},{"id":"c14_fc08","question":"What is Psychological First Aid?","answer":"Evidence-informed support: ensure safety/needs, listen without forcing details, link to support — 'Look, Listen, Link'.","category":"Resilience"},{"id":"c14_fc09","question":"Is mandatory single-session debriefing recommended?","answer":"No — it doesn't prevent PTSD and may cause harm; use PFA and voluntary peer support.","category":"Resilience"},{"id":"c14_fc10","question":"When to refer a responder for mental-health care?","answer":"Symptoms persisting beyond ~1 month, worsening function, substance misuse, or any suicidal thoughts (immediately).","category":"Resilience"},{"id":"c14_fc11","question":"Key MCI documents?","answer":"Triage tags, transport log, unit assignments/times, TQ times, antidotes/decon, exposure logs, ePCRs.","category":"Documentation"}]}},"quizzes":{"c01":{"chapter":"c01","questions":[{"id":"c01_q01","question":"An MCI is BEST defined as:","options":["A. Any incident where casualties exceed immediately available resources","B. Any incident requiring a helicopter","C. Any incident with 10 or more patients","D. Any incident declared by a hospital"],"correct":0,"rationale":"The resource gap defines an MCI. A fixed number is only a local activation tier.","difficulty":"Easy"},{"id":"c01_q02","question":"A tour bus rolls over with 32 passengers aboard. All are accounted for. This is a(n):","options":["A. Compound incident","B. Open incident","C. Closed incident","D. Uncompensated incident"],"correct":2,"rationale":"The number of victims is finite and known — a closed (contained) incident.","difficulty":"Easy"},{"id":"c01_q03","question":"An earthquake damages the regional hospital and cuts the main highway. This is BEST described as:","options":["A. Simple, closed","B. Simple, open","C. Compound, open","D. Compound, closed"],"correct":2,"rationale":"Infrastructure damage = compound; unknown, growing victim numbers in an earthquake = open.","difficulty":"Medium"},{"id":"c01_q04","question":"Which pairing of disaster type and dominant injury is CORRECT?","options":["A. Earthquake — crush injury","B. Flood — blast lung","C. Tornado — drowning","D. Heat wave — penetrating trauma"],"correct":0,"rationale":"Earthquakes cause entrapment and crush; tornadoes cause penetrating debris and blunt trauma.","difficulty":"Easy"},{"id":"c01_q05","question":"Three days after a hurricane, several family members are found confused with headache in a closed house running a generator. Most likely cause:","options":["A. Carbon monoxide poisoning","B. Heat stroke","C. Dehydration","D. Food poisoning"],"correct":0,"rationale":"Generator use indoors after storms is a classic delayed killer — CO poisoning. Get everyone out and give high-flow O2.","difficulty":"Easy"},{"id":"c01_q06","question":"Pandemics are classified as which type of natural disaster?","options":["A. Biological","B. Geophysical","C. Hydrological","D. Climatological"],"correct":0,"rationale":"Epidemics/pandemics fall under the biological natural-hazard group.","difficulty":"Easy"},{"id":"c01_q07","question":"The MCI mindset shift is from:","options":["A. Maximum care for each patient to the most good for the most patients","B. Speed to accuracy","C. BLS to ALS","D. Transport to treatment"],"correct":0,"rationale":"MCI care rations resources to maximize survivors overall.","difficulty":"Easy"},{"id":"c01_q08","question":"Which phase of the disaster cycle includes MCI drills and stocking triage tags?","options":["A. Recovery","B. Preparedness","C. Mitigation","D. Response"],"correct":1,"rationale":"Planning, training, exercises, and equipment caches are preparedness.","difficulty":"Easy"},{"id":"c01_q09","question":"The primary mechanism of death in a crowd crush is:","options":["A. Hypothermia","B. Head injury from falls","C. Penetrating trauma","D. Compressive asphyxia"],"correct":3,"rationale":"Sustained chest compression prevents ventilation — traumatic/compressive asphyxia.","difficulty":"Medium"},{"id":"c01_q10","question":"A second explosion occurs 20 minutes after the first at the same scene. Your FIRST consideration is:","options":["A. Gas leak only","B. Industrial accident","C. Intentional event with secondary devices targeting responders","D. Hoax"],"correct":2,"rationale":"Repeat events suggest an intentional attack; withdraw, stage away, and coordinate with law enforcement.","difficulty":"Medium"}]},"c02":{"chapter":"c02","questions":[{"id":"c02_q01","question":"You are first on scene at a multi-vehicle pile-up with ~20 patients. Your FIRST action is to:","options":["A. Begin extrication","B. Establish command and send a METHANE report","C. Treat the most critical patient","D. Start transporting the walking wounded"],"correct":1,"rationale":"Command and communication come before treatment. The first crew sets up the incident.","difficulty":"Easy"},{"id":"c02_q02","question":"In METHANE, 'E' (the first one) stands for:","options":["A. Emergency services","B. Estimated casualties","C. Evacuation","D. Exact location"],"correct":3,"rationale":"M-E-T-H-A-N-E: the first E is Exact location; the last E is Emergency services present/required.","difficulty":"Easy"},{"id":"c02_q03","question":"Which element of METHANE tells incoming units the safest approach route and rendezvous point?","options":["A. T","B. H","C. A","D. N"],"correct":2,"rationale":"A = Access and egress.","difficulty":"Easy"},{"id":"c02_q04","question":"CSCATTT places TRIAGE after:","options":["A. Nothing — it's first","B. Assessment","C. Transport","D. Treatment"],"correct":1,"rationale":"Command, Safety, Communication, Assessment, then Triage, Treatment, Transport.","difficulty":"Easy"},{"id":"c02_q05","question":"The best way to report casualty numbers early in an incident is:","options":["A. Wait until all are counted","B. Report only the dead","C. Leave it to the hospital","D. Give an estimate with severity breakdown"],"correct":3,"rationale":"Early estimates let resources move. Refine numbers in later updates.","difficulty":"Easy"},{"id":"c02_q06","question":"You arrive and see 6 office workers collapsed in a lobby, no trauma, two seizing. You should:","options":["A. Start triage at the door","B. Withdraw, isolate upwind, report a suspected chemical incident and request HazMat","C. Run in and open airways","D. Ventilate with BVM"],"correct":1,"rationale":"Multiple collapsed people without trauma = chemical until proven otherwise. Entering makes you casualty #7.","difficulty":"Medium"},{"id":"c02_q07","question":"Why are 10-codes discouraged in MCI radio traffic?","options":["A. Hospitals cannot hear them","B. They are too slow","C. They are illegal","D. They differ between agencies and cause confusion"],"correct":3,"rationale":"NIMS requires plain language to ensure interoperability across agencies.","difficulty":"Easy"},{"id":"c02_q08","question":"In the first-due crew, the member NOT in command should:","options":["A. Perform a rapid recon and global sort, feeding numbers to command","B. Start IVs on red patients","C. Stay in the cab","D. Drive to the hospital"],"correct":0,"rationale":"Recon and global triage give command the 'N' for METHANE.","difficulty":"Medium"},{"id":"c02_q09","question":"Which METHANE element is MOST often forgotten and endangers incoming crews?","options":["A. Hazards","B. Exact location","C. Type","D. Number"],"correct":0,"rationale":"Omitting hazards sends crews into fire, chemicals, traffic, or violence.","difficulty":"Medium"},{"id":"c02_q10","question":"A good follow-up update structure after METHANE is:","options":["A. SAMPLE","B. OPQRST","C. CAN — Conditions, Actions, Needs","D. SOAP"],"correct":2,"rationale":"CAN updates keep command and dispatch synchronized.","difficulty":"Easy"}]},"c03":{"chapter":"c03","questions":[{"id":"c03_q01","question":"Which is a Command Staff position?","options":["A. Operations Section Chief","B. Logistics Section Chief","C. Triage Unit Leader","D. Safety Officer"],"correct":3,"rationale":"Command Staff = Safety, PIO, Liaison. They report directly to the IC.","difficulty":"Easy"},{"id":"c03_q02","question":"The optimal span of control in ICS is approximately:","options":["A. 1:2","B. 1:5","C. 1:12","D. 1:20"],"correct":1,"rationale":"3–7 subordinates, with 5 considered optimal.","difficulty":"Easy"},{"id":"c03_q03","question":"A 'Medical Group' is named so because it is defined by:","options":["A. Geography","B. Shift","C. Function","D. Agency"],"correct":2,"rationale":"Groups are functional; Divisions are geographic.","difficulty":"Medium"},{"id":"c03_q04","question":"The person in charge of an ICS Branch is titled:","options":["A. Director","B. Leader","C. Chief","D. Supervisor"],"correct":0,"rationale":"Section–Chief, Branch–Director, Division/Group–Supervisor, Unit–Leader.","difficulty":"Medium"},{"id":"c03_q05","question":"A battalion chief arrives on scene. Command is transferred when:","options":["A. The chief arrives","B. Dispatch decides","C. The chief's rank is higher","D. A face-to-face briefing occurs and the transfer is announced"],"correct":3,"rationale":"Arrival alone does not transfer command. Brief, accept, announce.","difficulty":"Medium"},{"id":"c03_q06","question":"Unified Command is used when:","options":["A. Multiple agencies share jurisdiction over an incident","B. The incident is over","C. The IC is injured","D. Only one agency responds"],"correct":0,"rationale":"UC lets fire, police, EMS, and others share one set of objectives without surrendering authority.","difficulty":"Easy"},{"id":"c03_q07","question":"Which section would source extra oxygen cylinders and backboards for a prolonged incident?","options":["A. Planning","B. Operations","C. Finance","D. Logistics"],"correct":3,"rationale":"Logistics supports the incident with supplies, facilities, and equipment.","difficulty":"Easy"},{"id":"c03_q08","question":"An MCI supervisor is directly managing 11 ambulance crews. The ICS fix is to:","options":["A. Work faster","B. Ignore span of control in emergencies","C. Add a supervisory layer (e.g., group/division or unit leaders)","D. Send some crews home"],"correct":2,"rationale":"When span is exceeded, expand the organization — modularity is the point of ICS.","difficulty":"Medium"},{"id":"c03_q09","question":"Who may immediately stop an unsafe act on scene without waiting for the IC?","options":["A. PIO","B. Finance Chief","C. Safety Officer","D. Liaison Officer"],"correct":2,"rationale":"The Safety Officer has authority to halt unsafe acts immediately.","difficulty":"Easy"},{"id":"c03_q10","question":"An off-duty EMT drives to the scene and starts treating patients without checking in. This is:","options":["A. Freelancing — an accountability and safety problem","B. Mutual aid","C. Encouraged in MCIs","D. Unified command"],"correct":0,"rationale":"Everyone checks in and receives an assignment. Freelancers can't be tracked or protected.","difficulty":"Easy"}]},"c04":{"chapter":"c04","questions":[{"id":"c04_q01","question":"Which task belongs to the Transport Officer?","options":["A. Applying tourniquets","B. Global sort of casualties","C. Assigning destination hospitals and logging each departure","D. Setting up red/yellow/green treatment zones"],"correct":2,"rationale":"Transport matches patients to vehicles and hospitals and tracks them.","difficulty":"Easy"},{"id":"c04_q02","question":"The Triage Officer encounters a patient with arterial bleeding from the thigh. They should:","options":["A. Start two large-bore IVs","B. Apply a tourniquet, tag, and move on","C. Package and transport","D. Ignore — triage only"],"correct":1,"rationale":"Hemorrhage control is a seconds-long LSI permitted during triage.","difficulty":"Easy"},{"id":"c04_q03","question":"Where should ambulances wait until called?","options":["A. At the treatment area","B. At the hospital","C. In the staging area","D. At the command post"],"correct":2,"rationale":"Staging keeps uncommitted units organized and out of the scene until the Transport Officer requests them.","difficulty":"Easy"},{"id":"c04_q04","question":"Who sets up the red/yellow/green zones of the treatment area?","options":["A. Staging Officer","B. Treatment Officer","C. Triage Officer","D. PIO"],"correct":1,"rationale":"The Treatment Officer establishes and runs the treatment area.","difficulty":"Easy"},{"id":"c04_q05","question":"The best way for hospitals to receive MCI information is:","options":["A. Each ambulance calls its own destination","B. A single Medical Communications Coordinator / hospital coordination point","C. Patients phone ahead","D. Media reports"],"correct":1,"rationale":"One voice prevents duplicate calls and gives an accurate picture of distribution.","difficulty":"Medium"},{"id":"c04_q06","question":"A crew arrives and asks staging 'Can we just go grab a patient?' The correct reply is:","options":["A. Self-select the sickest","B. No — wait with the vehicle until the Transport Officer calls you to the loading zone","C. Yes, the closest one","D. Go to the command post"],"correct":1,"rationale":"Self-dispatch breaks tracking and distribution.","difficulty":"Easy"},{"id":"c04_q07","question":"Dead victims at an MCI should generally be:","options":["A. Left in place unless blocking access to the living","B. Moved immediately to the treatment area","C. Transported first","D. Covered and put in an ambulance"],"correct":0,"rationale":"Leave in place: preserves resources, the scene, and identification.","difficulty":"Easy"},{"id":"c04_q08","question":"Which is NOT a role of the EMS Incident Commander?","options":["A. Assigning triage and transport officers","B. Coordinating with police and fire","C. Requesting resources","D. Inserting an advanced airway on a red patient"],"correct":3,"rationale":"The IC does not provide hands-on care.","difficulty":"Easy"},{"id":"c04_q09","question":"The treatment area is full and nothing is leaving. The MOST likely failure is in:","options":["A. Triage","B. PIO","C. Transport/staging flow","D. Finance"],"correct":2,"rationale":"Treatment areas back up when transport and staging aren't moving vehicles efficiently.","difficulty":"Medium"},{"id":"c04_q10","question":"A transport log primarily ensures:","options":["A. Every patient can be located — which unit took them and to which hospital","B. Media can be briefed","C. Crew overtime is recorded","D. Billing accuracy"],"correct":0,"rationale":"Tracking reunites families, informs hospitals, and supports re-triage and accountability.","difficulty":"Easy"}]},"c05":{"chapter":"c05","questions":[{"id":"c05_q01","question":"The decontamination corridor is located in the:","options":["A. Hot zone","B. Cold zone","C. Staging area","D. Warm zone"],"correct":3,"rationale":"Decon happens in the warm (contamination reduction) zone.","difficulty":"Easy"},{"id":"c05_q02","question":"The treatment area should be:","options":["A. At the hospital","B. Inside the hot zone for speed","C. Downwind for ventilation","D. In the cold zone, upwind, next to the loading zone"],"correct":3,"rationale":"Safety plus flow: cold zone, upwind, adjacent to the loading zone.","difficulty":"Easy"},{"id":"c05_q03","question":"Which part of the treatment area should be closest to the ambulance loading exit?","options":["A. Green","B. Yellow","C. Red","D. Black"],"correct":2,"rationale":"Reds are transported first.","difficulty":"Easy"},{"id":"c05_q04","question":"Ambulances should move through the scene:","options":["A. In any direction","B. On a one-way loop: staging → loading zone → hospital","C. By reversing into the treatment area","D. Only after all patients are treated"],"correct":1,"rationale":"One-way vehicle flow keeps the scene moving and safe.","difficulty":"Easy"},{"id":"c05_q05","question":"A suspected pipe bomb is found near the treatment area. The minimum mandatory evacuation distance is approximately:","options":["A. 10 ft","B. 70 ft","C. 500 ft","D. 1 mile"],"correct":1,"rationale":"≈70 ft mandatory; ≈1,200 ft preferred outdoor evacuation per stand-off charts — move the treatment area.","difficulty":"Medium"},{"id":"c05_q06","question":"The helicopter landing zone should be placed:","options":["A. In the warm zone","B. In the cold zone away from the treatment area","C. On the access road used by ambulances","D. Next to the red treatment area"],"correct":1,"rationale":"Rotor wash throws debris; the LZ also shouldn't block ground flow.","difficulty":"Easy"},{"id":"c05_q07","question":"Which statement about zones is TRUE?","options":["A. Zones can move as wind, threat, or structure changes","B. The cold zone has no hazards ever","C. Only police mark zones","D. Zones are fixed once set"],"correct":0,"rationale":"Re-evaluate zones continuously, especially wind in chemical incidents.","difficulty":"Medium"},{"id":"c05_q08","question":"Staging during a suspected terrorist bombing should be:","options":["A. At the hospital entrance","B. Next to the blast site","C. At the most obvious nearby parking lot","D. Out of sight, in a location checked for secondary devices"],"correct":3,"rationale":"Secondary devices may target predictable responder gathering points.","difficulty":"Medium"}]},"c06":{"chapter":"c06","questions":[{"id":"c06_q01","question":"Under START, a patient who walks to the designated area is tagged:","options":["A. Deceased","B. Immediate","C. Delayed","D. Minor"],"correct":3,"rationale":"Ambulatory patients are tagged Minor (green) and re-triaged later.","difficulty":"Easy"},{"id":"c06_q02","question":"A non-ambulatory adult has RR 32, radial pulse present, follows commands. START category:","options":["A. Minor","B. Delayed","C. Deceased","D. Immediate"],"correct":3,"rationale":"RR > 30 → Immediate.","difficulty":"Easy"},{"id":"c06_q03","question":"A non-ambulatory adult has RR 30, radial pulse present, CRT 1 s, follows commands. START category:","options":["A. Deceased","B. Immediate","C. Delayed","D. Minor"],"correct":2,"rationale":"The criterion is MORE than 30; 30 passes. Perfusion and mental status are normal → Delayed.","difficulty":"Medium"},{"id":"c06_q04","question":"An adult is apneic. After you reposition the airway, he begins breathing. Tag:","options":["A. Immediate","B. Minor","C. Delayed","D. Deceased"],"correct":0,"rationale":"Breathing only after airway positioning → Immediate.","difficulty":"Easy"},{"id":"c06_q05","question":"An adult has RR 18, absent radial pulse. Tag:","options":["A. Deceased","B. Delayed","C. Minor","D. Immediate"],"correct":3,"rationale":"Perfusion failure → Immediate.","difficulty":"Easy"},{"id":"c06_q06","question":"An adult has RR 16, strong radial pulse, but cannot follow simple commands. Tag:","options":["A. Expectant","B. Delayed","C. Immediate","D. Minor"],"correct":2,"rationale":"Altered mental status (can't follow commands) → Immediate.","difficulty":"Easy"},{"id":"c06_q07","question":"JumpSTART: a 4-year-old is apneic after airway positioning but has a palpable pulse. Next step:","options":["A. Give 5 rescue breaths and reassess","B. Tag deceased","C. Tag immediate without breaths","D. Start CPR"],"correct":0,"rationale":"5 rescue breaths; if breathing resumes → Immediate; if not → Deceased.","difficulty":"Medium"},{"id":"c06_q08","question":"JumpSTART: a 3-year-old has RR 12. Tag:","options":["A. Delayed","B. Minor","C. Immediate","D. Deceased"],"correct":2,"rationale":"RR < 15 → Immediate.","difficulty":"Easy"},{"id":"c06_q09","question":"JumpSTART: a 6-year-old has RR 30, palpable peripheral pulse, alert, deformed femur, can't walk. Tag:","options":["A. Deceased","B. Minor","C. Immediate","D. Delayed"],"correct":3,"rationale":"RR 15–45, pulse present, Alert → Delayed.","difficulty":"Medium"},{"id":"c06_q10","question":"JumpSTART: a 5-year-old responds to pain only with abnormal flexion (posturing). Tag:","options":["A. Minor","B. Immediate","C. Delayed","D. Deceased"],"correct":1,"rationale":"Inappropriate P (posturing) → Immediate.","difficulty":"Medium"},{"id":"c06_q11","question":"Which is NOT performed during START primary triage?","options":["A. CPR","B. Tourniquet for arterial bleeding","C. Positioning the airway","D. Asking the patient to follow a command"],"correct":0,"rationale":"CPR is not performed during mass-casualty triage.","difficulty":"Easy"},{"id":"c06_q12","question":"A night-time winter MCI. The best START perfusion check is:","options":["A. Capillary refill","B. Radial pulse","C. Blood pressure","D. Skin color"],"correct":1,"rationale":"Cold and darkness make CRT unreliable — use the radial pulse.","difficulty":"Medium"}]},"c07":{"chapter":"c07","questions":[{"id":"c07_q01","question":"In SALT, which group is assessed FIRST after global sorting?","options":["A. Wavers","B. Walkers","C. Still casualties / obvious life threats","D. Children"],"correct":2,"rationale":"Still casualties and obvious life threats are most likely to need LSIs.","difficulty":"Easy"},{"id":"c07_q02","question":"Which is a SALT lifesaving intervention?","options":["A. Chest decompression","B. Spinal immobilization","C. IV fluids","D. Splinting"],"correct":0,"rationale":"LSIs: hemorrhage control, airway (± 2 breaths for kids), chest decompression, auto-injector.","difficulty":"Easy"},{"id":"c07_q03","question":"A breathing patient obeys commands, has a peripheral pulse, no respiratory distress, hemorrhage controlled, and an open femur fracture. SALT category:","options":["A. Expectant","B. Minimal","C. Immediate","D. Delayed"],"correct":3,"rationale":"All four YES but injuries aren't minor → Delayed.","difficulty":"Medium"},{"id":"c07_q04","question":"A breathing patient has no peripheral pulse but is likely to survive with care available. SALT category:","options":["A. Delayed","B. Minimal","C. Immediate","D. Expectant"],"correct":2,"rationale":"Any NO + likely survivable → Immediate.","difficulty":"Easy"},{"id":"c07_q05","question":"Expectant patients should receive:","options":["A. Comfort care and re-triage when resources allow","B. CPR","C. Immediate transport","D. Nothing"],"correct":0,"rationale":"Expectant is a resource-based decision; comfort care and re-triage are required.","difficulty":"Easy"},{"id":"c07_q06","question":"In SALT, an apneic child after airway opening should:","options":["A. Receive CPR","B. Be tagged dead immediately","C. Receive consideration of 2 rescue breaths","D. Be tagged expectant"],"correct":2,"rationale":"Children: consider 2 rescue breaths before tagging dead.","difficulty":"Medium"},{"id":"c07_q07","question":"Which is the BEST place to attach a triage tag?","options":["A. Shoe","B. Jacket zipper","C. Stretcher only","D. Limb or neck"],"correct":3,"rationale":"Clothing is cut off in treatment; tags on clothing get lost.","difficulty":"Easy"},{"id":"c07_q08","question":"High over-triage rates in an MCI are associated with:","options":["A. Higher critical mortality","B. Lower critical mortality","C. No effect","D. Faster transport"],"correct":0,"rationale":"Over-triage diverts resources from the truly critical (Frykberg).","difficulty":"Medium"},{"id":"c07_q09","question":"A patient tagged yellow deteriorates in the treatment area. The correct action:","options":["A. Leave the yellow tag","B. Add a second tag","C. Move to green","D. Re-triage to red, note the time, and inform the treatment/transport officers"],"correct":3,"rationale":"Update the category and time; communicate the change.","difficulty":"Easy"},{"id":"c07_q10","question":"Which statement about triage systems is TRUE?","options":["A. SALT is only for chemical events","B. START includes an Expectant step","C. SALT includes LSIs and an Expectant category","D. Triage Sieve is only for children"],"correct":2,"rationale":"SALT integrates LSIs and Expectant; START has no Expectant step.","difficulty":"Medium"}]},"c08":{"chapter":"c08","questions":[{"id":"c08_q01","question":"Which is the MOST appropriate intervention in the MCI treatment area?","options":["A. Two large-bore IVs for every yellow","B. Routine spinal immobilization of all patients","C. Full secondary survey on every patient","D. Tourniquet and wound packing for hemorrhage"],"correct":3,"rationale":"Hemorrhage control changes survival; the others slow flow without proportional benefit.","difficulty":"Easy"},{"id":"c08_q02","question":"The nearest hospital is usually overwhelmed early because:","options":["A. Self-presenting walking wounded arrive first","B. It has no ED","C. It's the trauma center","D. EMS sends no one there"],"correct":0,"rationale":"Upside-down triage: the least injured self-present to the closest hospital.","difficulty":"Easy"},{"id":"c08_q03","question":"Which loading plan is MOST efficient?","options":["A. Wait until all patients are treated","B. All reds in one ambulance","C. One green per ambulance","D. One red + one or two greens per ambulance; greens in bulk by bus with a medic"],"correct":3,"rationale":"Fill seats sensibly and move greens in bulk.","difficulty":"Easy"},{"id":"c08_q04","question":"A hospital receives 30 casualties in the first hour. Its likely total is about:","options":["A. 30","B. 45","C. 60","D. 300"],"correct":2,"rationale":"CDC rule of thumb: roughly double the first-hour count.","difficulty":"Medium"},{"id":"c08_q05","question":"Which patient should be transported FIRST?","options":["A. Stable ankle fracture","B. Penetrating torso wound with signs of shock","C. Minor burns to the hand","D. Anxious walking patient"],"correct":1,"rationale":"Non-compressible torso hemorrhage needs a surgeon now.","difficulty":"Easy"},{"id":"c08_q06","question":"The main reason to log every transport is to:","options":["A. Measure crew speed","B. Track each patient's location for families, hospitals, and accountability","C. Bill correctly","D. Satisfy media"],"correct":1,"rationale":"Tracking keeps patients from 'disappearing'.","difficulty":"Easy"},{"id":"c08_q07","question":"Which statement about hypothermia in MCIs is TRUE?","options":["A. Insulating from the ground is as important as covering","B. Only a winter issue","C. Warm patients do worse","D. Irrelevant for trauma"],"correct":0,"rationale":"Ground contact steals heat fast; hypothermia worsens trauma coagulopathy.","difficulty":"Medium"},{"id":"c08_q08","question":"Hospital capacity during an MCI should be obtained:","options":["A. After arrival","B. From social media","C. By each crew calling ahead","D. Through the Medical Communications Coordinator / hospital coordination center"],"correct":3,"rationale":"A single channel prevents duplicate calls and gives accurate distribution.","difficulty":"Easy"}]},"c09":{"chapter":"c09","questions":[{"id":"c09_q01","question":"You arrive to find 4 workers collapsed near a loading dock, no trauma. Per Step 1-2-3:","options":["A. Start CPR","B. Approach with caution","C. Approach normally","D. Do not approach; withdraw, report, isolate"],"correct":3,"rationale":"Three or more casualties without explanation = do not approach.","difficulty":"Easy"},{"id":"c09_q02","question":"ERG pages listing materials by 4-digit ID number are:","options":["A. Blue","B. Yellow","C. Orange","D. Green"],"correct":1,"rationale":"Yellow = ID number; Blue = name; Orange = guide; Green = distances.","difficulty":"Easy"},{"id":"c09_q03","question":"In the NFPA 704 diamond, the blue section indicates:","options":["A. Special hazard","B. Flammability","C. Health hazard","D. Instability"],"correct":2,"rationale":"Blue = health.","difficulty":"Easy"},{"id":"c09_q04","question":"A placard with hazard class 8 indicates:","options":["A. Corrosives","B. Radioactive material","C. Flammable gas","D. Explosives"],"correct":0,"rationale":"Class 8 = corrosives.","difficulty":"Easy"},{"id":"c09_q05","question":"Which PPE level uses an air-purifying respirator?","options":["A. A","B. B","C. C","D. D"],"correct":2,"rationale":"Level C uses APR/PAPR — requires a known agent and adequate oxygen.","difficulty":"Easy"},{"id":"c09_q06","question":"The most effective initial decon step is:","options":["A. Scrubbing with bleach","B. Removing clothing","C. Wrapping in blankets","D. Antibiotic ointment"],"correct":1,"rationale":"Disrobing removes most contamination fast.","difficulty":"Easy"},{"id":"c09_q07","question":"Wet decon is especially indicated for:","options":["A. Radiological exposure without contamination","B. Vapor-only exposure with no symptoms","C. All patients regardless of exposure","D. Caustic exposures or visible liquid contamination"],"correct":3,"rationale":"Dry decon suffices for most; go wet for caustics/liquids/symptoms.","difficulty":"Medium"},{"id":"c09_q08","question":"A critical contaminated patient with arterial bleeding in the decon line should:","options":["A. Be tagged expectant","B. Receive LSIs (tourniquet) from protected staff during rapid gross decon","C. Wait at the end of the line","D. Skip decon and be transported"],"correct":1,"rationale":"Combine LSIs with rapid decon — never transport contaminated.","difficulty":"Medium"},{"id":"c09_q09","question":"Which statement about Level C PPE is TRUE?","options":["A. Includes SCBA","B. Safe in oxygen-deficient atmospheres","C. Safe in unknown atmospheres","D. Requires a known agent and adequate oxygen"],"correct":3,"rationale":"APRs filter ambient air; they don't supply oxygen.","difficulty":"Medium"},{"id":"c09_q10","question":"ERG green pages tell you:","options":["A. Fire-fighting tactics","B. Material names","C. Initial isolation and protective action distances for toxic-inhalation hazards","D. Hospital locations"],"correct":2,"rationale":"Green = distances for TIH materials.","difficulty":"Easy"}]},"c10":{"chapter":"c10","questions":[{"id":"c10_q01","question":"A subway passenger has pinpoint pupils, copious secretions, wheezing, and muscle twitching. Most likely agent:","options":["A. Nerve agent","B. Cyanide","C. Mustard","D. Chlorine"],"correct":0,"rationale":"Muscarinic + nicotinic signs with miosis = nerve agent.","difficulty":"Easy"},{"id":"c10_q02","question":"Atropine in nerve-agent poisoning is titrated to:","options":["A. Normal blood pressure","B. Heart rate > 100","C. Dry bronchial secretions and easy breathing","D. Pupil dilation"],"correct":2,"rationale":"Secretions and work of breathing are the endpoints.","difficulty":"Medium"},{"id":"c10_q03","question":"A nerve-agent casualty is seizing and apneic. Antidote kit dosing:","options":["A. No kit; ventilate only","B. 1 kit","C. 3 kits + benzodiazepine","D. 2 kits"],"correct":2,"rationale":"Severe poisoning: 3 kits rapidly plus a benzodiazepine; support ventilation.","difficulty":"Medium"},{"id":"c10_q04","question":"Pralidoxime should be given early because:","options":["A. It reverses opioids","B. It's an anticonvulsant","C. It dries secretions","D. Agent–enzyme binding 'ages' and becomes irreversible"],"correct":3,"rationale":"Oximes only work before aging occurs.","difficulty":"Medium"},{"id":"c10_q05","question":"A house-fire victim is hypotensive and unresponsive. Which antidote is most appropriate?","options":["A. Atropine","B. Naloxone","C. Pralidoxime","D. Hydroxocobalamin"],"correct":3,"rationale":"Smoke inhalation → consider cyanide toxicity → hydroxocobalamin.","difficulty":"Easy"},{"id":"c10_q06","question":"Why are nitrites avoided in smoke-inhalation victims?","options":["A. They cause seizures","B. They induce methemoglobinemia, worsening oxygen delivery with CO poisoning","C. They are ineffective","D. They cause bradycardia"],"correct":1,"rationale":"Methemoglobin + carboxyhemoglobin is a dangerous combination.","difficulty":"Advanced"},{"id":"c10_q07","question":"A factory worker exposed to a gas smelling of 'freshly mown hay' feels fine. You should:","options":["A. Advise rest and observation for ~24 h for delayed pulmonary edema","B. Give hydroxocobalamin","C. Release him","D. Give atropine"],"correct":0,"rationale":"Phosgene causes delayed non-cardiogenic pulmonary edema.","difficulty":"Medium"},{"id":"c10_q08","question":"Which agent causes painless exposure with blisters appearing hours later?","options":["A. Sulfur mustard","B. CS gas","C. Chlorine","D. Lewisite"],"correct":0,"rationale":"Mustard is painless at exposure; lesions appear 2–24 h later.","difficulty":"Medium"},{"id":"c10_q09","question":"A theater crowd collapses with pinpoint pupils, slow shallow breathing, dry skin, no twitching. Best treatment:","options":["A. Atropine","B. Ventilation and naloxone","C. Pralidoxime","D. Hydroxocobalamin"],"correct":1,"rationale":"Dry miosis with respiratory depression = opioid agent.","difficulty":"Medium"},{"id":"c10_q10","question":"Most riot-control agent exposures:","options":["A. Cause delayed pulmonary edema in all patients","B. Require atropine","C. Resolve within ~15–30 min after removal to fresh air","D. Need hydroxocobalamin"],"correct":2,"rationale":"Self-limited; watch asthmatics and enclosed-space exposures.","difficulty":"Easy"},{"id":"c10_q11","question":"Chlorine causes early upper-airway symptoms because it is:","options":["A. An enzyme inhibitor","B. Highly water-soluble","C. Radioactive","D. Poorly water-soluble"],"correct":1,"rationale":"Highly soluble gases react with moist upper airways immediately.","difficulty":"Medium"}]},"c11":{"chapter":"c11","questions":[{"id":"c11_q01","question":"Which bioterrorism agent requires airborne + contact precautions?","options":["A. Tularemia","B. Anthrax","C. Smallpox","D. Botulism"],"correct":2,"rationale":"Smallpox spreads by respiratory and contact routes.","difficulty":"Easy"},{"id":"c11_q02","question":"A cluster of previously healthy postal workers presents with severe pneumonia, shock, and widened mediastinum. Most likely:","options":["A. Inhalational anthrax","B. Botulism","C. Influenza","D. Smallpox"],"correct":0,"rationale":"Classic inhalational anthrax; not person-to-person.","difficulty":"Medium"},{"id":"c11_q03","question":"An alert, afebrile patient has double vision, slurred speech, and difficulty swallowing that is progressing downward. Suspect:","options":["A. Botulism","B. Guillain–Barré","C. Nerve agent","D. Stroke"],"correct":0,"rationale":"Descending symmetric flaccid paralysis with clear sensorium = botulism.","difficulty":"Medium"},{"id":"c11_q04","question":"A patient exposed to radiation from a hidden source (no contamination) is:","options":["A. Requires Level A PPE","B. Not radioactive — no risk to responders","C. Contagious","D. Radioactive and dangerous"],"correct":1,"rationale":"Exposure does not make a person radioactive.","difficulty":"Easy"},{"id":"c11_q05","question":"The most effective first step in external radiological decon is:","options":["A. Waiting for a survey meter","B. Removing clothing","C. Scrubbing with bleach","D. KI tablets"],"correct":1,"rationale":"Clothing removal removes most external contamination.","difficulty":"Easy"},{"id":"c11_q06","question":"A dirty-bomb victim has an amputated leg with arterial bleeding and is contaminated. Priority:","options":["A. Wait for radiation team","B. Decon first","C. Tourniquet and trauma care now, decon as part of care","D. KI tablet"],"correct":2,"rationale":"Life threats first; radiation contamination is rarely immediately dangerous.","difficulty":"Easy"},{"id":"c11_q07","question":"Doubling your distance from a radiation source reduces your dose rate to:","options":["A. 1/4","B. No change","C. 1/8","D. 1/2"],"correct":0,"rationale":"Inverse-square law.","difficulty":"Medium"},{"id":"c11_q08","question":"Potassium iodide is indicated when:","options":["A. Treating ARS","B. Any radiation event occurs","C. Radioactive iodine release threatens thyroid uptake","D. For dirty bombs with cesium"],"correct":2,"rationale":"KI blocks thyroid uptake of radioiodine only.","difficulty":"Medium"},{"id":"c11_q09","question":"Under EPA guidance, the dose guideline for lifesaving actions by emergency workers is about:","options":["A. 500 rem","B. 25 rem","C. 0.5 rem","D. 5 rem"],"correct":1,"rationale":"~25 rem for lifesaving/protecting large populations; higher only for informed volunteers.","difficulty":"Advanced"},{"id":"c11_q10","question":"A patient vomited 30 minutes after a radiation exposure. This suggests:","options":["A. A trivial dose","B. Anxiety only","C. Contamination only","D. A high, potentially severe dose"],"correct":3,"rationale":"Early onset of vomiting correlates with higher dose.","difficulty":"Medium"},{"id":"c11_q11","question":"You receive a call about a white powder in an opened envelope at an office. Best initial action:","options":["A. Vacuum the powder","B. Shake the envelope to see contents","C. Isolate the area, keep the envelope still, wash hands with soap and water, notify law enforcement/HazMat","D. Give everyone antibiotics"],"correct":2,"rationale":"Contain, wash, notify; prophylaxis only if testing confirms a threat.","difficulty":"Easy"}]},"c12":{"chapter":"c12","questions":[{"id":"c12_q01","question":"The most common mechanism of injury in explosions is:","options":["A. Secondary","B. Tertiary","C. Quinary","D. Primary"],"correct":0,"rationale":"Fragments and debris injure the most people.","difficulty":"Easy"},{"id":"c12_q02","question":"Which organ is MOST susceptible to primary blast injury?","options":["A. Liver","B. Lungs","C. Spleen","D. Femur"],"correct":1,"rationale":"Air-filled organs: lungs, TMs, bowel.","difficulty":"Easy"},{"id":"c12_q03","question":"A bus-bombing survivor with intact eardrums becomes hypoxic 6 hours later. This:","options":["A. Is CO only","B. Excludes blast lung","C. Is consistent with delayed blast lung","D. Is anxiety"],"correct":2,"rationale":"Blast lung can be delayed; intact TMs don't exclude it.","difficulty":"Medium"},{"id":"c12_q04","question":"In TECC Direct Threat (hot zone), the recommended medical intervention is:","options":["A. IV access","B. Intubation","C. Tourniquet for life-threatening extremity hemorrhage","D. Spinal immobilization"],"correct":2,"rationale":"Only TQ (and moving to cover) under direct threat.","difficulty":"Easy"},{"id":"c12_q05","question":"THREAT's 'H' stands for:","options":["A. Hospital","B. Hazards","C. Hot zone","D. Hemorrhage control"],"correct":3,"rationale":"Threat suppression, Hemorrhage control, Rapid Extrication, Assessment, Transport.","difficulty":"Easy"},{"id":"c12_q06","question":"A Rescue Task Force typically operates in the:","options":["A. Hospital","B. Hot zone without escort","C. Cold zone only","D. Warm zone with law-enforcement escort"],"correct":3,"rationale":"RTFs enter cleared-but-not-secure warm zones with police protection.","difficulty":"Easy"},{"id":"c12_q07","question":"Which management is appropriate for suspected blast lung?","options":["A. O2 and cautious fluids; caution with positive-pressure ventilation","B. Ignore until symptoms worsen","C. Immediate high-pressure ventilation","D. Large-volume fluids"],"correct":0,"rationale":"Avoid fluid overload and barotrauma/air embolism.","difficulty":"Medium"},{"id":"c12_q08","question":"Why should EMS staging be out of sight in a bombing?","options":["A. Radio interference","B. Traffic","C. Secondary devices may target responders","D. Media"],"correct":2,"rationale":"Responders and CCPs are predictable targets.","difficulty":"Easy"},{"id":"c12_q09","question":"Indirect Threat care includes:","options":["A. Only transport","B. Return fire","C. Only tourniquets","D. Wound packing, chest seals, needle decompression, hypothermia prevention"],"correct":3,"rationale":"MARCH-based care when the immediate threat is suppressed.","difficulty":"Easy"},{"id":"c12_q10","question":"Hospitals near a bombing often receive which patients first?","options":["A. Only children","B. The less injured self-presenters","C. Only EMS transports","D. The most critical"],"correct":1,"rationale":"Upside-down triage.","difficulty":"Medium"}]},"c13":{"chapter":"c13","questions":[{"id":"c13_q01","question":"A worker trapped under a beam for 5 hours is about to be released. Which is MOST important first?","options":["A. IV normal saline before release with cardiac monitoring","B. Lactated Ringer's after release","C. Apply ice","D. Release quickly"],"correct":0,"rationale":"Fluids before freedom; monitor for hyperkalemia.","difficulty":"Medium"},{"id":"c13_q02","question":"Why is lactated Ringer's avoided pre-release in crush injury?","options":["A. It causes hypoglycemia","B. It contains potassium","C. It's hypertonic","D. Too expensive"],"correct":1,"rationale":"Hyperkalemia is the main threat at release.","difficulty":"Medium"},{"id":"c13_q03","question":"After extrication, a crush victim's ECG shows peaked T waves and widening QRS. Give:","options":["A. Atropine","B. Calcium","C. Amiodarone","D. Adenosine"],"correct":1,"rationale":"Calcium stabilizes the myocardium in hyperkalemia.","difficulty":"Medium"},{"id":"c13_q04","question":"Crowd crush victims mostly die from:","options":["A. Heat stroke","B. Trampling head injuries","C. Compressive asphyxia","D. Cardiac contusion"],"correct":2,"rationale":"They cannot expand their chests.","difficulty":"Easy"},{"id":"c13_q05","question":"The FIRST hazard control at a rail derailment is:","options":["A. Calling the media","B. Extrication","C. Triage","D. Isolating electrical power"],"correct":3,"rationale":"Overhead lines and third rails kill rescuers.","difficulty":"Easy"},{"id":"c13_q06","question":"Floodwater depth that can knock an adult off their feet if moving:","options":["A. ~6 inches","B. ~3 feet","C. Only above waist","D. ~5 feet"],"correct":0,"rationale":"About 6 inches of moving water can knock a person down.","difficulty":"Easy"},{"id":"c13_q07","question":"A marathon runner collapses, confused, temp 41.5 °C. Best initial action:","options":["A. Cold-water immersion on scene","B. Antipyretics","C. Transport immediately","D. Oral fluids only"],"correct":0,"rationale":"Cool first, transport second for exertional heat stroke.","difficulty":"Medium"},{"id":"c13_q08","question":"An unaccompanied 6-year-old at an MCI should be:","options":["A. Identified, photographed, tagged, and kept supervised until a verified guardian is found","B. Sent home by taxi","C. Left with green patients","D. Released to any adult who claims them"],"correct":0,"rationale":"Reunification is a safety process.","difficulty":"Easy"},{"id":"c13_q09","question":"During a prolonged power outage, which patients are highest priority for proactive outreach?","options":["A. Mild colds","B. Healthy adults","C. Ankle sprains","D. Ventilator and home O2-dependent patients"],"correct":3,"rationale":"Technology-dependent patients deteriorate quickly without power.","difficulty":"Easy"}]},"c14":{"chapter":"c14","questions":[{"id":"c14_q01","question":"Before terminating command, the MOST important check is:","options":["A. Media have left","B. Overtime is approved","C. Patient counts reconcile across tags, transport log, and hospitals","D. All units are home"],"correct":2,"rationale":"A mismatch means a patient may be missing.","difficulty":"Easy"},{"id":"c14_q02","question":"A hot wash is best described as:","options":["A. A media briefing","B. Decontamination of equipment","C. A brief informal debrief right after the incident","D. A formal written report weeks later"],"correct":2,"rationale":"Immediate, short, focused on facts and safety.","difficulty":"Easy"},{"id":"c14_q03","question":"Which approach to responder mental health is recommended?","options":["A. Ignore reactions","B. Psychological First Aid with voluntary peer support and follow-up","C. Immediate medication","D. Mandatory group debriefing for everyone"],"correct":1,"rationale":"PFA is recommended; forced single-session debriefing is not.","difficulty":"Easy"},{"id":"c14_q04","question":"An AAR should be:","options":["A. Written only by the IC","B. Systems-focused with sustain/improve items, owners, and deadlines","C. Focused on blame","D. Optional"],"correct":1,"rationale":"Blame-free, actionable improvement plans drive change.","difficulty":"Easy"},{"id":"c14_q05","question":"Resources should be released:","options":["A. All at once when the last red leaves","B. Only after media leave","C. In phases as they're no longer needed","D. Never until the next day"],"correct":2,"rationale":"Phased demob keeps capacity for late finds and rehab.","difficulty":"Easy"},{"id":"c14_q06","question":"A paramedic reports nightmares and avoidance six weeks after an MCI and is drinking more. Best action:","options":["A. Tell them it's normal and will pass","B. Refer to professional mental-health support and peer support","C. Wait another 6 months","D. Discipline"],"correct":1,"rationale":"Persistent symptoms beyond ~1 month with functional impact warrant referral.","difficulty":"Medium"},{"id":"c14_q07","question":"Equipment used at a chemical MCI must be:","options":["A. Returned to service immediately","B. Decontaminated before returning to service","C. Left on scene","D. Discarded always"],"correct":1,"rationale":"Contaminated equipment injures the next crew and patient.","difficulty":"Easy"},{"id":"c14_q08","question":"The three PFA actions are:","options":["A. Sort, Assess, Treat","B. Stop, Drop, Roll","C. Look, Listen, Link","D. Assess, Treat, Transport"],"correct":2,"rationale":"WHO PFA: Look, Listen, Link.","difficulty":"Easy"}]}},"scenarios":{"c01":{"chapter":"c01","cases":[{"id":"c01_s01","title":"Three Patients, One Ambulance","presentation":"Night call to a rural two-car head-on collision 40 minutes from the nearest hospital. You are the only unit; the next is 30 minutes away. You find three critically injured patients.","vitals":{"patients":"3 critical","units":"1 (yours)","next unit":"30 min"},"question":"Is this an MCI?","options":["A: No — MCIs need at least 10 patients.","B: Only if a hospital declares it.","C: Yes — casualties exceed immediately available resources; declare and request resources.","D: Only if one patient dies."],"correct":2,"explanation":"MCI = patients > resources. Three critical patients for one crew in a remote area is an MCI. Declare early so help starts moving.","clinicalPearl":"Small numbers + few resources = MCI. Declare early, downgrade later."},{"id":"c01_s02","title":"The River Is Still Rising","presentation":"Flash flooding in a low-lying district. Dispatch reports 'about 12 people' stranded. As you arrive, more calls are coming in from adjacent streets; the bridge to the main hospital is closed.","vitals":{"reported":"~12","calls":"increasing","hospital route":"bridge closed"},"question":"How do you classify this incident?","options":["A: Open, simple","B: Closed, compound","C: Open, compound — expect more victims and degraded infrastructure","D: Closed, simple"],"correct":2,"explanation":"Victims are still appearing (open) and infrastructure is damaged (compound). Expect longer scene times, alternate destinations, and request swift-water rescue rather than entering water yourself.","clinicalPearl":"Open + compound = plan for self-sufficiency and longer holds."},{"id":"c01_s03","title":"Week After the Storm","presentation":"Five days after a hurricane, your service is busier than during the storm: a chainsaw laceration, a dialysis patient with weakness and peaked T waves, an elderly woman whose home oxygen ran out, and a family with headaches.","vitals":{"power":"out","pharmacies":"closed","calls":"↑ 40%"},"question":"What is the KEY lesson?","options":["A: These calls are unrelated to the disaster.","B: Disasters cause a delayed wave: CO poisoning, cleanup trauma, and decompensated chronic disease.","C: Only trauma matters after hurricanes.","D: Storm injuries are over once the wind stops."],"correct":1,"explanation":"Post-disaster mortality is driven by CO from generators, cleanup injuries, and loss of dialysis, oxygen, and medications. The family with headaches needs CO screening and removal from the home.","clinicalPearl":"Ask every post-storm household: 'Is a generator running inside or near the house?'"}]},"c02":{"chapter":"c02","cases":[{"id":"c02_s01","title":"The Pull of the First Patient","presentation":"You arrive first at a bus vs. truck collision. A screaming woman with an open femur fracture is right by your door. Through the windshield you see at least 20 more people, some not moving.","vitals":{"your unit":"first & only","patients":"20+","ETA next":"6 min"},"question":"What do you do?","options":["A: Splint the femur — she's right here.","B: Wait for a supervisor.","C: Partner does a quick recon/global sort while you declare MCI, name command, and send METHANE.","D: Load her and transport to clear the scene."],"correct":2,"explanation":"First-in doesn't get sucked in. The open femur can wait seconds; the scene can't run without command. Declare, report, request, then assign triage.","clinicalPearl":"Your first radio transmission is the most valuable intervention you'll do all day."},{"id":"c02_s02","title":"Build the METHANE","presentation":"Gas explosion in a 3-story restaurant at 42 Harbor Rd, rear wall collapsed, smell of gas still present. Approx 15 casualties: 3 critical, 5 serious, 7 walking. Harbor Rd blocked by debris; access via Mill Lane. Your unit and one engine on scene.","vitals":{"location":"42 Harbor Rd","casualties":"~15","access":"Mill Lane"},"question":"Which report is BEST?","options":["A: '15 patients, need ambulances.'","B: 'Explosion at Harbor Rd, lots hurt, will update.'","C: 'Send everyone to the explosion.'","D: 'Major incident declared. 42 Harbor Rd, rear of restaurant. Gas explosion with partial collapse. Hazards: ongoing gas leak, unstable structure. Access via Mill Lane — Harbor Rd blocked. Approx 15: 3 red, 5 yellow, 7 green. On scene: 1 ambulance, 1 engine; request 6 ambulances, USAR, gas utility, police.'"],"correct":3,"explanation":"This hits every METHANE element in one concise transmission, including the critical hazard (gas) and the access change (Mill Lane).","clinicalPearl":"If you can't remember METHANE, read it off the action card on your visor."},{"id":"c02_s03","title":"Quiet Lobby","presentation":"Dispatch: 'multiple people fainted in a subway station.' On arrival you see commuters coughing as they exit, several collapsed on the platform stairs, and pigeons dead near a vent.","vitals":{"down":"≥6, no trauma","odor":"faint","animals":"dead birds"},"question":"Best action?","options":["A: Bring the patients to your ambulance immediately.","B: Stop, withdraw upwind, keep ambulatory exiting patients in one area, report suspected chemical MCI (METHANE) and request HazMat/decon.","C: Enter with a BVM and start triage.","D: Assume heat exhaustion."],"correct":1,"explanation":"Multiple collapsed casualties without trauma + dead animals = chemical clues. Don't approach (Step 1-2-3), control the exiting crowd for decon, and report.","clinicalPearl":"Dead birds and fallen people — don't be the next one down."}]},"c03":{"chapter":"c03","cases":[{"id":"c03_s01","title":"Who's in Charge Here?","presentation":"At a warehouse fire with 14 burned workers, a fire captain and an EMS supervisor both arrive and each starts giving orders to the same ambulance crews. Police set up their own post across the street.","vitals":{"patients":"14 burns","agencies":"Fire, EMS, Police","command posts":"2"},"question":"What fixes this?","options":["A: The highest rank wins.","B: Let dispatch coordinate.","C: Unified Command: co-locate fire, EMS, and police commanders at one command post with one set of objectives; EMS crews report only through the Medical Group.","D: Each agency keeps its own command post."],"correct":2,"explanation":"Multi-jurisdiction incidents use Unified Command. Unity of command for crews is restored by clear EMS supervision within the shared structure.","clinicalPearl":"One incident, one command post, one plan."},{"id":"c03_s02","title":"Too Many Radios","presentation":"You're Medical Group Supervisor at a train derailment. 12 ambulances, 2 rescue teams, and a bus are all calling you directly.","vitals":{"units reporting":"15","you":"Medical Group Supervisor"},"question":"Best ICS move?","options":["A: Send half the ambulances away.","B: Request a second Incident Commander.","C: Turn your radio down.","D: Appoint Triage, Treatment, and Transport Unit Leaders and a Staging Manager; units report to them."],"correct":3,"explanation":"Span of control exceeded → delegate. Unit leaders each supervise a manageable number; you supervise ~4–5 leaders.","clinicalPearl":"When the radio never stops, your org chart is too flat."},{"id":"c03_s03","title":"The Handover","presentation":"You've been IC at a 9-patient bus crash for 15 minutes. The EMS duty chief arrives and says 'I've got it.'","vitals":{"time":"15 min","patients":"9"},"question":"What must happen?","options":["A: Face-to-face briefing: situation, hazards, objectives, resources, org chart; chief accepts; transfer announced to all units; you take a new assignment.","B: Hand over your radio and leave.","C: Nothing — rank transfers command automatically.","D: Ask dispatch to decide."],"correct":0,"explanation":"A formal transfer of command keeps continuity and tells everyone who's in charge. The outgoing IC usually stays in the structure (e.g., as Medical Group Supervisor).","clinicalPearl":"Brief — Accept — Announce."}]},"c04":{"chapter":"c04","cases":[{"id":"c04_s01","title":"You're Wearing the Orange Vest","presentation":"The IC hands you the TRANSPORT vest at a 26-patient bus crash. Three hospitals: General (Level I trauma, 8 min), St. Mary's (community, 5 min), Children's (12 min). 4 red, 8 yellow, 14 green — including 3 injured children.","vitals":{"red":"4","yellow":"8","green":"14 (3 peds)","hospitals":"3"},"question":"Best distribution strategy?","options":["A: Let each ambulance crew decide.","B: Reds to General (trauma center) a few at a time, yellows split between General and St. Mary's, injured children toward Children's per capability, greens by bus with a medic to a less-busy hospital — all logged.","C: Hold everyone until you hear from all hospitals.","D: Everyone to St. Mary's — it's closest."],"correct":1,"explanation":"Match severity to capability and spread the load. Nearby hospitals already get flooded by self-presenters. Log every departure.","clinicalPearl":"Distribute, don't dump."},{"id":"c04_s02","title":"The Triage Officer Who Stayed","presentation":"Fifteen minutes into an apartment-fire MCI, the triage count hasn't been updated since the first report. The triage officer is found inserting an IO in a burned toddler.","vitals":{"time":"15 min","count updates":"0","untagged":"unknown"},"question":"What's the problem and fix?","options":["A: Pause the incident.","B: Nothing — the toddler is critical.","C: Triage has stopped: hand the toddler to the treatment area team, return the triage officer to sorting and reporting counts.","D: Make the triage officer the transport officer."],"correct":2,"explanation":"When the triage officer treats, triage halts and untagged reds go unfound. Lifesaving interventions in triage are seconds-long only.","clinicalPearl":"Triage touches for seconds, then moves."},{"id":"c04_s03","title":"Staging Chaos","presentation":"Mutual-aid ambulances keep driving straight to the scene, blocking the fire apparatus and the loading zone. Two crews have loaded green patients on their own and left.","vitals":{"inbound units":"9","staging":"not established"},"question":"Best fix?","options":["A: Close the road to all ambulances.","B: Let them continue — more transports is good.","C: Ask dispatch to cancel mutual aid.","D: Appoint a Staging Officer, set a staging location in the METHANE update, require check-in, and release units only on Transport Officer request."],"correct":3,"explanation":"Staging restores flow and accountability. Self-dispatching units clog access and lose patient tracking.","clinicalPearl":"Check in, keys in, crews in."}]},"c05":{"chapter":"c05","cases":[{"id":"c05_s01","title":"The Wind Changed","presentation":"Industrial fire with 18 casualties. Your treatment area is set up 150 m east of the plant. Twenty minutes in, a light breeze shifts and smoke begins drifting toward the treatment area. Two treatment staff start coughing.","vitals":{"patients in TA":"12","wind":"now toward TA","smoke":"drifting"},"question":"What now?","options":["A: Hand out surgical masks and continue.","B: Relocate the treatment area upwind immediately, re-mark zones, and inform IC/Safety and Transport of the new loading point.","C: Close the windows of the ambulances.","D: Transport everyone at once to the nearest hospital."],"correct":1,"explanation":"Zones move with the hazard. A treatment area in smoke creates new casualties among patients and staff. Relocate and re-communicate flow.","clinicalPearl":"Check the wind every 15 minutes — tie a strip of tape to an antenna."},{"id":"c05_s02","title":"Gridlock","presentation":"At a stadium MCI, ambulances are driving in from three directions, parking wherever they can, and backing out past the green collection point. Two crews almost hit walking wounded.","vitals":{"ambulances":"14","entry points":"3","loading zone":"undefined"},"question":"Best fix?","options":["A: Ask crews to drive carefully.","B: Move the greens into ambulances.","C: Establish one staging area on a single approach, a defined loading zone at the treatment exit, and a one-way exit route — communicate it to all units.","D: Stop transporting until clear."],"correct":2,"explanation":"Flow design solves congestion: one way in from staging, load, one way out.","clinicalPearl":"Draw the flow on the hood of your rig, then put it on the radio."},{"id":"c05_s03","title":"Second Bag","presentation":"Fifteen minutes after an explosion at a bus terminal, a police officer reports an unattended backpack 20 m from your casualty collection point.","vitals":{"distance":"~20 m","CCP patients":"9"},"question":"Your action?","options":["A: Evacuate the CCP and staff beyond the stand-off distance using cover, avoid radio use near the device, notify IC/police — continue care at the new location.","B: Open the bag to check.","C: Ignore it — police will handle it.","D: Move the backpack away yourself."],"correct":0,"explanation":"Assume a secondary device. Move people out of line-of-sight beyond the stand-off distance; let bomb technicians manage it.","clinicalPearl":"Time, distance, cover — for bombs as for radiation."}]},"c06":{"chapter":"c06","cases":[{"id":"c06_s01","title":"The Quiet Child","presentation":"Apartment collapse. You find a ~5-year-old boy lying still, not breathing. You reposition his airway — still no breathing. You feel a weak radial pulse.","vitals":{"age":"~5","breathing":"none after positioning","pulse":"weak radial"},"question":"Per JumpSTART, what do you do?","options":["A: Tag delayed and return later.","B: Start full CPR.","C: Tag deceased and move on.","D: Give 5 rescue breaths (~15 s): if he breathes → IMMEDIATE; if not → DECEASED."],"correct":3,"explanation":"Pediatric arrests are often respiratory; a child with a pulse may respond to ventilation alone. JumpSTART spends 15 seconds on 5 breaths — never full CPR.","clinicalPearl":"Pulse + apnea in a child = 5 breaths before black."},{"id":"c06_s02","title":"Thirty on the Dot","presentation":"Train derailment. A man pinned by the legs (can't walk) is breathing 30/min, radial pulse strong, CRT 1.5 s, and answers 'yes' when asked to squeeze your hand — and does it.","vitals":{"RR":"30","radial":"present","CRT":"1.5 s","commands":"follows"},"question":"START category?","options":["A: MINOR","B: EXPECTANT","C: DELAYED — RR is not > 30, perfusion and mental status OK.","D: IMMEDIATE — RR is high."],"correct":2,"explanation":"START's cut-off is RR MORE than 30. He passes all three checks → Delayed. Re-triage: entrapment can become crush syndrome.","clinicalPearl":"Know the cut-offs exactly: > 30, > 2 s."},{"id":"c06_s03","title":"Green Who Turned Gray-Skinned","presentation":"45 minutes after a bus crash, a woman tagged GREEN at the walking-wounded point is now pale, sweaty, and says she feels faint. She has left-upper-quadrant abdominal pain.","vitals":{"initial tag":"green","now":"pale, diaphoretic","radial":"weak, fast"},"question":"What does this teach?","options":["A: Walkers can hide internal bleeding — re-triage greens; she now meets IMMEDIATE criteria (perfusion).","B: Tag her deceased.","C: She is anxious; reassure.","D: Green tags are permanent."],"correct":0,"explanation":"START sorts by snapshot physiology. A splenic injury may present late. Re-triage the green area regularly with a medic assigned.","clinicalPearl":"Greens need a babysitter with a stethoscope."},{"id":"c06_s04","title":"Thirty-Second Challenge","presentation":"You've tagged 9 patients in 6 minutes. The 10th, a middle-aged woman, is screaming with an open tib-fib fracture, RR 26, radial pulse strong, follows commands perfectly, bleeding is oozing (not arterial).","vitals":{"RR":"26","radial":"strong","commands":"follows","bleeding":"oozing"},"question":"What's your tag and how long should it take?","options":["A: MINOR — she's talking.","B: Splint first, then tag — 3 minutes.","C: IMMEDIATE because of the open fracture.","D: DELAYED — tag in ~30 s; she's loud but physiologically stable; move on."],"correct":3,"explanation":"Noise and gore don't change START categories. She passes RPM → Delayed. The silent patient behind her may be the red.","clinicalPearl":"Loud is alive — go find the quiet ones."}]},"c07":{"chapter":"c07","cases":[{"id":"c07_s01","title":"Gray or Red?","presentation":"Tanker explosion. 40+ casualties, 4 ambulances on scene, 15 min to the next wave. A man with ~90% full-thickness burns is breathing shallowly, unresponsive, weak pulse.","vitals":{"casualties":"40+","ambulances":"4","burns":"~90% FT"},"question":"SALT category now?","options":["A: DEAD","B: DELAYED","C: IMMEDIATE — he's the sickest.","D: EXPECTANT — survival unlikely with current resources; comfort care and re-triage when resources improve."],"correct":3,"explanation":"SALT's Expectant category exists for this scenario. Resources spent on him now cost several salvageable lives. Provide analgesia/comfort and re-triage as resources arrive.","clinicalPearl":"Gray is 'not now', not 'never' — re-triage when the scene changes."},{"id":"c07_s02","title":"The Lost Tourniquet Time","presentation":"At the hospital, a red patient arrives with a tourniquet on his thigh. No tag notes, no time. Nobody on scene remembers when it went on.","vitals":{"TQ":"thigh","time":"unknown"},"question":"What scene practice would have prevented this?","options":["A: Removing tourniquets before transport.","B: Writing 'TQ + time' on the tag (and/or forehead) at application.","C: Telling the patient to remember.","D: Not applying tourniquets in MCIs."],"correct":1,"explanation":"Tourniquet time drives surgical decision-making. The tag is the record that travels with the patient.","clinicalPearl":"TQ without a time is half a treatment."},{"id":"c07_s03","title":"Red Area Overflowing","presentation":"Your treatment area has 22 'red' patients and 3 yellows from a nightclub stampede. Transport is stalled. On re-triage, 12 of the reds are alert, have good pulses, no respiratory distress, and minor injuries.","vitals":{"red":"22","true reds on re-triage":"~10"},"question":"What happened and what now?","options":["A: Transport in order of arrival.","B: Nothing — better safe than sorry.","C: Over-triage is clogging the red area and transport; re-triage and re-tag downward so true reds move first.","D: Request 22 more ambulances and keep tags."],"correct":2,"explanation":"Over-triage buries true reds and wastes transport. Re-triage corrects it — that's the system working.","clinicalPearl":"Accuracy is a life-saving intervention."}]},"c08":{"chapter":"c08","cases":[{"id":"c08_s01","title":"The Field Hospital Trap","presentation":"Your treatment area has 8 reds. Two paramedics are attempting RSI on one red, another is placing a second IV on a stable yellow. Four ambulances wait empty at the loading zone.","vitals":{"reds waiting":"8","ambulances idle":"4"},"question":"Best correction?","options":["A: Transport yellows first since they're ready.","B: Send ambulances back to staging.","C: Load reds now with essential interventions only (airway positioning/adjuncts, bleeding control, decompression); do advanced procedures en route or at hospital.","D: Finish the procedures first."],"correct":2,"explanation":"Idle ambulances + waiting reds = flow failure. Treat to the minimum that's safe for transport and move.","clinicalPearl":"Empty ambulances are a red flag in the treatment area."},{"id":"c08_s02","title":"Three Hospitals, One Plan","presentation":"Subway derailment: 6 red, 10 yellow, 25 green. Hospitals: Central (Level I, 6 min — already receiving 15 walk-ins), East (community, 12 min, 10 free ED beds), Children's (15 min). 2 reds are children.","vitals":{"red":"6 (2 peds)","yellow":"10","green":"25"},"question":"Best distribution?","options":["A: Greens first to clear the scene.","B: Everyone to Central.","C: Hold all patients until hospitals call back.","D: Adult reds split between Central and the next trauma-capable hospital, pediatric reds toward Children's if stable enough for 15 min, yellows to East, greens by bus to the least-loaded facility — all via Med Comms and logged."],"correct":3,"explanation":"Match capability, respect capacity, and protect the trauma center for those who need it. Central is already flooded by self-presenters.","clinicalPearl":"Ask hospitals for capacity by color: 'How many red, yellow, green can you take?'"}]},"c09":{"chapter":"c09","cases":[{"id":"c09_s01","title":"Placard 1005","presentation":"A tanker on its side on the highway displays a placard: class 2, ID 1005. A faint pungent smell; a motorist downwind is coughing.","vitals":{"placard":"Class 2 · UN1005","wind":"toward traffic"},"question":"Best first steps?","options":["A: Open the valve to vent pressure.","B: Ask the coughing motorist to come to your ambulance.","C: Approach to read the bill of lading.","D: Stop upwind/uphill at distance, look up 1005 in the ERG yellow pages → guide (orange) → isolation/protective distances (green), isolate and deny entry, METHANE with HazMat request."],"correct":3,"explanation":"UN1005 is anhydrous ammonia (a toxic-inhalation gas). The ERG workflow — yellow/blue → orange → green — gives the PPE and distances. Ambulatory exposed people should move upwind and disrobe/decon before coming near you.","clinicalPearl":"ERG: find the number, read the guide, check the green distances."},{"id":"c09_s02","title":"200 Wet Commuters","presentation":"A sprayer releases an oily liquid in a train station. 200 people exit, many with burning eyes, some vomiting. Fire is setting up a ladder-pipe decon corridor.","vitals":{"exposed":"~200","symptoms":"eyes, nausea","liquid":"visible on clothes"},"question":"Your mass-decon priorities?","options":["A: Decon in order of arrival only.","B: Wait for Level A suits for everyone.","C: Tell everyone to remove outer clothing immediately; prioritize symptomatic and visibly contaminated for wet decon; separate ambulatory and non-ambulatory lanes; privacy, warmth, keep families together; triage after decon.","D: Send people home to shower."],"correct":2,"explanation":"Disrobing is decon step one. Visible liquid + symptoms → wet decon. Good crowd management (modesty, warmth, families) keeps people from self-evacuating contaminated.","clinicalPearl":"If decon feels humiliating or freezing, people will skip it — design for dignity."}]},"c10":{"chapter":"c10","cases":[{"id":"c10_s01","title":"Morning Rush, Line 3","presentation":"A commuter train car fills with a faint vapor. On the platform: a woman with pinpoint pupils and runny nose only; a man drooling, wheezing, vomiting; and a teen seizing and cyanotic. All have been disrobed and decontaminated.","vitals":{"woman":"miosis + rhinorrhea","man":"secretions, wheeze, vomiting","teen":"seizing, apneic"},"question":"Best antidote plan?","options":["A: Atropine only for the teen.","B: 1 kit for each.","C: 3 kits for everyone.","D: Woman: observe (± 1 kit if symptoms progress); man: 1 kit, repeat atropine to dry secretions; teen: 3 kits + benzodiazepine + ventilation."],"correct":3,"explanation":"Dose by severity. Vapor-only mild miosis/rhinorrhea may need no injector; moderate → 1 kit; severe → 3 kits + benzo and airway support. Titrate repeat atropine to secretions.","clinicalPearl":"Mild 1, Severe 3 + Benzo."},{"id":"c10_s02","title":"Pulled From the Apartment","presentation":"Firefighters carry a 40-year-old man out of a smoky apartment fire (burning furniture/foam). He is unresponsive, BP 78/40, RR 6, SpO2 98% on the monitor.","vitals":{"BP":"78/40","RR":"6","SpO2":"98% (?)"},"question":"What's going on and what do you give?","options":["A: Anaphylaxis — epinephrine.","B: Opioid overdose — naloxone.","C: Nerve agent — atropine.","D: Combined CO and cyanide toxicity — 100% O2/ventilation and hydroxocobalamin 5 g IV."],"correct":3,"explanation":"Pulse oximetry can be falsely reassuring with CO. Shock and coma in a smoke victim = cyanide until proven otherwise. Hydroxocobalamin doesn't cause methemoglobinemia — safe with CO.","clinicalPearl":"Smoke + shock = think cyanide."},{"id":"c10_s03","title":"The Hay Smell","presentation":"After a chemical plant leak, 12 workers mildly cough and say they smelled 'freshly mown hay'. All have normal vitals and want to go home.","vitals":{"exposed":"12","vitals":"normal","odor":"hay"},"question":"Disposition?","options":["A: Treat as phosgene exposure: rest, O2 as needed, transport/observe ~24 h for delayed pulmonary edema.","B: Release with advice.","C: Atropine for all.","D: Hydroxocobalamin for all."],"correct":0,"explanation":"Phosgene's latent period fools everyone. Exertion accelerates the pulmonary edema — they should not walk out, drive home, or exercise.","clinicalPearl":"Hay smell today = wet lungs tonight."}]},"c11":{"chapter":"c11","cases":[{"id":"c11_s01","title":"The Bus Stop Blast","presentation":"A small explosion at a bus stop. A police officer's radiation pager is alarming. 7 casualties: one with a partial leg amputation and arterial bleeding, others with fragment wounds.","vitals":{"casualties":"7","radiation":"detector alarming","worst":"arterial bleed"},"question":"Best approach?","options":["A: Standard PPE; tourniquet and triage now; remove patients' clothing; limit time near the seat of the blast; notify hospitals of contamination; decon as part of care.","B: Withdraw everyone until radiation is mapped.","C: Give KI to all.","D: Wait for Level A suits."],"correct":0,"explanation":"RDDs injure mainly by blast. Radiation risk to patients and responders is usually low; treat life threats immediately, minimize time near the source, and decon by disrobing.","clinicalPearl":"Dirty bomb = bomb first, dirt second."},{"id":"c11_s02","title":"Fever and Pustules","presentation":"A 30-year-old with 3 days of high fever and back pain now has firm pustules on the face, forearms, palms, and soles — all at the same stage.","vitals":{"temp":"39.8 °C","rash":"synchronous, centrifugal"},"question":"Your actions?","options":["A: Transport by bus with others.","B: Ignore the rash — treat the fever.","C: Standard precautions — it's chickenpox.","D: Treat as possible smallpox: mask the patient, N95/PAPR + gown + gloves + eye protection, limit crew, notify medical control/public health, decon the vehicle."],"correct":3,"explanation":"Synchronous centrifugal pustules including palms/soles = smallpox pattern. A single case is a public-health emergency.","clinicalPearl":"Same-stage pustules on palms and soles → think smallpox."},{"id":"c11_s03","title":"Seven Burned Hands","presentation":"Over a week, a clinic sees seven scrap-metal workers with painful red skin lesions on their hands and nausea. No chemical history.","vitals":{"cluster":"7 workers","lesions":"hands","symptoms":"nausea, fatigue"},"question":"Most likely explanation?","options":["A: Smallpox","B: Mustard exposure","C: A lost radioactive source causing local radiation injury/ARS (exposure)","D: Contact dermatitis"],"correct":2,"explanation":"Clusters of unexplained 'burns' + GI symptoms in people handling scrap suggest an orphan radioactive source (e.g., a medical teletherapy head). These patients are exposed, not necessarily contaminated.","clinicalPearl":"Unexplained burns in a cluster = think radiation."}]},"c12":{"chapter":"c12","cases":[{"id":"c12_s01","title":"Mall Shooting — Minute 12","presentation":"Police report the shooter is pinned down in the east wing. The food court (west) has been cleared but not secured. 15 casualties are there. You are assigned to a Rescue Task Force with 4 officers.","vitals":{"threat":"contained east","food court":"cleared, not secure","casualties":"~15"},"question":"Your RTF priorities?","options":["A: Search for the shooter.","B: Wait in the cold zone until the building is fully secure.","C: Intubate the first unresponsive patient.","D: Enter the food court with escort: rapid hemorrhage control (TQs, packing), airway positioning, chest seals; move casualties to the CCP; minimal time on each."],"correct":3,"explanation":"RTF's job is warm-zone TECC and rapid extraction. Prolonged procedures expose the team; police manage the threat.","clinicalPearl":"Stop the bleeding, get them out, keep moving."},{"id":"c12_s02","title":"The Train Carriage","presentation":"An explosive device detonates inside a crowded rail carriage. A 30-year-old is walking, deafened, mildly short of breath, with a ruptured right eardrum. SpO2 94%.","vitals":{"setting":"enclosed","SpO2":"94%","TM":"ruptured"},"question":"Best management?","options":["A: Needle decompression for all blast victims.","B: Tag green and release.","C: Treat as at risk for blast lung: re-triage, O2, monitor SpO2/work of breathing, transport for observation — communicate in writing.","D: Large-volume IV fluids."],"correct":2,"explanation":"Enclosed-space blast + TM rupture + mild hypoxia = high risk of evolving blast lung. Keep him under observation; he may deteriorate hours later.","clinicalPearl":"Enclosed blast, walking patient — still watch the lungs."},{"id":"c12_s03","title":"Second Device","presentation":"Twenty minutes after a car bomb, EMS and fire have clustered at a single CCP in a plaza next to a parked van with blacked-out windows.","vitals":{"time":"20 min","CCP":"plaza next to van"},"question":"What should command do?","options":["A: Relocate the CCP and staging away and out of line of sight; request police clearance of the van and the new site; disperse vehicles.","B: Search the van yourself.","C: Nothing — keep treating.","D: Move all patients into the van for shelter."],"correct":0,"explanation":"Secondary devices are designed to kill responders at predictable gathering points. Relocate, disperse, and get bomb-squad clearance.","clinicalPearl":"The second bomb is for you."}]},"c13":{"chapter":"c13","cases":[{"id":"c13_s01","title":"Under the Slab","presentation":"Earthquake. USAR has reached a 35-year-old man pinned at both thighs under a slab for ~6 hours. He's talking, HR 110, BP 110/70. They're ready to lift in 10 minutes.","vitals":{"entrapment":"~6 h","HR":"110","BP":"110/70"},"question":"Best plan?","options":["A: LR bolus after release only.","B: Lift now, then start fluids.","C: IV/IO access, NS 1–1.5 L/h before release, cardiac monitor, have calcium/bicarbonate/albuterol ready; coordinate the lift with USAR; watch for arrhythmia at release.","D: Leave him until the hospital is ready."],"correct":2,"explanation":"Prolonged compression of large muscle mass = crush syndrome risk. Pre-release saline and hyperkalemia readiness prevent the 'smiling death'.","clinicalPearl":"Fluids before freedom."},{"id":"c13_s02","title":"Gate 4","presentation":"At a concert, the crowd surges at a narrow exit. Security radios that people are 'stuck standing'. You see faces deeply purple above the barrier.","vitals":{"density":"packed, no movement","victims":"cyanotic, plethoric"},"question":"First priorities?","options":["A: Wait until the crowd disperses.","B: Get event control to stop inflow and open alternate exits, relieve pressure from the edges/barriers, extract victims, open airways and ventilate, then triage.","C: Announce over the PA for everyone to stay still and wait.","D: Push into the center of the crowd to reach victims."],"correct":1,"explanation":"Crowd crush is a pressure problem. Stop inflow, open egress, decompress from the edges, and ventilate the asphyxiated.","clinicalPearl":"Fix the pressure, then fix the patients."},{"id":"c13_s03","title":"The Silent Ventilator","presentation":"Day 2 of a regional blackout during a heat wave. Calls are rising: a home-ventilator patient whose battery is at 10%, an elderly couple in a hot flat, and a dialysis patient whose center is closed.","vitals":{"power":"out 36 h","temperature":"38 °C"},"question":"Key lesson?","options":["A: Disasters create medical emergencies through infrastructure loss — prioritize technology-dependent and heat-vulnerable patients, coordinate shelters with power and dialysis diversion.","B: These are routine calls.","C: Tell them to wait for power.","D: Only transport the ventilator patient."],"correct":0,"explanation":"Compound incidents turn chronic conditions into emergencies. Registries, early outreach, and power-equipped shelters save lives.","clinicalPearl":"No power = new patients."}]},"c14":{"chapter":"c14","cases":[{"id":"c14_s01","title":"The Missing Three","presentation":"End of a 38-patient bus crash. Tags issued: 38. Transport log: 33 transported. Released on scene: 1. Dead: 1. Hospitals report receiving 31.","vitals":{"tags":"38","logged out":"33 + 1 released + 1 dead","hospitals":"31"},"question":"What now?","options":["A: Do not terminate: 3 tagged patients unaccounted on scene and 2 transported patients not found at hospitals — re-sweep the scene, check the transport log against hospitals, search for self-evacuees.","B: Ask the media.","C: Close the incident — close enough.","D: Assume they went home."],"correct":0,"explanation":"38 − (33 + 1 + 1) = 3 missing on scene, and 33 − 31 = 2 missing in the hospital system. Reconciliation finds them.","clinicalPearl":"Math is a patient-safety tool."},{"id":"c14_s02","title":"After the Night","presentation":"Two days after a nightclub fire with multiple deaths, your manager proposes a mandatory 3-hour session where every crew member must describe their worst moments in detail.","vitals":{"crews":"14","deaths":"multiple"},"question":"Best recommendation?","options":["A: Replace it with Psychological First Aid, voluntary peer support, practical help, and follow-up checks; refer anyone with persistent or severe symptoms.","B: Support it — talking always helps.","C: Give everyone a week off and no contact.","D: Do nothing."],"correct":0,"explanation":"Mandatory single-session debriefing is not recommended. PFA principles and voluntary, ongoing support are evidence-informed.","clinicalPearl":"Offer support; don't force reliving."}]}},"algorithms":{"c01":{"chapter":"c01","algorithms":[{"id":"c01_alg01","title":"60-Second Incident Classification","description":"Run this in your head while you're still in the cab.","steps":["Count & severity: do casualties exceed what is immediately available? → If yes, DECLARE MCI.","Open or closed? Are victims finite/known, or still appearing/unknown?","Simple or compound? Are roads, hospitals, comms, utilities intact?","Hazard type: natural vs human-made; CBRNE? structural? violence/secondary device?","Predict the injury pattern from the disaster type (crush, burns, drowning, blast, asphyxia).","Translate into resource requests in your METHANE report (Chapter 2)."]}]},"c02":{"chapter":"c02","algorithms":[{"id":"c02_alg01","title":"METHANE Radio Template","description":"Read it straight off the card. Target: under 60 seconds.","steps":["'[Dispatch], this is [unit], establishing [Name] Command.'","M — 'MAJOR INCIDENT DECLARED' (or 'major incident standby').","E — Exact location: address/grid, side of building, landmarks.","T — Type: what happened (RTC, explosion, collapse, chemical, shooting).","H — Hazards: present and potential (fire, fuel, gas, chemicals, structure, violence, traffic, weather).","A — Access/egress: best route in, routes to avoid, staging/RV location.","N — Number: estimated total + red/yellow/green split + special groups (children, burns, contaminated).","E — Emergency services: who is on scene, what you request (ambulances, buses, HazMat, USAR, police, air).","Follow with CAN updates (Conditions, Actions, Needs) every 10–15 min or on major change."]},{"id":"c02_alg02","title":"First-Due Crew Actions","description":"Two-person crew, first unit at an MCI.","steps":["Approach with caution; stop short; position upwind/uphill/upstream and out of traffic.","Scan for hazards and CBRNE/hostile clues; if present — withdraw and report.","Crew 1: assume command, name the incident, declare MCI, send METHANE.","Crew 2: 360° recon + global sort (walkers to a collection point, wavers noted).","Request resources early and name the staging area.","As units arrive: assign Triage, Treatment, Transport, Staging; hand command up when a senior officer arrives (formal transfer)."]}]},"c03":{"chapter":"c03","algorithms":[{"id":"c03_alg01","title":"Transfer of Command","description":"Use every time command changes hands.","steps":["Incoming officer reports to the command post (face-to-face preferred).","Outgoing IC briefs: situation/size, hazards & safety, objectives & progress, resources assigned/requested, current org chart.","Incoming officer formally accepts command.","New IC announces the change on the radio to all units and dispatch.","Outgoing IC is reassigned (often to Medical Group or a unit leader role) — never just leaves."]},{"id":"c03_alg02","title":"Building the EMS Org Chart","description":"Grow only what you need.","steps":["First EMS unit: IC + global triage.","Add Triage Unit Leader when 2nd unit arrives.","Add Transport Unit Leader early — transport bottlenecks kill MCIs.","Add Treatment Unit Leader once a treatment area is needed.","Add Staging Area Manager once more than a few units are inbound.","When the IC is overloaded or other agencies have big roles: Medical Group Supervisor under Operations; consider Unified Command and Command Staff."]}]},"c04":{"chapter":"c04","algorithms":[{"id":"c04_alg01","title":"Triage Officer Action Card","description":"Put on the vest. Grab tags. Go.","steps":["Report to IC; get the area to triage and your team (pairs).","Global sort: 'If you can walk, go to [point]' → 'Wave if you need help'.","Systematic sweep (e.g., clockwise / row by row); START/JumpSTART or SALT per local protocol.","Seconds-long LSIs only: tourniquet/pressure, open airway/position, (child) breaths per protocol, auto-injector.","Tag every patient; mark searched areas.","Report counts by category to IC (red/yellow/green/black) and update as they change.","Direct litter teams: reds to treatment area first.","Re-triage; hand the dead to the morgue manager."]},{"id":"c04_alg02","title":"Transport Officer Action Card","description":"You move patients and paperwork, not stretchers.","steps":["Set up the ambulance loading zone (one-way flow, close to treatment area exit).","Get hospital capacity/capability through Med Comms or the hospital coordination center.","Request units from Staging as patients are ready.","Assign destination by category + hospital capability (trauma, burns, peds) — spread the load.","Load reds first; use buses (with medic) for greens; avoid 'one patient per ambulance' if yellows/greens can share.","Log: tag # · category · unit · destination · time.","Update IC with patients transported/remaining."]},{"id":"c04_alg03","title":"Treatment Officer Action Card","description":"Keep them alive and keep them moving.","steps":["Choose the treatment area: safe, upwind, near the loading zone, room to expand, one entrance/one exit.","Lay out red / yellow / green zones (tarps/flags) with a separate, out-of-view black area.","Assign Red, Yellow, Green treatment managers.","Secondary triage at the entrance; re-triage regularly.","Focused care: airway, O2, bleeding, splinting, warmth; minimal procedures that don't slow flow.","Prioritize patients for the Transport Officer; request supplies via Logistics."]}]},"c05":{"chapter":"c05","algorithms":[{"id":"c05_alg01","title":"Build the Scene Layout in 10 Minutes","description":"Do it on paper/whiteboard and on the radio.","steps":["Identify the hazard and wind; set hot/warm/cold boundaries and mark them (tape, cones, flags).","Fix the command post in the cold zone with a clear view.","Choose the treatment area: upwind, flat, lit, sheltered, expandable, near a road.","Define the loading zone at the treatment exit; set a one-way vehicle loop.","Set staging on the approach route, out of sight; announce it.","Set a supervised green collection point and a screened morgue area.","Pick a helicopter LZ away from treatment if air resources are coming.","Broadcast the layout to all units; re-evaluate when wind/threat changes."]}]},"c06":{"chapter":"c06","algorithms":[{"id":"c06_alg01","title":"START Adult Triage","description":"Target: ~30 seconds per patient.","steps":["Global: 'If you can walk, go to [green point].' → walkers = MINOR (green).","Non-walkers, one by one: Breathing? If NO → open/position airway.","Breathes after positioning → IMMEDIATE. Still apneic → DECEASED.","Breathing: RR > 30 → IMMEDIATE.","RR ≤ 30: check perfusion — radial pulse absent or CRT > 2 s → IMMEDIATE (control bleeding).","Perfusion OK: can follow simple commands? NO → IMMEDIATE. YES → DELAYED.","Tag, mark, move. Re-triage later."]},{"id":"c06_alg02","title":"JumpSTART Pediatric Triage","description":"For children ~1–8 years (or anyone who looks like a child).","steps":["Walking → MINOR (non-walkers by development: run the algorithm; well-appearing with no significant injury may be MINOR).","Not breathing → position airway → breathes → IMMEDIATE.","Still apneic → palpable peripheral pulse? NO → DECEASED.","Pulse present → 5 rescue breaths (~15 s) → breathes → IMMEDIATE; still apneic → DECEASED.","Breathing: RR < 15 or > 45 → IMMEDIATE.","RR 15–45: palpable peripheral pulse? NO → IMMEDIATE.","Pulse present: AVPU — U or inappropriate P → IMMEDIATE; A, V, or appropriate P → DELAYED."]}]},"c07":{"chapter":"c07","algorithms":[{"id":"c07_alg01","title":"SALT Mass Casualty Triage","description":"CDC-sponsored all-hazards standard (adults & children).","steps":["SORT: 'Walk to [area]' → assess last. 'Wave/move' → assess second. Still/obvious life threat → assess first.","ASSESS each casualty; perform LSIs (seconds): hemorrhage control, open airway (child: consider 2 rescue breaths), chest decompression, auto-injector.","Not breathing → DEAD.","Breathing → Obeys commands/purposeful movement? Peripheral pulse? Not in respiratory distress? Major hemorrhage controlled?","ALL YES → minor injuries only? → MINIMAL; otherwise → DELAYED.","ANY NO → likely to survive with current resources? → IMMEDIATE; otherwise → EXPECTANT (comfort care).","TREATMENT/TRANSPORT in priority order: Immediate → Delayed → Minimal (Expectant when resources allow).","Re-triage at every stage."]},{"id":"c07_alg02","title":"Re-Triage Loop","description":"Run it at every hand-off.","steps":["Primary triage at scene (START/SALT).","Secondary triage at treatment area entry (more detailed physiology, injury, age).","Re-check while waiting (assign a medic per area, every ~15 min or per protocol).","Pre-transport triage to set loading order and destination.","Hospital triage on arrival.","Any change: re-tag, note time, tell the Treatment and Transport Officers."]}]},"c08":{"chapter":"c08","algorithms":[{"id":"c08_alg01","title":"Treatment Area — MARCH Rapid Pass","description":"Per patient, then move to the next.","steps":["M — Massive hemorrhage: tourniquet, packing, pressure dressing (note TQ time).","A — Airway: position, suction, NPA/OPA; recovery position for unconscious breathing patients.","R — Respiration: seal open chest wounds; decompress tension pneumothorax per protocol; O2 to the hypoxic.","C — Circulation: bleeding control first; IV/IO and fluids only when indicated; permissive hypotension in penetrating trauma per protocol.","H — Hypothermia/Head: insulate from ground, cover; protect airway in head injury.","Re-triage and hand to Transport when ready."]},{"id":"c08_alg02","title":"Transport Officer — Loading Cycle","description":"Repeat until the scene is clear.","steps":["Ask Treatment: who is next (priority order)?","Ask Med Comms: who can take what (red/yellow/green capacity)?","Call the next unit from staging to the loading zone.","Assign patient(s) + destination; brief the crew in one line.","Log tag # · category · unit · destination · time.","Notify hospital via Med Comms; update IC counts."]}]},"c09":{"chapter":"c09","algorithms":[{"id":"c09_alg01","title":"HazMat Approach (EMS Awareness/Operations)","description":"Survive first, then help.","steps":["Recognize: clues, placards, Step 1-2-3.","Stop upwind, uphill, upstream; use binoculars.","Identify: placard class + UN number → ERG (yellow/blue → orange guide → green distances).","Isolate & deny entry; set hot/warm/cold zones.","Notify: METHANE + HazMat team + hospitals (contaminated patients may self-present).","Instruct exposed ambulatory people by PA: move upwind, remove outer clothing.","Receive patients in the cold zone after decon; treat per toxidrome (Chapter 10)."]},{"id":"c09_alg02","title":"Mass Decontamination","description":"High volume, fast, humane.","steps":["Disrobe (outer clothing at least) — bag, tag, keep valuables with the person.","Triage for decon priority: symptomatic, visible liquid, non-ambulatory first.","Dry decon (blot/wipe exposed skin) for most; wet decon for caustics, visible liquid, symptoms.","Wet decon: high-volume, low-pressure lukewarm water, ~30–60 s+ per person, head to toe; no scrubbing.","Non-ambulatory lane: decon teams roll/wash on backboards/litters.","Re-dress (gowns/blankets), keep warm, triage in the cold zone, document decon on the tag."]}]},"c10":{"chapter":"c10","algorithms":[{"id":"c10_alg01","title":"Nerve Agent Casualty","description":"Decon + Drugs + Airway.","steps":["PPE; remove from source; disrobe/decon (vapor: clothing removal; liquid: wet decon).","Assess severity: mild (miosis, rhinorrhea), moderate (secretions, wheeze, vomiting, fasciculations), severe (resp. distress, seizures, unconscious, apnea).","Mild: observe; 1 kit if symptoms progress. Moderate: 1 kit (atropine 2.1 mg + pralidoxime 600 mg IM).","Severe: 3 kits rapidly + benzodiazepine (midazolam 10 mg IM or diazepam 10 mg) for seizures.","Support ventilation; suction secretions (atropine first makes BVM ventilation possible).","Repeat atropine 2 mg every 5–10 min until secretions dry and breathing is easy.","Children: weight-based atropine/pediatric auto-injectors per protocol."]},{"id":"c10_alg02","title":"Cyanide (incl. Smoke Inhalation)","description":"Fast recognition, fast antidote.","steps":["Remove from source; decon if liquid exposure.","100% O2 / ventilate; treat seizures.","Suspect if: enclosed-space fire + AMS, hypotension, seizures, or arrest; sudden collapse near HCN source.","Hydroxocobalamin 5 g IV/IO over ~15 min (child 70 mg/kg); repeat once if needed.","Expect red skin/urine; SpO2 and some labs may read falsely.","Avoid nitrites if CO poisoning is possible."]}]},"c11":{"chapter":"c11","algorithms":[{"id":"c11_alg01","title":"Suspected Biological Event (EMS)","description":"Protect, contain, notify.","steps":["PPE by syndrome: respiratory + rash/bleeding → airborne + contact (N95/PAPR, gown, gloves, eye protection).","Source control: surgical mask on the patient.","Limit crew contact; avoid aerosol-generating procedures unless necessary.","Notify medical control and public health; pre-alert the hospital.","Document contacts (crew, bystanders) for prophylaxis/vaccination.","Decontaminate the ambulance per agent guidance; doff PPE with a spotter."]},{"id":"c11_alg02","title":"Radiological Incident (EMS)","description":"Trauma first, then radiation.","steps":["Approach upwind; use dosimeters; minimize time, maximize distance, use shielding.","Triage and treat life threats in standard PPE (gloves, gown, N95/mask, eye protection).","Remove patient clothing (bag/label); gently wash skin and wounds; cover wounds.","Note time of vomiting (dose estimate); avoid eating/drinking/smoking in the area.","Notify hospital: contaminated vs exposed; numbers.","Survey responders and equipment before leaving; follow turn-back values."]}]},"c12":{"chapter":"c12","algorithms":[{"id":"c12_alg01","title":"TECC by Phase","description":"Care matches the threat level.","steps":["DIRECT THREAT (hot): suppress threat / move to cover; direct self-aid; tourniquet 'high and tight' for life-threatening extremity bleeding; drag casualty to cover. No airway or spinal care.","INDIRECT THREAT (warm): M — reassess/convert TQs, pack junctional wounds, pressure dressings; A — recovery position, NPA, (surgical airway if trained); R — chest seal, needle decompression; C — IV/IO and TXA per protocol; H — hypothermia prevention, head injury care.","Move casualties to the CCP; triage there.","EVACUATION (cold): reassess everything, continue MARCH, add advanced care en route; document TQ times."]},{"id":"c12_alg02","title":"Blast Casualty Rapid Check","description":"Think in classes.","steps":["Scene: secondary device? structural collapse? fire/toxins? radiation detector alarm?","Primary: ears, breathing (blast lung), abdominal pain (bowel).","Secondary: fragment wounds — look everywhere, eyes too.","Tertiary: blunt trauma, amputations, crush.","Quaternary: burns, smoke/CO/cyanide, exacerbated illness.","Manage: hemorrhage first, O2, cautious fluids, careful ventilation, re-triage walking patients from enclosed blasts."]}]},"c13":{"chapter":"c13","algorithms":[{"id":"c13_alg01","title":"Crush Syndrome Field Protocol","description":"Prevent death at release.","steps":["Scene safety with USAR; do not enter unshored voids.","Establish IV/IO; normal saline ~1–1.5 L/h adult (pediatric weight-based) BEFORE release.","Cardiac monitor; check for peaked T waves/QRS widening.","Prepare calcium, sodium bicarbonate, nebulized albuterol per protocol.","If no access and release can't wait: consider proximal tourniquet before release per protocol.","Release; watch for arrhythmia/hypotension; treat hyperkalemia; continue fluids; transport to a center with dialysis capability."]},{"id":"c13_alg02","title":"Crowd Crush Response","description":"Pressure first, patients second.","steps":["Alert event control/security: stop inflow, open exits, stop the show/music if needed.","Approach from the edges; remove barriers if they trap people.","Extract victims; open airway, high-flow O2, ventilate apneic patients if resources allow.","Triage (START/SALT); treat traumatic asphyxia and fractures.","Re-triage; watch for delayed hypoxia; track patients for reunification."]}]},"c14":{"chapter":"c14","algorithms":[{"id":"c14_alg01","title":"Incident Close-Out","description":"Do it in this order.","steps":["Confirm no patients remain (re-sweep scene, check green area, search for self-evacuees).","Reconcile counts: tags = transport log = hospital arrivals + dead + released on scene.","Phased demobilization: rehab/medical check → decon → restock → return to service; log each release.","Terminate command and announce.","Hot wash before crews disperse.","Complete documentation (ePCRs, exposure logs).","AAR/Improvement Plan within weeks; update plans, train, and drill.","PFA and peer follow-up at ~1 day, 1 week, 1 month."]}]}},"tables":{"c01":{"chapter":"c01","tables":[{"id":"c01_t01","title":"Disaster Type → Injury Pattern → EMS Tactical Priority","headers":["Disaster","Dominant injuries/threats","EMS tactical priority"],"rows":[["Earthquake / structural collapse","Crush, crush syndrome, fractures, head injury","USAR coordination; pre-release fluids for crush; aftershock safety"],["Flood / tsunami","Drowning, hypothermia, debris trauma, electrocution","Don't enter moving water; swift-water teams; warm the patients"],["Tornado","Penetrating debris, blunt trauma, fractures","Search debris fields; tetanus/wound care; gas leaks/downed lines"],["Hurricane (and aftermath)","Trauma, drowning; later CO poisoning, chronic disease decompensation","Pre-storm evacuation of dependent patients; CO screening after"],["Heat wave","Heat stroke, dehydration, elderly/isolated deaths","Rapid cooling on scene; welfare checks"],["Wildfire","Burns, smoke inhalation, CO/cyanide","Evacuation corridors; airway burns; don't get trapped"],["Industrial / HazMat","Toxic exposure, burns, blast","Upwind/uphill; isolate; decon before treatment"],["Transportation (bus, rail, air)","Blunt multi-system trauma, entrapment, fire","Extrication; closed incident — account for the manifest"],["Explosion / terrorism","Blast lung, fragments, amputations, burns","Secondary device awareness; tourniquets; rapid evacuation"],["Crowd crush / mass gathering","Compressive asphyxia, trampling","Relieve compression; open airway; access/egress control"],["Pandemic / bioterror","Respiratory failure, sepsis, surge over weeks","PPE first; protect the workforce; altered standards of care"]]},{"id":"c01_t02","title":"Incident Classification Cheat Sheet","headers":["Axis","Option A","Option B"],"rows":[["Victim number","CLOSED — finite, known","OPEN — ongoing / unknown"],["Infrastructure","SIMPLE — intact","COMPOUND — damaged"],["System capacity","COMPENSATED — absorbable","UNCOMPENSATED — needs outside help (disaster)"]]}]},"c02":{"chapter":"c02","tables":[{"id":"c02_t01","title":"CSCATTT at a Glance","headers":["Letter","Priority","What it looks like on scene"],"rows":[["C","Command & control","Someone says 'I am command'; vests on; command post fixed"],["S","Safety","Self–Scene–Survivors; PPE; hazard zones marked"],["C","Communication","METHANE sent; named incident; plain language"],["A","Assessment","Recon, scale, hazards, resources needed"],["T","Triage","Global sort → primary triage → re-triage"],["T","Treatment","Lifesaving interventions; treatment area by priority"],["T","Transport","Right patient, right hospital, right time; tracking"]]},{"id":"c02_t02","title":"METHANE — Good vs Weak","headers":["Element","Weak","Strong"],"rows":[["M","'Looks bad'","'Major incident declared'"],["E","'On the highway'","'Hwy 9 northbound, km 42, past the Shell station'"],["T","'Accident'","'Bus vs truck rollover'"],["H","(omitted)","'Diesel spill, fire risk, traffic still moving southbound'"],["A","(omitted)","'Approach from north only; staging at the rest area, km 40'"],["N","'Lots of patients'","'Approx 30: 5 red, 9 yellow, 16 green, 2 children'"],["E","'Send help'","'2 ALS + police on scene; request 8 ambulances, 1 bus, fire rescue'"]]}]},"c03":{"chapter":"c03","tables":[{"id":"c03_t01","title":"ICS Levels & Titles","headers":["Organizational level","Title","EMS example"],"rows":[["Incident Command","Incident Commander","First-due EMS officer → later chief"],["Command Staff","Officer","Safety, PIO, Liaison"],["Section","Chief","Operations Section Chief"],["Branch","Director","Medical Branch Director"],["Division (geographic) / Group (functional)","Supervisor","Medical Group Supervisor"],["Unit","Leader","Triage / Treatment / Transport Unit Leader"],["Strike Team / Task Force","Leader","Ambulance Strike Team Leader (5 ambulances + leader)"],["Staging Area","Manager","Staging Area Manager"]]},{"id":"c03_t02","title":"General Staff — Who Does What","headers":["Section","Core job","MCI example"],"rows":[["Operations","Does the tactical work","Triage, treatment, transport, rescue"],["Planning","Situation & resource status, IAP, documentation","Patient-count tracking, next operational period"],["Logistics","Supplies, facilities, comms, food, responder medical","MCI trailer, O2 cylinders, generators, rehab"],["Finance/Admin","Costs, time records, claims, procurement","Mutual-aid reimbursement, injury claims"]]}]},"c04":{"chapter":"c04","tables":[{"id":"c04_t01","title":"MCI Officer Roles — One-Glance Card","headers":["Role","Mission","First actions","Never"],"rows":[["Incident Commander","Run the incident","Command post, METHANE, assign officers, request resources","Hands-on patient care"],["Triage Officer","Find & sort everyone","Global sort, tag, LSIs, count, re-triage","Stop to treat/transport"],["Treatment Officer","Keep patients alive","Zones, managers, secondary triage, prioritize","Let the area become a hospital"],["Transport Officer","Move & track patients","Loading zone, hospital capacity, assign, log","Let crews self-select hospitals"],["Staging Officer","Hold & release vehicles","Location, check-in, release on request","Let units self-dispatch"],["Safety Officer","Protect responders","Hazard scan, PPE, zones","Ignore an unsafe act"],["Med Comms Coordinator","Single voice to hospitals","Capacity, notifications","Let crews call independently"],["Morgue Manager","Manage the dead","Secure, out of view, liaise with police/ME","Move bodies unnecessarily"]]},{"id":"c04_t02","title":"Transport Log Template","headers":["Tag #","Category","Age/Sex","Unit","Destination","Time out"],"rows":[["A-00231","Red","~40 M","Medic 12","General (Trauma I)","14:22"],["A-00244","Yellow","~25 F","Medic 7","St. Mary's","14:26"],["A-00250 to 00262","Green ×12","mixed","Bus 3 + medic","West Hospital","14:31"]]}]},"c05":{"chapter":"c05","tables":[{"id":"c05_t01","title":"Zone Functions","headers":["Zone","Also called","What happens","Who enters"],"rows":[["Hot","Exclusion / direct threat","Hazard source, rescue, threat neutralization","Specialist teams in proper PPE; police"],["Warm","Contamination reduction / indirect threat","Decon, CCP, rapid LSIs (TECC)","Decon teams; Rescue Task Forces with escort"],["Cold","Support","Command, treatment, transport, staging, rehab, morgue, media","All responders"]]},{"id":"c05_t02","title":"Bomb Threat Stand-Off (Approximate, DHS/NCTC)","headers":["Threat","Mandatory evacuation","Preferred outdoor evacuation"],"rows":[["Pipe bomb","≈70 ft (21 m)","≈1,200 ft (366 m)"],["Suicide vest","≈110 ft (34 m)","≈1,700 ft (518 m)"],["Briefcase / suitcase","≈150 ft (46 m)","≈1,850 ft (564 m)"],["Car","≈320 ft (98 m)","≈1,500 ft (457 m)"],["Semi-trailer","≈1,570 ft (479 m)","≈9,300 ft (2,835 m)"]]},{"id":"c05_t03","title":"Facility Placement Checklist","headers":["Facility","Zone","Key rule"],"rows":[["Command post","Cold","Visible, fixed, view of the scene"],["Casualty collection point","Warm (hostile/CBRNE) or edge of cold","Gather → rapid triage → move on"],["Treatment area","Cold","Upwind, expandable, next to loading zone"],["Loading zone","Cold","At treatment exit, one-way loop"],["Staging","Cold (remote)","Out of sight, on the approach, check-in"],["Green collection point","Cold","Supervised, sheltered"],["Morgue","Cold","Secure, screened from view"],["Helicopter LZ","Cold","Away from treatment; clear of wires/debris"]]}]},"c06":{"chapter":"c06","tables":[{"id":"c06_t01","title":"START vs JumpSTART","headers":["Step","START (adult)","JumpSTART (child)"],"rows":[["Walking","MINOR","MINOR"],["Apneic after positioning","DECEASED","Pulse? None → DECEASED; pulse → 5 breaths"],["After rescue breaths","N/A","Breathes → IMMEDIATE; apneic → DECEASED"],["Respiratory rate red flag","> 30","< 15 or > 45"],["Perfusion red flag","No radial pulse or CRT > 2 s","No palpable peripheral pulse"],["Mental status red flag","Can't follow simple commands","U, or P with inappropriate response"],["Otherwise","DELAYED","DELAYED"]]},{"id":"c06_t02","title":"Triage Categories & Colors (START family)","headers":["Color","Category","Priority","Typical examples"],"rows":[["Red","Immediate","1st","Airway compromise, shock, altered mental status, RR > 30"],["Yellow","Delayed","2nd","Stable fractures, burns without airway issues, stable abdominal injury"],["Green","Minor","3rd","Walking wounded: abrasions, sprains, small lacerations"],["Black","Deceased","—","Apneic after airway positioning (child: after pulse check/5 breaths)"]]}]},"c07":{"chapter":"c07","tables":[{"id":"c07_t01","title":"Triage Systems Compared","headers":["Feature","START / JumpSTART","SALT","Triage Sieve (UK)"],"rows":[["Origin","US (1983 / Romig peds)","CDC-sponsored national guideline","UK major-incident doctrine"],["Global sort","Walkers only","Walk / Wave / Still","Walkers"],["LSIs built in","Airway + bleeding","Bleeding, airway ± 2 breaths, decompression, auto-injector","Catastrophic hemorrhage, airway"],["Pediatrics","Separate (JumpSTART)","Same algorithm (+2 breaths)","Paediatric tape/adjusted values"],["Expectant","No","Yes (gray)","Optional (expectant category in mass events)"],["Categories","Green / Yellow / Red / Black","Minimal / Delayed / Immediate / Expectant / Dead","P3 / P2 / P1 / Dead"]]},{"id":"c07_t02","title":"Under- vs Over-Triage","headers":["Error","Definition","Consequence","Fix"],"rows":[["Under-triage","Critical patient tagged too low","Preventable death/disability","Re-triage greens/yellows; clear criteria"],["Over-triage","Non-critical patient tagged too high","Red area & transport flooded; ↑ critical mortality","Strict physiological criteria; re-triage down"]]}]},"c08":{"chapter":"c08","tables":[{"id":"c08_t01","title":"Destination Matching","headers":["Patient type","Preferred destination","Notes"],"rows":[["Red — torso/major trauma","Trauma center (spread across centers)","Surgeon availability matters most"],["Red — major burns","Burn center if reachable","Otherwise stabilize at nearest, transfer later"],["Red — child","Pediatric-capable center","If time cost acceptable; else nearest appropriate"],["Yellow","Hospitals with capacity, often further out","Protect trauma center for reds"],["Green","Bus/van to low-load hospital or clinic","Medic + radio aboard; not the closest hospital"],["Contaminated","Decon BEFORE transport","Notify receiving hospital"]]},{"id":"c08_t02","title":"Field Care: Do / Defer","headers":["Do now","Defer (unless it's quick & lifesaving)"],"rows":[["Tourniquets, packing, pressure dressings","Detailed secondary survey"],["Airway positioning, adjuncts","Routine full spinal packaging"],["Chest seal / decompression","Non-critical IV lines"],["Warmth and ground insulation","Splinting minor injuries (greens can self-splint)"],["Antidotes (chemical)","Prolonged procedures delaying loading"]]}]},"c09":{"chapter":"c09","tables":[{"id":"c09_t01","title":"PPE Levels A–D","headers":["Level","Respiratory","Skin","Typical use"],"rows":[["A","SCBA","Fully encapsulating, vapor-tight","Unknown/high vapor hazard entry (HazMat team)"],["B","SCBA","Splash-protective, non-encapsulating","Highest respiratory need, lower skin threat"],["C","APR / PAPR","Splash-protective","Known agent & concentration, O2 adequate; decon teams, hospital decon"],["D","None","Work uniform","No contamination present"]]},{"id":"c09_t02","title":"DOT Hazard Classes","headers":["Class","Hazard","Example"],"rows":[["1","Explosives","Fireworks, blasting agents"],["2","Gases","Propane, chlorine, ammonia"],["3","Flammable liquids","Gasoline, ethanol"],["4","Flammable solids","Magnesium, matches"],["5","Oxidizers / organic peroxides","Ammonium nitrate, hydrogen peroxide"],["6","Toxic / infectious","Pesticides, medical waste"],["7","Radioactive","Medical isotopes, industrial sources"],["8","Corrosives","Sulfuric acid, sodium hydroxide"],["9","Miscellaneous","Lithium batteries, dry ice"]]},{"id":"c09_t03","title":"NFPA 704 Quick Read","headers":["Quadrant","Meaning","4 means…"],"rows":[["Blue (left)","Health","Can be lethal with brief exposure"],["Red (top)","Flammability","Extremely flammable / vaporizes readily"],["Yellow (right)","Instability / reactivity","May detonate at normal conditions"],["White (bottom)","Special hazards","W̶ = water-reactive, OX = oxidizer, SA = simple asphyxiant"]]}]},"c10":{"chapter":"c10","tables":[{"id":"c10_t01","title":"Chemical Toxidrome Cheat Sheet","headers":["Agent class","Examples","Onset","Key signs","Field treatment"],"rows":[["Nerve","Sarin, soman, VX, organophosphates","Vapor: sec–min; liquid: up to 18 h","Miosis, secretions, bronchospasm, fasciculations, seizures","Decon, atropine + pralidoxime, benzo"],["Cyanide (blood)","HCN, cyanogen chloride, smoke","Seconds–minutes","Sudden collapse, seizures, apnea, shock","O2, hydroxocobalamin"],["Choking (pulmonary)","Chlorine, ammonia, phosgene","Chlorine immediate; phosgene 2–24 h","Cough, stridor, wheeze; delayed pulmonary edema","Remove, O2, rest, bronchodilators, observe"],["Vesicant (blister)","Sulfur mustard, lewisite","Mustard 2–24 h; lewisite immediate","Erythema, blisters, eye injury, airway injury","Immediate decon; BAL for lewisite"],["Riot control","CS, CN, OC","Immediate","Tearing, burning, cough","Fresh air, eye irrigation; self-limited"],["Incapacitating opioid","Carfentanil aerosol","Minutes","Miosis, coma, apnea, DRY","Ventilate, naloxone"]]},{"id":"c10_t02","title":"Nerve Agent Kit Dosing by Severity","headers":["Severity","Signs","Kits (atropine 2.1 mg + 2-PAM 600 mg)","Add"],"rows":[["Mild (vapor)","Miosis, rhinorrhea only","0 — observe (1 if progressing)","—"],["Moderate","Secretions, wheeze, vomiting, fasciculations","1","Repeat atropine to dry secretions"],["Severe","Resp. distress, seizures, unconscious, apnea","3 rapidly","Benzodiazepine + ventilation"]]}]},"c11":{"chapter":"c11","tables":[{"id":"c11_t01","title":"Category A Agents — Transmission & PPE","headers":["Agent","Key presentation","Person-to-person?","EMS precautions"],"rows":[["Anthrax (inhalational)","Flu-like → shock, widened mediastinum","No","Standard"],["Botulism","Descending flaccid paralysis, alert, afebrile","No","Standard; prepare to ventilate"],["Plague (pneumonic)","Fulminant pneumonia, hemoptysis","Yes — droplet","Droplet (mask patient; N95 commonly used)"],["Smallpox","Fever → synchronous centrifugal pustules","Yes — airborne/contact","Airborne + contact + eye"],["Tularemia","Pneumonia, ulceroglandular lesions","No","Standard"],["Viral hemorrhagic fever","Fever, bleeding, shock","Yes — body fluids","Full contact/droplet PPE, trained doffing"]]},{"id":"c11_t02","title":"Radiological/Nuclear Devices","headers":["Device","What it is","Main injuries","Key action"],"rows":[["RDD (dirty bomb)","Explosive + radioactive material","Blast trauma; low radiation doses","Treat trauma first; disrobe/decon"],["RED (exposure device)","Hidden source","Local burns, ARS; no contamination","Find cluster; isolate source"],["IND / nuclear detonation","Nuclear yield","Blast, burns, radiation, fallout","Get inside, stay inside, stay tuned"]]},{"id":"c11_t03","title":"Time to Vomiting → Approximate Dose (ARS)","headers":["Vomiting onset","Approximate dose","Implication"],"rows":[["< 10 min","Very high (> ~8 Gy)","Likely lethal; comfort care in mass events"],["< 1 h","High (≈ 4–8 Gy)","Severe ARS — priority for hospital care"],["1–2 h","Moderate (≈ 2–4 Gy)","Hospital care likely needed"],["> 2–4 h / none","Low (< ~2 Gy)","Likely survivable; outpatient follow-up"]]}]},"c12":{"chapter":"c12","tables":[{"id":"c12_t01","title":"Blast Injury Classification","headers":["Class","Mechanism","Typical injuries"],"rows":[["Primary","Overpressure wave","TM rupture, blast lung, bowel perforation, eye globe rupture"],["Secondary","Fragments/debris","Penetrating wounds, eye injuries"],["Tertiary","Body displacement / collapse","Blunt trauma, amputations, crush, fractures"],["Quaternary","Other explosion effects","Burns, inhalation (CO, cyanide), asthma/COPD/angina"],["Quinary","Additives","Hyperinflammatory state; bacteria/chemicals/radiation"]]},{"id":"c12_t02","title":"TECC Phases vs ICS Zones","headers":["TECC phase","Zone","What you do","What you don't"],"rows":[["Direct threat","Hot","Cover, self-aid, tourniquet","Airway, C-spine, IVs"],["Indirect threat","Warm","MARCH, CCP, prepare to move","Prolonged procedures"],["Evacuation","Cold","Reassess, advanced care en route","Delay transport"]]}]},"c13":{"chapter":"c13","tables":[{"id":"c13_t01","title":"Special MCI Quick Tactics","headers":["Incident","Hazard to you","Medical focus","Key action"],"rows":[["Structural collapse","Secondary collapse, dust","Crush, fractures, dust inhalation","USAR coordination; fluids before release"],["Crowd crush","Being swept in","Compressive asphyxia","Stop inflow, open exits, ventilate"],["Bus/coach crash","Traffic, fuel","Blunt multi-system trauma","Manifest; extrication"],["Rail crash","Electrical power, hazmat cargo","Blunt trauma, entrapment","Isolate power first"],["Aircraft crash","Fuel fire, composites","Burns, blunt trauma","Upwind approach; respiratory PPE"],["Flood","Moving water, electrocution","Drowning, hypothermia","Swift-water teams only"],["Heat wave","Your own heat illness","Heat stroke","Cool first, transport second"],["Winter storm/outage","Roads, CO","Hypothermia, CO, tech-dependent pts","CO screening, shelters with power"]]},{"id":"c13_t02","title":"Vulnerable Populations Checklist","headers":["Group","Risk","MCI action"],"rows":[["Children","Hypoxia, hypothermia, separation","JumpSTART; keep with caregivers; unaccompanied-minor protocol"],["Elderly","Atypical signs, falls, heat","Lower threshold to re-triage; medication lists"],["Technology-dependent","Power/supply loss","Early evacuation, battery/O2 resupply, dialysis plans"],["Disabilities","Mobility, communication","Evacuation aids; keep service animals and devices"],["Pregnancy","Aortocaval compression; fetal hypoxia","Left lateral tilt; maternal oxygenation"]]}]},"c14":{"chapter":"c14","tables":[{"id":"c14_t01","title":"Stress Reactions: Normal vs Refer","headers":["Usually normal (days–weeks)","Refer / act"],"rows":[["Trouble sleeping, vivid dreams","Symptoms > ~1 month or worsening"],["Irritability, sadness, numbness","Unable to work or function at home"],["Replaying images of the event","Increasing alcohol/drug use"],["Wanting to talk — or not","Any thoughts of self-harm (act today)"]]},{"id":"c14_t02","title":"Hot Wash vs AAR","headers":["","Hot wash","After-Action Review/Report"],"rows":[["When","Immediately (minutes–hours)","Days–weeks later"],["Format","Informal, verbal, short","Structured, written, with Improvement Plan"],["Who","Everyone on scene","Leads from all agencies + planners"],["Output","Immediate safety fixes, quick lessons","Sustain/improve actions with owners & deadlines"]]}]}},"drills":{"c01":{"chapter":"c01","drills":[{"title":"Disaster → What Will Hurt People?","icon":"🌪️","targetSeconds":10,"description":"Match each disaster to the injury pattern you should expect on arrival. Fast pattern recognition = right resource request.","items":[{"id":"c01_dr01_01","prompt":"Magnitude 7.1 earthquake, apartment blocks down.","options":["Crush injuries & entrapment","Drowning","Heat stroke","Compressive asphyxia"],"answer":0,"why":"Collapsed structures → entrapment, crush, and crush syndrome after release."},{"id":"c01_dr01_02","prompt":"Flash flood sweeps through a campground.","options":["Blast lung","Drowning, hypothermia & debris trauma","Cyanide toxicity","Penetrating fragments"],"answer":1,"why":"Floods drown, chill, and batter with debris. Never self-deploy into moving water."},{"id":"c01_dr01_03","prompt":"EF-4 tornado through a mobile-home park.","options":["Penetrating debris & blunt trauma","Radiation burns","Pulmonary edema from phosgene","Crowd crush"],"answer":0,"why":"Wind-borne debris impales and batters; also check for gas leaks and downed power lines."},{"id":"c01_dr01_04","prompt":"Packed stadium exit gate jammed during a stampede.","options":["Drowning","Burns","Compressive (traumatic) asphyxia","Crush syndrome from 6-h entrapment"],"answer":2,"why":"People die standing up — chest compression prevents breathing."},{"id":"c01_dr01_05","prompt":"Day 4 after a hurricane; family indoors with a generator.","options":["Carbon monoxide poisoning","Hypothermia","Blast injury","Anaphylaxis"],"answer":0,"why":"Generators indoors or near windows are a predictable post-storm killer."},{"id":"c01_dr01_06","prompt":"Week-long heat wave; elderly living alone.","options":["Heat stroke & dehydration","Frostbite","Crush injury","Smoke inhalation"],"answer":0,"why":"Elderly, isolated, and on diuretics/psych meds are highest risk — cool aggressively."},{"id":"c01_dr01_07","prompt":"Chlorine tanker ruptures near a school.","options":["Toxic inhalation (airway/lung irritation)","Crush injury","Drowning","Heat stroke"],"answer":0,"why":"Chemical release = respiratory toxicity. Approach upwind/uphill; decon before treatment."},{"id":"c01_dr01_08","prompt":"Train derailment, two cars on their sides.","options":["Blunt multi-system trauma & entrapment","Radiation sickness","Compressive asphyxia only","Pandemic respiratory illness"],"answer":0,"why":"High-energy blunt trauma with extrication needs. Get the passenger manifest — it's closed."},{"id":"c01_dr01_09","prompt":"Wildfire overruns a hillside neighborhood.","options":["Burns & smoke inhalation (CO/cyanide)","Drowning","Crush syndrome","Blast lung"],"answer":0,"why":"Thermal burns, airway burns, and smoke toxins. Protect your evacuation route."},{"id":"c01_dr01_10","prompt":"Novel respiratory virus overwhelming ICUs.","options":["Biological disaster — slow surge over weeks","Closed incident","Simple, compensated event","Blast injury pattern"],"answer":0,"why":"Biological disasters are 'slow MCIs': staff protection, PPE, and crisis standards of care matter most."}],"id":"c01_dr01"}]},"c02":{"chapter":"c02","drills":[{"title":"METHANE Radio Drill","icon":"📻","targetSeconds":12,"description":"You're on the radio. Pick the line that correctly belongs in each METHANE slot. Speed matters — dispatch is waiting.","items":[{"id":"c02_dr01_01","prompt":"Which line belongs in 'M'?","options":["Major incident declared.","Multiple patients, will advise.","Medic 4 on scene.","Mild injuries mostly."],"answer":0,"why":"M = the declaration (or 'standby'). Say the words."},{"id":"c02_dr01_02","prompt":"Which line belongs in the FIRST 'E'?","options":["Request 6 ambulances.","Exit 14, northbound, under the rail bridge.","Evacuating now.","Engine 2 on scene."],"answer":1,"why":"First E = Exact location. The last E = Emergency services."},{"id":"c02_dr01_03","prompt":"Which line belongs in 'T'?","options":["Approx 20 casualties.","Coach overturned into ditch after striking a lorry.","Fuel leaking.","Access from the south."],"answer":1,"why":"T = Type of incident — what happened."},{"id":"c02_dr01_04","prompt":"Which line belongs in 'H'?","options":["Fuel leaking, live traffic in southbound lanes, powerlines down.","Stage at the truck stop.","Two engines on scene.","Hospital notified."],"answer":0,"why":"H = hazards present AND potential."},{"id":"c02_dr01_05","prompt":"Which line belongs in 'A'?","options":["All patients triaged.","Approach from the north only; RV point at the truck stop, junction 13.","Approx 30 casualties.","Ambulance 7 en route."],"answer":1,"why":"A = Access/egress + rendezvous/staging."},{"id":"c02_dr01_06","prompt":"Which line belongs in 'N'?","options":["Need more units.","Approx 30 casualties: 5 red, 10 yellow, 15 green, 3 are children.","Number of the incident is 4471.","No hazards."],"answer":1,"why":"N = number, severity, and type of casualties — estimates are fine."},{"id":"c02_dr01_07","prompt":"Which line belongs in the LAST 'E'?","options":["Exact address is 9 Main St.","On scene: 2 ALS, 1 engine, police. Request: 8 ambulances, 1 bus for greens, heavy rescue.","Estimated time 10 minutes.","Everyone is stable."],"answer":1,"why":"Last E = Emergency services present and required."},{"id":"c02_dr01_08","prompt":"A dispatcher asks 'Confirm, is this a major incident?' The incident clearly exceeds your resources. You say:","options":["'Standby, still assessing.'","'Affirmative — MAJOR INCIDENT DECLARED.'","'Possibly, send what you can.'","'Code 3, 10-50 major.'"],"answer":1,"why":"Unambiguous plain language. Hedging delays resources; codes confuse mutual aid."},{"id":"c02_dr01_09","prompt":"You don't yet know the exact casualty count. Best 'N' line?","options":["'Unknown, will count.'","'Approximately 40, majority walking, at least 6 appear critical.'","Skip N until later.","'Lots.'"],"answer":1,"why":"An estimate with a severity split moves resources now. Refine later."},{"id":"c02_dr01_10","prompt":"Which order is correct?","options":["M-E-T-H-A-N-E: Major, Exact location, Type, Hazards, Access, Number, Emergency services","M-E-T-H-A-N-E: Medical, Evacuation, Triage, Hospital, Ambulance, Number, Exit","M-E-T-H-A-N-E: Major, Emergency services, Type, Hospital, Access, Number, Exact location","M-E-T-H-A-N-E: Mechanism, Exposure, Time, Hazards, Age, Name, ETA"],"answer":0,"why":"Major – Exact location – Type – Hazards – Access – Number – Emergency services."}],"id":"c02_dr01"}]},"c03":{"chapter":"c03","drills":[{"title":"ICS Title Match","icon":"🪖","targetSeconds":8,"description":"Rapid-fire ICS terminology. Get the title and the box right — it's how strangers work together.","items":[{"id":"c03_dr01_01","prompt":"Head of the Operations Section is the…","options":["Operations Section Chief","Operations Director","Operations Supervisor","Operations Officer"],"answer":0,"why":"Sections are led by Chiefs."},{"id":"c03_dr01_02","prompt":"Head of the Medical Branch is the…","options":["Medical Branch Chief","Medical Branch Director","Medical Branch Leader","Medical Branch Officer"],"answer":1,"why":"Branches are led by Directors."},{"id":"c03_dr01_03","prompt":"Head of the Medical Group is the…","options":["Medical Group Leader","Medical Group Director","Medical Group Supervisor","Medical Group Manager"],"answer":2,"why":"Divisions and Groups are led by Supervisors."},{"id":"c03_dr01_04","prompt":"Head of the Triage Unit is the…","options":["Triage Unit Leader","Triage Unit Supervisor","Triage Unit Chief","Triage Officer (Command Staff)"],"answer":0,"why":"Units are led by Leaders (often called 'Triage Officer' informally)."},{"id":"c03_dr01_05","prompt":"The Public Information Officer belongs to…","options":["General Staff","Command Staff","Planning Section","Operations Section"],"answer":1,"why":"Command Staff = Safety, PIO, Liaison."},{"id":"c03_dr01_06","prompt":"Logistics is part of…","options":["Command Staff","General Staff","Medical Group","Staging"],"answer":1,"why":"General Staff = Operations, Planning, Logistics, Finance/Admin."},{"id":"c03_dr01_07","prompt":"'Division B' most likely refers to…","options":["A function","A geographic area","An agency","A shift"],"answer":1,"why":"Divisions are geographic; Groups are functional."},{"id":"c03_dr01_08","prompt":"Who coordinates with other agencies' representatives?","options":["Liaison Officer","PIO","Logistics Chief","Treatment Unit Leader"],"answer":0,"why":"Liaison Officer is the point of contact for assisting/cooperating agencies."},{"id":"c03_dr01_09","prompt":"Who runs the area where uncommitted ambulances wait?","options":["Transport Unit Leader","Staging Area Manager","Safety Officer","Treatment Unit Leader"],"answer":1,"why":"Staging Areas are run by Managers."},{"id":"c03_dr01_10","prompt":"A supervisor has 9 direct reports. ICS says…","options":["Fine in an emergency","Add a supervisory layer","Send 4 home","Report to two supervisors"],"answer":1,"why":"Span of control ~3–7 (5 optimal) — expand the organization."},{"id":"c03_dr01_11","prompt":"Who documents the situation and writes the IAP?","options":["Operations","Planning","Finance/Admin","Liaison"],"answer":1,"why":"Planning tracks situation/resources and produces the IAP."},{"id":"c03_dr01_12","prompt":"Who can halt an unsafe operation immediately?","options":["Any crew member","Safety Officer","PIO","Finance Chief"],"answer":1,"why":"Safety Officer has stop-work authority (everyone should still call out hazards)."}],"id":"c03_dr01"}]},"c04":{"chapter":"c04","drills":[{"title":"Whose Job Is It?","icon":"🦺","targetSeconds":8,"options":[{"key":"ic","label":"Incident Commander","color":"#f0f6fc"},{"key":"triage","label":"Triage Officer","color":"#c8102e"},{"key":"treat","label":"Treatment Officer","color":"#d29922"},{"key":"transport","label":"Transport Officer","color":"#2ea043"},{"key":"staging","label":"Staging Officer","color":"#1f6feb"},{"key":"safety","label":"Safety Officer","color":"#ff9f43"}],"description":"A task lands on the scene. Toss it to the right vest — fast. Wrong vest = lost minutes.","items":[{"id":"c04_dr01_01","prompt":"Sending the METHANE report and naming the incident.","answer":"ic","why":"Command owns the first report and naming the incident."},{"id":"c04_dr01_02","prompt":"Shouting 'If you can walk, come to the blue tent!'","answer":"triage","why":"Global sort is the triage officer's opening move."},{"id":"c04_dr01_03","prompt":"Choosing which hospital gets the next red patient.","answer":"transport","why":"Transport matches patients to hospital capability and capacity."},{"id":"c04_dr01_04","prompt":"Laying out red, yellow, and green tarps.","answer":"treat","why":"Treatment Officer sets up the treatment area."},{"id":"c04_dr01_05","prompt":"Making mutual-aid ambulances check in, keys left in the ignition.","answer":"staging","why":"Staging tracks and holds available vehicles."},{"id":"c04_dr01_06","prompt":"Stopping a crew from walking under a sagging roof.","answer":"safety","why":"Safety Officer can stop unsafe acts immediately."},{"id":"c04_dr01_07","prompt":"Applying a tourniquet in 10 seconds then moving on.","answer":"triage","why":"Seconds-long LSIs are allowed during triage."},{"id":"c04_dr01_08","prompt":"Writing 'A-00231 · Red · Medic 12 · General · 14:22'.","answer":"transport","why":"The transport log is the Transport Officer's record."},{"id":"c04_dr01_09","prompt":"Requesting 6 more ambulances and a bus from dispatch.","answer":"ic","why":"Resource requests flow through command."},{"id":"c04_dr01_10","prompt":"Secondary triage of patients arriving at the treatment area.","answer":"treat","why":"Treatment re-triages on entry to the treatment area."},{"id":"c04_dr01_11","prompt":"Telling the IC 'only 2 ambulances left available'.","answer":"staging","why":"Staging reports when available resources drop to the trigger level."},{"id":"c04_dr01_12","prompt":"Reporting '5 red, 9 yellow, 21 green, 2 black' to command.","answer":"triage","why":"Triage owns the casualty count by category."},{"id":"c04_dr01_13","prompt":"Coordinating with police and fire chiefs at one command post.","answer":"ic","why":"Unified command coordination is a command function."},{"id":"c04_dr01_14","prompt":"Calling the next ambulance up from staging to the loading zone.","answer":"transport","why":"Transport requests units from staging as patients are ready."},{"id":"c04_dr01_15","prompt":"Enforcing respiratory protection near a smoldering chemical drum.","answer":"safety","why":"PPE and hazard enforcement are safety functions."}],"id":"c04_dr01"}]},"c05":{"chapter":"c05","drills":[{"title":"Zone It!","icon":"🗺️","targetSeconds":6,"options":[{"key":"hot","label":"HOT zone","color":"#c8102e"},{"key":"warm","label":"WARM zone","color":"#d29922"},{"key":"cold","label":"COLD zone","color":"#2ea043"}],"description":"Drop each item into the right zone. Speed counts — the scene is building itself around you.","items":[{"id":"c05_dr01_01","prompt":"Incident command post","answer":"cold","why":"Command lives in the cold zone, visible and safe."},{"id":"c05_dr01_02","prompt":"Decontamination corridor","answer":"warm","why":"Decon = contamination reduction = warm zone."},{"id":"c05_dr01_03","prompt":"Leaking chlorine cylinder","answer":"hot","why":"The hazard source defines the hot zone."},{"id":"c05_dr01_04","prompt":"Red/yellow/green treatment area","answer":"cold","why":"Definitive field treatment happens in the cold zone."},{"id":"c05_dr01_05","prompt":"Casualty collection point during an active-shooter response","answer":"warm","why":"CCPs sit in the warm (indirect threat) zone, staffed by Rescue Task Forces with security."},{"id":"c05_dr01_06","prompt":"Ambulance staging area","answer":"cold","why":"Staging is cold, remote, and out of sight of the hazard."},{"id":"c05_dr01_07","prompt":"Direct-threat area where the shooter is still active","answer":"hot","why":"Direct threat = hot zone; law enforcement neutralizes the threat."},{"id":"c05_dr01_08","prompt":"Applying a tourniquet under police escort in a cleared hallway","answer":"warm","why":"Indirect-threat care (TECC) happens in the warm zone."},{"id":"c05_dr01_09","prompt":"Media briefing area","answer":"cold","why":"Media are kept in the cold zone, away from patients."},{"id":"c05_dr01_10","prompt":"Helicopter landing zone","answer":"cold","why":"LZ is cold and away from treatment because of rotor wash."},{"id":"c05_dr01_11","prompt":"Collapsed floor slabs with trapped victims and ongoing aftershocks","answer":"hot","why":"Unstable structure = hot zone; USAR teams only."},{"id":"c05_dr01_12","prompt":"Responder rehab station","answer":"cold","why":"Rehab supports responders in the cold zone."}],"id":"c05_dr01"}]},"c06":{"chapter":"c06","drills":[{"title":"60-Second Tagger: START & JumpSTART","icon":"🏷️","targetSeconds":30,"options":[{"key":"green","label":"MINOR (Green)","color":"#2ea043"},{"key":"yellow","label":"DELAYED (Yellow)","color":"#d29922"},{"key":"red","label":"IMMEDIATE (Red)","color":"#c8102e"},{"key":"black","label":"DECEASED (Black)","color":"#111111"}],"description":"Twenty-six patients. One tag each. Target ≤ 30 s per patient. Read the protocol line — adults get START, kids get JumpSTART.","items":[{"id":"c06_dr01_01","prompt":"Man walks to the green tarp holding a bloody forearm (oozing).","details":{"protocol":"START (adult)","walks":"Yes","resp":"—","perfusion":"—","mental":"—"},"answer":"green","why":"Ambulatory = MINOR. Re-triage later; have him hold pressure."},{"id":"c06_dr01_02","prompt":"Woman lying under a seat, not breathing. You tilt her head — she gasps and starts breathing.","details":{"protocol":"START (adult)","walks":"No","resp":"Apneic → breathes after positioning","perfusion":"—","mental":"—"},"answer":"red","why":"Breathing only after airway positioning = IMMEDIATE."},{"id":"c06_dr01_03","prompt":"Man face-down, not breathing. Airway repositioned — still no breathing.","details":{"protocol":"START (adult)","walks":"No","resp":"Apneic after positioning","perfusion":"—","mental":"—"},"answer":"black","why":"Adult apneic after positioning = DECEASED. No CPR in START."},{"id":"c06_dr01_04","prompt":"Teen-looking adult, pelvis pain, can't stand.","details":{"protocol":"START (adult)","walks":"No","resp":"36/min","perfusion":"Radial present","mental":"Follows commands"},"answer":"red","why":"RR > 30 = IMMEDIATE — stop at the first red criterion."},{"id":"c06_dr01_05","prompt":"Driver trapped, pale.","details":{"protocol":"START (adult)","walks":"No","resp":"22/min","perfusion":"Radial ABSENT","mental":"Follows commands"},"answer":"red","why":"No radial pulse = IMMEDIATE."},{"id":"c06_dr01_06","prompt":"Older woman, wrist and hip deformity.","details":{"protocol":"START (adult)","walks":"No","resp":"24/min","perfusion":"Radial present, CRT 4 s (warm day)","mental":"Follows commands"},"answer":"red","why":"CRT > 2 s = IMMEDIATE (perfusion)."},{"id":"c06_dr01_07","prompt":"Construction worker, open tib-fib fracture, screaming.","details":{"protocol":"START (adult)","walks":"No","resp":"26/min","perfusion":"Radial strong, CRT < 2 s","mental":"Follows commands"},"answer":"yellow","why":"Passes RPM = DELAYED. Loud ≠ red."},{"id":"c06_dr01_08","prompt":"Man with a head wound, eyes open, mumbling, can't squeeze your hand on request.","details":{"protocol":"START (adult)","walks":"No","resp":"18/min","perfusion":"Radial present","mental":"Does NOT follow commands"},"answer":"red","why":"Can't follow simple commands = IMMEDIATE."},{"id":"c06_dr01_09","prompt":"Woman with a femur deformity, calm.","details":{"protocol":"START (adult)","walks":"No","resp":"30/min","perfusion":"Radial present, CRT 1 s","mental":"Follows commands"},"answer":"yellow","why":"RR exactly 30 is NOT > 30 → DELAYED."},{"id":"c06_dr01_10","prompt":"Unconscious man, snoring respirations.","details":{"protocol":"START (adult)","walks":"No","resp":"10/min","perfusion":"Radial present","mental":"Unresponsive"},"answer":"red","why":"RR ≤ 30 and pulse OK, but can't follow commands = IMMEDIATE."},{"id":"c06_dr01_11","prompt":"Woman sitting, says her back hurts too much to walk.","details":{"protocol":"START (adult)","walks":"No","resp":"20/min","perfusion":"Radial present, CRT < 2 s","mental":"Follows commands"},"answer":"yellow","why":"Non-ambulatory with normal RPM = DELAYED."},{"id":"c06_dr01_12","prompt":"Man with burns to both arms, walking around asking for water.","details":{"protocol":"START (adult)","walks":"Yes","resp":"—","perfusion":"—","mental":"—"},"answer":"green","why":"Ambulatory = MINOR for now — burns patients need re-triage (airway, % TBSA)."},{"id":"c06_dr01_13","prompt":"Woman in the cold night air, fingers icy.","details":{"protocol":"START (adult)","walks":"No","resp":"24/min","perfusion":"Radial present (CRT unreadable in cold)","mental":"Follows commands"},"answer":"yellow","why":"Use radial pulse when CRT is unreliable. Radial present + RPM OK = DELAYED."},{"id":"c06_dr01_14","prompt":"Man with arterial spurting from the thigh — you place a tourniquet.","details":{"protocol":"START (adult)","walks":"No","resp":"28/min","perfusion":"Radial weak but present after TQ, CRT 3 s","mental":"Follows commands"},"answer":"red","why":"CRT > 2 s = IMMEDIATE. The tourniquet was the right seconds-long LSI."},{"id":"c06_dr01_15","prompt":"6-year-old walks to her mother at the green area.","details":{"protocol":"JumpSTART (child)","walks":"Yes","resp":"—","perfusion":"—","mental":"—"},"answer":"green","why":"Ambulatory child = MINOR. Re-triage later."},{"id":"c06_dr01_16","prompt":"4-year-old not breathing. Positioned — still apneic. Pulse present. You give 5 breaths — he starts breathing.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"Breathes after 5 rescue breaths","perfusion":"Pulse present","mental":"—"},"answer":"red","why":"Breathing after rescue breaths = IMMEDIATE."},{"id":"c06_dr01_17","prompt":"7-year-old not breathing after positioning. No palpable pulse.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"Apneic","perfusion":"No pulse","mental":"—"},"answer":"black","why":"Apneic + pulseless child = DECEASED (no rescue breaths)."},{"id":"c06_dr01_18","prompt":"3-year-old apneic after positioning, pulse present, still apneic after 5 rescue breaths.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"Apneic after 5 breaths","perfusion":"Pulse present","mental":"—"},"answer":"black","why":"Apnea persists after 5 breaths = DECEASED."},{"id":"c06_dr01_19","prompt":"5-year-old with chest bruising, grunting.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"52/min","perfusion":"Pulse present","mental":"Alert"},"answer":"red","why":"RR > 45 = IMMEDIATE."},{"id":"c06_dr01_20","prompt":"2-year-old, drowsy, slow breathing.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"12/min","perfusion":"Pulse present","mental":"Responds to voice"},"answer":"red","why":"RR < 15 = IMMEDIATE."},{"id":"c06_dr01_21","prompt":"6-year-old, deformed thigh, crying for mom.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"34/min","perfusion":"Peripheral pulse present","mental":"Alert"},"answer":"yellow","why":"RR 15–45, pulse present, Alert = DELAYED. (34 would be red in START — not in JumpSTART.)"},{"id":"c06_dr01_22","prompt":"4-year-old, pale, abdominal bruising.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"28/min","perfusion":"NO palpable peripheral pulse","mental":"Responds to voice"},"answer":"red","why":"No palpable peripheral pulse = IMMEDIATE."},{"id":"c06_dr01_23","prompt":"5-year-old with a scalp wound, eyes closed, pushes your hand away when pinched.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"24/min","perfusion":"Pulse present","mental":"P — localizes (appropriate)"},"answer":"yellow","why":"Appropriate P (localizes/withdraws) = DELAYED."},{"id":"c06_dr01_24","prompt":"3-year-old, extends arms rigidly when pinched.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"26/min","perfusion":"Pulse present","mental":"P — posturing (inappropriate)"},"answer":"red","why":"Inappropriate P (posturing) = IMMEDIATE."},{"id":"c06_dr01_25","prompt":"8-year-old, no response to voice or pain.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"20/min","perfusion":"Pulse present","mental":"U — unresponsive"},"answer":"red","why":"U on AVPU = IMMEDIATE."},{"id":"c06_dr01_26","prompt":"6-year-old not breathing; you position the airway and she starts breathing.","details":{"protocol":"JumpSTART (child)","walks":"No","resp":"Breathes after positioning","perfusion":"—","mental":"—"},"answer":"red","why":"Breathing after positioning = IMMEDIATE (same as START)."}],"id":"c06_dr01"}]},"c07":{"chapter":"c07","drills":[{"title":"SALT Tagger (with Expectant)","icon":"⚖️","targetSeconds":25,"options":[{"key":"green","label":"MINIMAL (Green)","color":"#2ea043"},{"key":"yellow","label":"DELAYED (Yellow)","color":"#d29922"},{"key":"red","label":"IMMEDIATE (Red)","color":"#c8102e"},{"key":"gray","label":"EXPECTANT (Gray)","color":"#8b949e"},{"key":"black","label":"DEAD (Black)","color":"#111111"}],"description":"SALT adds the hardest call in EMS: EXPECTANT. Read resources carefully — the same injury can be red or gray depending on what's available.","items":[{"id":"c07_dr01_01","prompt":"Walked to you; abrasions and a sprained wrist.","details":{"breathing":"Yes","obeys":"Yes","pulse":"Yes","distress":"No","bleeding":"None"},"answer":"green","why":"All YES with minor injuries = MINIMAL."},{"id":"c07_dr01_02","prompt":"Adult, still, apneic after airway opened.","details":{"breathing":"No (after airway)","age":"Adult"},"answer":"black","why":"Not breathing after airway opening = DEAD."},{"id":"c07_dr01_03","prompt":"Child, apneic → airway opened → 2 rescue breaths → now breathing, unresponsive, pulse present.","details":{"breathing":"Yes (after 2 breaths)","obeys":"No","pulse":"Yes","resources":"Adequate"},"answer":"red","why":"Any NO + likely survivable = IMMEDIATE."},{"id":"c07_dr01_04","prompt":"Open femur fracture, talking, bleeding controlled with pressure dressing.","details":{"breathing":"Yes","obeys":"Yes","pulse":"Yes","distress":"No","bleeding":"Controlled"},"answer":"yellow","why":"All YES, injury not minor = DELAYED."},{"id":"c07_dr01_05","prompt":"Arterial thigh bleed — you apply a tourniquet; bleeding stops. Alert, radial present, breathing easily.","details":{"breathing":"Yes","obeys":"Yes","pulse":"Yes","distress":"No","bleeding":"Controlled (TQ)"},"answer":"yellow","why":"After the LSI, all four are YES and injury is significant = DELAYED. Note TQ + time."},{"id":"c07_dr01_06","prompt":"Blast victim, severe respiratory distress, alert.","details":{"breathing":"Yes, labored","obeys":"Yes","pulse":"Yes","distress":"YES","resources":"Adequate"},"answer":"red","why":"Respiratory distress = a NO → IMMEDIATE if survivable."},{"id":"c07_dr01_07","prompt":"~90% full-thickness burns, unresponsive, weak pulse. 50 casualties, 3 ambulances.","details":{"breathing":"Shallow","obeys":"No","pulse":"Weak","resources":"Overwhelmed"},"answer":"gray","why":"Any NO + survival unlikely with CURRENT resources = EXPECTANT. Comfort care; re-triage later."},{"id":"c07_dr01_08","prompt":"Open skull fracture with exposed brain, agonal breathing. Mass-casualty, scarce resources.","details":{"breathing":"Agonal","obeys":"No","pulse":"Present","resources":"Scarce"},"answer":"gray","why":"Unsurvivable with current resources = EXPECTANT."},{"id":"c07_dr01_09","prompt":"Abdominal stab wound, alert, no radial pulse, breathing OK. Resources adequate.","details":{"breathing":"Yes","obeys":"Yes","pulse":"NO","distress":"No"},"answer":"red","why":"Absent peripheral pulse = NO → IMMEDIATE."},{"id":"c07_dr01_10","prompt":"Child, apneic after airway opening and 2 rescue breaths.","details":{"breathing":"No (after 2 breaths)","age":"Child"},"answer":"black","why":"Still apneic after 2 breaths = DEAD."},{"id":"c07_dr01_11","prompt":"Small lacerations; waved when asked; sitting because she's shaken.","details":{"breathing":"Yes","obeys":"Yes","pulse":"Yes","distress":"No","bleeding":"Minor"},"answer":"green","why":"All YES with minor injuries = MINIMAL (re-triage later)."},{"id":"c07_dr01_12","prompt":"Confused elderly man after the crash, won't follow commands, pulse present, no distress.","details":{"breathing":"Yes","obeys":"NO","pulse":"Yes","distress":"No","resources":"Adequate"},"answer":"red","why":"Doesn't obey commands = NO → IMMEDIATE."},{"id":"c07_dr01_13","prompt":"Same 90% burns patient as before — 2 hours later, 20 ambulances and burn center beds are available.","details":{"breathing":"Shallow","obeys":"No","pulse":"Weak","resources":"Now adequate"},"answer":"red","why":"Re-triage when resources change: Expectant can become IMMEDIATE."},{"id":"c07_dr01_14","prompt":"Nerve-agent exposure: pinpoint pupils, drooling, wheezing. You give an auto-injector; now breathing easier, obeys, pulse present, no distress.","details":{"breathing":"Yes","obeys":"Yes","pulse":"Yes","distress":"No (after antidote)","injuries":"Significant exposure"},"answer":"yellow","why":"After the LSI (auto-injector) all four YES; significant exposure, not minor → DELAYED. Re-triage often."}],"id":"c07_dr01"}]},"c08":{"chapter":"c08","drills":[{"title":"Where Does This One Go?","icon":"🚑","targetSeconds":12,"description":"You're Transport Officer. Central (Level I trauma, near, flooded with walk-ins), East (community, spare beds), Children's (pediatric, farther), Burn Center (40 min). Pick the best move.","items":[{"id":"c08_dr01_01","prompt":"Adult red, gunshot to the abdomen, weak radial pulse.","options":["Central (trauma center)","East community hospital","Bus with greens","Hold on scene for IV fluids"],"answer":0,"why":"Non-compressible torso hemorrhage needs a trauma surgeon."},{"id":"c08_dr01_02","prompt":"20 greens with bruises and small cuts.","options":["One per ambulance to Central","Bus with a medic to East (spare capacity)","Send them home","Hold until all reds are gone"],"answer":1,"why":"Move greens in bulk, away from the flooded trauma center."},{"id":"c08_dr01_03","prompt":"Yellow adult, closed tib fracture, stable.","options":["Central","East","Burn Center","Air medical"],"answer":1,"why":"Protect the trauma center's capacity for reds; East has beds."},{"id":"c08_dr01_04","prompt":"Red 6-year-old, stable airway, splenic injury suspected, 15 min to Children's.","options":["Children's (pediatric center)","East community hospital","Bus","Hold on scene"],"answer":0,"why":"Pediatric-capable center when the time cost is acceptable."},{"id":"c08_dr01_05","prompt":"Adult red with 40% burns and singed nasal hair, voice getting hoarse.","options":["Burn Center by ground (40 min)","Central — closest capable airway/trauma care now","East by bus","Mark expectant"],"answer":1,"why":"Threatened airway can't wait 40 min. Stabilize at the nearest capable center, transfer to burns later."},{"id":"c08_dr01_06","prompt":"Red patient + space for passengers in the same ambulance.","options":["Leave seats empty","Add 1–2 greens going to the same hospital","Add another red","Add the expectant patient"],"answer":1,"why":"Fill seats sensibly: 1 red + 1–2 greens (per policy)."},{"id":"c08_dr01_07","prompt":"Patient contaminated with an unknown liquid chemical.","options":["Load immediately","Decon first, then transport and notify hospital","Send by private car","Wrap in a blanket and load"],"answer":1,"why":"Decon before transport — a contaminated ambulance is out of service and its crew become patients."},{"id":"c08_dr01_08","prompt":"An ambulance crew wants to take 'their' patient to their usual hospital.","options":["Allow it","Transport Officer assigns destination per the plan","Let the patient decide","Let dispatch decide later"],"answer":1,"why":"Destination is assigned centrally to balance load and capability."},{"id":"c08_dr01_09","prompt":"Scene is 90 min by road from the only trauma center; red patient.","options":["Ground to trauma center","Air medical if available, LZ away from treatment area","Hold on scene","Bus"],"answer":1,"why":"Long distance + critical = air medical is worth the LZ cost."},{"id":"c08_dr01_10","prompt":"You don't know how many beds East has.","options":["Guess","Ask Med Comms/hospital coordination for capacity by color","Have each crew call East","Send everyone to Central"],"answer":1,"why":"One channel for hospital capacity."}],"id":"c08_dr01"}]},"c09":{"chapter":"c09","drills":[{"title":"Read the Hazard","icon":"☢️","targetSeconds":10,"description":"Placards, diamonds, the ERG, and PPE. Ten seconds each — you're reading through binoculars.","items":[{"id":"c09_dr01_01","prompt":"A placard shows hazard class 3.","options":["Flammable liquid","Corrosive","Radioactive","Explosive"],"answer":0,"why":"Class 3 = flammable liquids (e.g., gasoline)."},{"id":"c09_dr01_02","prompt":"A placard shows hazard class 7.","options":["Toxic","Radioactive","Oxidizer","Gas"],"answer":1,"why":"Class 7 = radioactive."},{"id":"c09_dr01_03","prompt":"A placard shows hazard class 8.","options":["Explosive","Corrosive","Flammable solid","Miscellaneous"],"answer":1,"why":"Class 8 = corrosives."},{"id":"c09_dr01_04","prompt":"You know the 4-digit UN number. Which ERG pages?","options":["Yellow","Blue","Green","White"],"answer":0,"why":"Yellow pages are sorted by ID number."},{"id":"c09_dr01_05","prompt":"You need the initial isolation distance for a toxic gas.","options":["Orange","Green","Blue","Yellow"],"answer":1,"why":"Green pages = isolation and protective action distances."},{"id":"c09_dr01_06","prompt":"NFPA diamond: the BLUE quadrant shows 4.","options":["Extremely flammable","Lethal health hazard","May detonate","Water-reactive"],"answer":1,"why":"Blue = health; 4 = can be lethal with short exposure."},{"id":"c09_dr01_07","prompt":"NFPA white quadrant shows 'W' with a line through it.","options":["Use water","Water-reactive — avoid water","Wear Level A","Waste material"],"answer":1,"why":"W̶ = reacts with water."},{"id":"c09_dr01_08","prompt":"Unknown vapor, entry team going into the hot zone.","options":["Level A","Level C","Level D","Surgical mask + gown"],"answer":0,"why":"Unknown vapor hazards require maximum skin + respiratory protection."},{"id":"c09_dr01_09","prompt":"Hospital decon team, agent known, oxygen normal.","options":["Level A","Level B","Level C","Level D"],"answer":2,"why":"Level C (APR/PAPR + splash suit) is typical for hospital/decon teams with known agents."},{"id":"c09_dr01_10","prompt":"Five people collapsed in a basement, no trauma, rotten-egg smell.","options":["Go in with a BVM","Do not approach — withdraw, report, request HazMat (Step 3)","Approach with caution (Step 2)","Ventilate the basement yourself"],"answer":1,"why":"3+ casualties unexplained = Step 3. Rotten egg suggests hydrogen sulfide — smell fades as it paralyzes olfaction."},{"id":"c09_dr01_11","prompt":"First and best decon step for 100 exposed people?","options":["Remove outer clothing","Bleach shower","Antibiotics","Wait for the HazMat team"],"answer":0,"why":"Disrobing removes most external contamination immediately."},{"id":"c09_dr01_12","prompt":"Exposure to a vapor only, patients asymptomatic, no visible liquid.","options":["Wet decon with scrubbing","Disrobe + dry decon","No action","Level A for patients"],"answer":1,"why":"Dry decon is the default for most exposures; wet for caustics/liquid/symptoms."}],"id":"c09_dr01"}]},"c10":{"chapter":"c10","drills":[{"title":"Name That Toxidrome","icon":"🧪","targetSeconds":12,"description":"Fast pattern recognition. Read the signs, pick the agent or the antidote. Wrong answer = wrong drug.","items":[{"id":"c10_dr01_01","prompt":"Pinpoint pupils, drooling, wheezing, twitching, vomiting.","options":["Nerve agent","Opioid","Cyanide","Chlorine"],"answer":0,"why":"Wet miosis + fasciculations = cholinergic crisis."},{"id":"c10_dr01_02","prompt":"Pinpoint pupils, RR 4, dry skin, no twitching, crowd in a theater.","options":["Nerve agent","Incapacitating opioid","Mustard","Riot agent"],"answer":1,"why":"Dry miosis + respiratory depression = opioid → naloxone."},{"id":"c10_dr01_03","prompt":"Fire victim, unresponsive, BP 70/40, SpO2 reads 99%.","options":["Hydroxocobalamin","Atropine","Pralidoxime","Naloxone"],"answer":0,"why":"Smoke + shock → cyanide (and CO). Hydroxocobalamin is the antidote."},{"id":"c10_dr01_04","prompt":"Yellow-green cloud, bleach smell, immediate burning eyes and stridor.","options":["Chlorine","Phosgene","Mustard","Sarin"],"answer":0,"why":"Highly water-soluble → immediate upper-airway irritation."},{"id":"c10_dr01_05","prompt":"'Smelled like cut hay', mild cough now; feels fine.","options":["Phosgene — observe 24 h","Riot agent — release","Cyanide — antidote now","Nerve agent — 3 kits"],"answer":0,"why":"Phosgene: delayed pulmonary edema 2–24 h. Rest and observe."},{"id":"c10_dr01_06","prompt":"Painless garlic-smelling oily liquid; red blistering skin appears 6 h later.","options":["Sulfur mustard","Lewisite","CS gas","Ammonia"],"answer":0,"why":"Mustard: painless exposure, delayed blisters. Decon immediately — no antidote."},{"id":"c10_dr01_07","prompt":"Immediate severe skin pain, geranium odor, blistering.","options":["Lewisite — BAL antidote","Mustard — no antidote","Phosgene","VX"],"answer":0,"why":"Lewisite hurts immediately; antidote is BAL (dimercaprol)."},{"id":"c10_dr01_08","prompt":"Protesters: tearing, burning skin, coughing; improving after 20 min in fresh air.","options":["Riot-control agent","Nerve agent","Cyanide","Phosgene"],"answer":0,"why":"CS/OC effects are immediate and self-limited after removal."},{"id":"c10_dr01_09","prompt":"Severe nerve-agent casualty, seizing. Kits?","options":["1","2","3 + benzodiazepine","0"],"answer":2,"why":"Severe = 3 kits rapidly + benzo + ventilatory support."},{"id":"c10_dr01_10","prompt":"Atropine has been given. Pulse 128, pupils still tiny, chest now clear and breathing easy. Next?","options":["More atropine until pupils dilate","Stop — endpoint reached (dry secretions, easy breathing)","More atropine until HR < 100","Give naloxone"],"answer":1,"why":"Titrate to secretions/breathing — tachycardia and miosis aren't the endpoint."},{"id":"c10_dr01_11","prompt":"Basement, rotten-egg smell that 'disappeared', 3 workers collapsed.","options":["Hydrogen sulfide — do not enter; SCBA only","Chlorine — enter with a mask","Phosgene — observe","Riot agent — fresh air"],"answer":0,"why":"H2S paralyzes smell at high concentration — a classic multiple-rescuer death scenario."},{"id":"c10_dr01_12","prompt":"Farmer after spraying crops: sweating, diarrhea, miosis, bradycardia.","options":["Organophosphate — atropine + pralidoxime","Cyanide — hydroxocobalamin","Opioid — naloxone","Heat stroke — cooling"],"answer":0,"why":"Organophosphate pesticides = same mechanism as nerve agents."}],"id":"c10_dr01"}]},"c11":{"chapter":"c11","drills":[{"title":"Contain It: Bio & Rad Decisions","icon":"🧬","targetSeconds":12,"description":"PPE, risk, and the right move for invisible threats. Wrong call = exposed crew or delayed care.","items":[{"id":"c11_dr01_01","prompt":"Suspected smallpox patient. Your respiratory protection?","options":["Surgical mask","Fit-tested N95 or PAPR","None","Level A"],"answer":1,"why":"Airborne + contact precautions."},{"id":"c11_dr01_02","prompt":"Inhalational anthrax patient. Precautions?","options":["Standard precautions","Airborne isolation","Level A suit","Quarantine the crew"],"answer":0,"why":"Anthrax is not transmitted person-to-person."},{"id":"c11_dr01_03","prompt":"Pneumonic plague, coughing blood.","options":["Standard only","Droplet precautions + mask the patient","No PPE needed","Level A"],"answer":1,"why":"Pneumonic plague spreads by respiratory droplets."},{"id":"c11_dr01_04","prompt":"Patient exposed to a hidden radiation source, no contamination. Risk to you?","options":["High — avoid touching","None — he is not radioactive","Moderate — use lead apron","Need KI first"],"answer":1,"why":"Exposure doesn't make a person radioactive."},{"id":"c11_dr01_05","prompt":"Contaminated dirty-bomb victim with arterial bleeding.","options":["Decon first","Tourniquet now, decon with care","Wait for survey","KI tablet"],"answer":1,"why":"Life threats first. Radiological contamination is rarely immediately dangerous."},{"id":"c11_dr01_06","prompt":"Best first decon step for radiological contamination?","options":["Remove clothing","Bleach scrub","Hair shaving","KI"],"answer":0,"why":"Disrobing removes most external contamination."},{"id":"c11_dr01_07","prompt":"You move from 1 m to 2 m from a source. Your dose rate becomes…","options":["½","¼","Same","Double"],"answer":1,"why":"Inverse-square law."},{"id":"c11_dr01_08","prompt":"Nuclear detonation nearby; public guidance?","options":["Drive away immediately","Get inside, stay inside, stay tuned","Go outside to look","Shelter in a car"],"answer":1,"why":"Shelter in the middle of a sturdy building/basement to avoid fallout."},{"id":"c11_dr01_09","prompt":"KI after a cesium dirty bomb?","options":["Yes, everyone","No — KI only protects against radioactive iodine","Only children","Only responders"],"answer":1,"why":"KI does nothing against cesium; it only blocks thyroid radioiodine uptake."},{"id":"c11_dr01_10","prompt":"Alert, afebrile adult: ptosis, double vision, can't swallow, weakness spreading down.","options":["Botulism","Smallpox","Anthrax","Plague"],"answer":0,"why":"Descending symmetric flaccid paralysis with a clear mind = botulism."},{"id":"c11_dr01_11","prompt":"White powder spilled from a letter onto a clerk's hands.","options":["Shake it off and sniff","Keep still, isolate area, wash hands with soap & water, call law enforcement/HazMat","Bleach the skin","Start antibiotics for all"],"answer":1,"why":"Contain, wash, notify. Prophylaxis only if testing indicates a threat."},{"id":"c11_dr01_12","prompt":"Vomiting began 20 minutes after radiation exposure.","options":["Low dose","High dose — priority ARS care","Contamination only","Not radiation related"],"answer":1,"why":"Early vomiting = high dose."}],"id":"c11_dr01"}]},"c12":{"chapter":"c12","drills":[{"title":"Which TECC Phase?","icon":"🎯","targetSeconds":8,"options":[{"key":"direct","label":"Direct Threat (HOT)","color":"#c8102e"},{"key":"indirect","label":"Indirect Threat (WARM)","color":"#d29922"},{"key":"evac","label":"Evacuation (COLD)","color":"#2ea043"}],"description":"Each action belongs to a phase. Do the right thing in the wrong zone and you become a casualty.","items":[{"id":"c12_dr01_01","prompt":"Applying a tourniquet 'high and tight' while rounds are still being fired.","answer":"direct","why":"Tourniquet is the only medical intervention in direct threat."},{"id":"c12_dr01_02","prompt":"Packing a groin (junctional) wound with hemostatic gauze in a cleared hallway.","answer":"indirect","why":"Junctional packing is warm-zone (indirect threat) care."},{"id":"c12_dr01_03","prompt":"Placing a vented chest seal under police escort.","answer":"indirect","why":"Respiration step of MARCH — indirect threat."},{"id":"c12_dr01_04","prompt":"Dragging a casualty behind a concrete pillar.","answer":"direct","why":"Moving to cover is direct-threat care."},{"id":"c12_dr01_05","prompt":"Reassessing tourniquet effectiveness and documenting time in the ambulance.","answer":"evac","why":"Reassessment and documentation continue during evacuation care."},{"id":"c12_dr01_06","prompt":"Needle decompression for suspected tension pneumothorax at the CCP.","answer":"indirect","why":"Decompression is indirect-threat (warm) care."},{"id":"c12_dr01_07","prompt":"Telling a wounded officer to apply his own tourniquet while staying in the fight.","answer":"direct","why":"Self-aid is emphasized under direct threat."},{"id":"c12_dr01_08","prompt":"Wrapping a casualty in a hypothermia blanket before moving to the CCP.","answer":"indirect","why":"Hypothermia prevention starts in indirect threat."},{"id":"c12_dr01_09","prompt":"Starting a second IV and advanced monitoring en route to the trauma center.","answer":"evac","why":"Advanced care belongs in evacuation."},{"id":"c12_dr01_10","prompt":"Placing an NPA and recovery position in an unconscious casualty in a cleared room.","answer":"indirect","why":"Airway management is deferred until indirect threat."},{"id":"c12_dr01_11","prompt":"Converting a hasty tourniquet to a pressure dressing when safe and time allows.","answer":"indirect","why":"TQ reassessment/conversion happens in indirect threat or later."}],"id":"c12_dr01"}]},"c13":{"chapter":"c13","drills":[{"title":"Special Ops Quick Calls","icon":"🏗️","targetSeconds":12,"description":"Collapse, crowds, crashes, and weather. Make the call that keeps your crew alive and your patient breathing.","items":[{"id":"c13_dr01_01","prompt":"Arm trapped for 4 hours under rubble; USAR ready to lift.","options":["Lift now","IV saline + monitor before release","LR after release","Ice the arm"],"answer":1,"why":"Fluids before freedom; prepare for hyperkalemia."},{"id":"c13_dr01_02","prompt":"Post-release ECG: peaked T waves, QRS widening.","options":["Calcium","Amiodarone","Adenosine","More lifting"],"answer":0,"why":"Calcium stabilizes the cardiac membrane in hyperkalemia."},{"id":"c13_dr01_03","prompt":"Crowd surge at a gate; people can't raise their arms.","options":["Push into the crowd","Stop inflow, open exits, extract from edges","Wait it out","Use a PA to tell people to push"],"answer":1,"why":"Relieve pressure first — compressive asphyxia kills fast."},{"id":"c13_dr01_04","prompt":"Train derailed under overhead catenary lines.","options":["Begin triage inside","Confirm power isolated before entering","Use ladders on the wires","Ignore — trains are diesel"],"answer":1,"why":"Isolate electrical power first."},{"id":"c13_dr01_05","prompt":"Water flowing across the road, ~30 cm deep, patient on the other side.","options":["Drive through","Wade across","Stop — request swift-water rescue / find another route","Rope yourself and swim"],"answer":2,"why":"~1 ft of moving water floats most cars. Turn around, don't drown."},{"id":"c13_dr01_06","prompt":"Collapsed marathon runner, temp 42 °C, confused.","options":["Transport now","Cold-water immersion on scene","Oral fluids","Paracetamol"],"answer":1,"why":"Cool first, transport second."},{"id":"c13_dr01_07","prompt":"Small aircraft crash with burning wreckage.","options":["Approach downwind","Approach upwind with respiratory protection","Walk through the debris field","Wait for media"],"answer":1,"why":"Upwind; burning composites release toxic fibers/gases."},{"id":"c13_dr01_08","prompt":"Lone 5-year-old at the green area; an adult says 'that's my nephew'.","options":["Hand him over","Verify identity per reunification protocol before release","Send the child home","Ignore"],"answer":1,"why":"Unaccompanied minors are released only to verified guardians."},{"id":"c13_dr01_09","prompt":"Coach crash: you've found 41 people; manifest says 44.","options":["Close the scene","Search for 3 missing (ejected, wandered, trapped)","Assume no-shows","Ask the media"],"answer":1,"why":"Closed incident — account for everyone on the manifest."},{"id":"c13_dr01_10","prompt":"Blackout day 2; home-ventilator battery at 10%.","options":["Advise waiting","Priority transport/power source now","Call tomorrow","Switch off alarms"],"answer":1,"why":"Technology-dependent patients become critical when power fails."}],"id":"c13_dr01"}]},"c14":{"chapter":"c14","drills":[{"title":"Close It Out Right","icon":"🏁","targetSeconds":10,"description":"The last ambulance is gone. Is the incident really over? Make the right call.","items":[{"id":"c14_dr01_01","prompt":"Tags 50, transported 45, dead 2, released 1. Close?","options":["Yes","No — 2 unaccounted; re-sweep and search","Yes, if the IC agrees","Ask the media"],"answer":1,"why":"50 − 48 = 2 missing. Reconcile before terminating."},{"id":"c14_dr01_02","prompt":"Last red patient just left. Release all 20 units?","options":["Yes, all at once","Release in phases; keep some for late finds/rehab","Keep all units overnight","Let crews decide"],"answer":1,"why":"Phased demobilization keeps capacity."},{"id":"c14_dr01_03","prompt":"Best timing for a hot wash?","options":["Before crews disperse, same day","Next month","Never","Only if things went badly"],"answer":0,"why":"Immediate, short, everyone present."},{"id":"c14_dr01_04","prompt":"Ambulance used for decon-zone patients at a chemical incident.","options":["Back in service now","Decontaminate before returning to service","Burn it","Air it out for 5 min"],"answer":1,"why":"Contaminated equipment endangers the next crew and patient."},{"id":"c14_dr01_05","prompt":"Crew member is quiet but says 'I'm fine'. You…","options":["Force them to describe it in detail","Check in (PFA), offer support, follow up later","Report them","Ignore"],"answer":1,"why":"Look, Listen, Link — offer, don't force."},{"id":"c14_dr01_06","prompt":"AAR finding: 'Staging was chaotic.' What makes it useful?","options":["Name someone to blame","Add a specific fix, an owner, and a deadline","Leave as is","Delete it"],"answer":1,"why":"Improvement plans need actions, owners, and dates."},{"id":"c14_dr01_07","prompt":"Firefighter changed 2 SCBA cylinders in heavy work.","options":["Keep going","Send to rehab (rest, fluids, vitals)","Go home","Third cylinder now"],"answer":1,"why":"Rehab trigger per NFPA 1584 guidance."},{"id":"c14_dr01_08","prompt":"Six weeks later, a medic has nightmares and is drinking heavily.","options":["It's normal, wait","Refer to professional and peer support","Discipline","Change shifts"],"answer":1,"why":"Persistent symptoms with functional impact need referral."}],"id":"c14_dr01"}]}}};
